/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230316-3","meetingId":"r05-c-budget","date":"2023年3月16日","dateIso":"2023-03-16","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を184件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年度品川区一般会計予算","agenda":"令和５年度品川区一般会計予算","exchanges":[{"speaker":"江野下委員","kind":"質問","question":"私からは、３６７ページ、いじめ防止対策費、３６９ページ、学校２０２０レガシー事業、３８３ページの登下校区域防犯カメラ維持管理費についてお伺いします。そして、防犯カメラの設置ですが、ご答弁では、令和３年度末で１６４町会、１,２７７台の設置、学校通学路へは２１２台の設置と伺い、設置から７年で更新、また、防犯カメラの設置後、１０年前より軽犯罪が５割減となり、貢献度が高いと伺いました。","respondent":"森学校施設担当課長","answer":"基本的には、捜査の関係上教えてはいただけないのですけれども、違う犯罪での確認というようなもの、大体月に３０件ほど警察からお問合せがある状況です。","id":"exchange-001"},{"speaker":"江野下委員","kind":"質問","question":"子どもたちへもごく僅かということで、安心しましたが、ほかの犯罪、月３０件ある、やはり多いように感じます。小学校、品川区内では３１校、義務教育学校６校、中学校９校ですから、一施設に４台程度になるのでしょうか。お答えください。","respondent":"森学校施設担当課長","answer":"２１２台の内訳ですけれども、委員ご指摘のとおり、１つの学校におよそ２台から５台程度整備されている状況です。","id":"exchange-002"},{"speaker":"江野下委員","kind":"質問・要望","question":"先日もご答弁で、町会・自治会には他区よりも多く支援をしているとも伺いました。町会・自治会へは防犯カメラ補助金を出していただいても、負担として約１台５万円、金額としては大きいと思います。子どもたちの登下校の安全のためにも、通学路や、また防犯ではありませんが、ヒヤリハット、重大な事故があった場所にさらなる拡充を要望しますが、いかがでしょうか。","respondent":"森学校施設担当課長","answer":"こちらの皆様の点検の結果、この場所に防犯カメラをつけたほうがいいという答申等が出された場合には、至急対応するようにしていきたいと、そのように考えてあります。","id":"exchange-003"},{"speaker":"江野下委員","kind":"質問","question":"ご答弁ありがとうあります。ぜひ検討していただければと思います。次に、学校２０２０レガシー事業のブラインドサッカー体験教室について伺います。その日本代表選手も在籍する、パペレシアル品川の皆さんを講師に迎えて、３月５日、２６日に、ブラインドサッカー体型教室が行われます。こちらの体験教室の内容、開催の回数、地域などもお知らせください。","respondent":"中谷指導課長","answer":"ブラインドサッカーですけれども、昨年度はコロナのためオンラインでの実施ということになっておりましたが、今年度につきましては、８年生を対象に、全ての生徒に対して、中学校９校、義務教育学校６校の１５校において、体験的な実施をすることができております。","id":"exchange-004"},{"speaker":"江野下委員","kind":"質問・要望","question":"８年生が全員体験できるということを確認できました。私もＰＴＡ時代に、車いすラグビー連盟の方をお迎えしたセミナーを開催して、車椅子体験をして、とてもスピード感があったり、楽しいスポーツなんだなと学んだ体験があります。体験からの学びは非常に重要だと考えます。ぜひ拡充した支援を要望しますが、いかがでしょうか。","respondent":"中谷指導課長","answer":"お話しいただいた車椅子ラグビーにつきましても、国際大会のご案内が東京都教育委員会からございまして、定期的にこういったご案内は学校に周知をさせていただいて、希望する学校が手を挙げていくということで、来年度も１つの小学校が観戦予定です。","id":"exchange-005"},{"speaker":"江野下委員","kind":"確認","question":"様々な体験の機会をご用意していただいて、このエスコートキッズですか、非常に子どもたちにとってはよい体験になると思います。私の子どもたちがお世話になっていた頃は、もう１０年前ぐらいですか、卵形で、防犯ブザーのストラップだけだったかなと記憶しています。この質問に当たり、知り合いのママ、お子さんにまもるっちを見せてもらい、機能なども確認しました。こちらについてお伺いします。","respondent":"矢部教育総合支援センター長","answer":"まもるっちの周知についてです。こちらにつきましては、目安箱の周知のときに、大体校長から朝会の際に目安箱の説明をするのですが、そのときに、まもるっちの相談機能についてもご説明をしています。","id":"exchange-006"},{"speaker":"江野下委員","kind":"質問・要望","question":"実際、私は２人のママだけでしたけれども、お子さんお二人は知っていると。ただ、１人はやはり「何、ＨＥＡＲＴＳって」と、保護者の方もやはり知らない方がいましたので、とてもいい機能だと思いますので、ぜひ周知の拡充を要望したいと思います。ですから、もう少しＨＥＡＲＴＳの相談機能の拡充というか、また、今までにどのような相談が子どもたちから寄せられていたか、お伺いします。","respondent":"矢部教育総合支援センター長","answer":"まもるっちの活用ですが、相談は全ていじめというわけでもございませんので、まず垣根というのですか、なるべくサッと大人に相談できるところがあるという１つの機関だと思ってもらえたらと考えています。","id":"exchange-007"},{"speaker":"江野下委員","kind":"質問・要望","question":"やはりいじめだけではなくて、子どもたちの小さな声、いろいろな悩みに対して対応していただいているということで、安心しました。体の悩みであったり、性の悩み、こういった友人関係の悩み以外にも答えが対応できるような相談機関というものもつくられる、開始されるようなので、ぜひ品川区でも、ＨＥＡＲＴＳ、もう少し相談員を増やすなり、そういった対応を要望しますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"検討します。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"順不同で伺います。公明党としても、特別支援学校に通う品川区民でありますので、歓迎しております。特別支援学校の生徒にも、通われている方にも拡充していただけるということで、この区立学校と同じく所得制限なしなのか、４月からスタートしていくということでよろしいのか、現段階でどれぐらいの人数がいらっしゃるのか、そのようなことをどのように把握していくのかというところを確認させてください。","respondent":"勝亦学務課長","answer":"具体的な支援の方法につきましては、現在情報収集等を行っておりまして、検討しています。対象になられる方は、概数として２００人から３００人程度が、区民の方で都立特別支援学校に通っていると、概数を把握しています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"漏れがないように確認していただきたいと思いますし、区立学校に通う皆さんは給食費を払わないという、そのような流れかと思いますけれども、都立でありますこの学校の方においては、そのお支払いの仕方など、そのようなものはどのようにお考えでしょうか。","respondent":"勝亦学務課長","answer":"所得制限なしで無償化というように考えてございまして、ただ、設置者が東京都となっていますので、区立の学校と同じ方法は取り得ないのかなと考えています。手法につきましても、具体的なものについてはこれから検討してまいりたいと考えています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"負担にならないように、保護者の方の負担にならないような、事務的な部分になると思いますけれども、しっかりご検討いただきまして、お願いしたいと思います。次に参ります。次に、教育相談事業費に関連いたしまして、学校制服の選択制について確認します。子どもたちの中での、ＬＧＢＴＱの方への配慮というところで、学校制服の選択制を認めてほしいという、そのような質問を取り上げてまいりました。","respondent":"矢部教育総合支援センター長","answer":"令和５年度、女子のスラックス着用など標準服の選択が可能な学校は、１５校中１４校です。１校につきましては、委員がおっしゃったようにセーラー服のことと、あと、今、校舎の建て替えをしておりまして、そのタイミングを見て一度に考えているということを聞いております。","id":"exchange-011"},{"speaker":"新妻委員","kind":"意見","question":"１５校中１４校ということで進んでまいりました。１校はセーラー服ということなのですね。やはり、そのセーラー服のところの保護者から、このことについてご相談がありました。進んできているとはいえ、自分が通っている学校の中で標準服の選択が認められていないということで、ぜひ進めてほしいけれども、なかなかそこが今は難しいというようなお話をいただいたということで、とても残念がっていました。","respondent":"矢部教育総合支援センター長","answer":"現在も個別対応はしておりまして、制服の標準服が嫌いだというお子さんについては、ズボンであっても、ジャージであっても登校させている事例もありますので、個別によく保護者や本人と相談をして対応するよう指導しております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。引き続き、また教育委員会としても、丁寧な対応をぜひよろしくお願いいたします。最後に、ＰＴＡについてお伺いします。新年度予算案の中に、ＰＴＡ活動支援ということで約１,０００万円の予算が計上されております。この内訳を教えてください。","respondent":"宮尾庶務課長","answer":"私から、ＰＴＡ活動支援経費１,０００万６,０００円の内訳についてご説明します。こちらは大きく３つの事業から構成されてあります。１つが、ＰＴＡの皆様の資質を高めていただくための研修会、こちらを開催していただく経費、３８０万９,０００円です。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問","question":"現在、コロナ禍の中でこの３年間、４年目になりますが、ＰＴＡの活動も大変変わってきたなと考えています。今後のＰＴＡの在り方として、これはＰＴＡ側のことでありますので、学校側がこうしてくださいということではないと思いますけれども、今後の考え方として、ＰＴＡの外部委託やＰＴＡの解散ということに対してどのようにお考えか、お伺いいたします。","respondent":"宮尾庶務課長","answer":"外部委託ですけれども、業務委託というものは、基本的に一定の、定例的な業務が一定量存在しまして、かつ、そういったお仕事が一定期間存続するということが基本前提になってこようかと思うのですが、これからＰＴＡが、委員から案内がありましたように。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"３６３ページ、学事制度検討経費、３７１ページ、不登校児童・生徒支援事業、３６４ページ、教育指導費に関わって、校則について伺います。学区の変更の検討をするとあるのです。報償費のほうを見ると、審議会は１０回、１２人の委員と。１２人の委員でそれを決めるということはなかなか重荷だなと思うのですけれども、どのように地域、卒業生など住民の意見を反映させるお考えなのか、伺いたいと思います。","respondent":"勝亦学務課長","answer":"区民の方のご意見の取り方については、具体的には今後検討していきたいと考えています。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"非常に地域の重要なことなので、そこは重要かなと思っているのです。ちょっと伺いたいのですが、数年前に小山小学校から後地小学校への学区変更がありましたけれども、その概要と、当時の変更理由について伺います。学区変更後に、地域や卒業生など住民からの反応はどのようなものだったのか、何かつかんでいる声がありましたらご紹介ください。","respondent":"勝亦学務課長","answer":"平成２８年から平成３０年まで行いました学事制度審議会の中でいただいた答申の中で、人口が増えているところは学区の変更を検討ということでございました。そういった中で、今委員がおっしゃられたように、小山小学校、後地小学校の学区のほうを変更いたしました。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"今年度もそれほど大きい差はないのではないかと思うのですけれども、このうち芳水小学校は大崎駅周辺の開発があり、御殿山小学校は北品川五丁目開発があり、第三日野小学校は目黒駅にツインタワーがドーンとできました。浜川小学校、城南小学校については、学区内の住民基本台帳上の児童・生徒数が増えた理由は何だと考えていらっしゃるのか、伺いたいと思います。","respondent":"勝亦学務課長","answer":"浜川小学校、城南小学校の人口増についてのお問合せです。いずれも、近年大規模な集合住宅ができたことによる人口増というように捉えてあります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"このまちづくりの問題です。先ほど紹介しましたように、区の再開発事業もかなり関わっていると思うのです。これによる局地的な人口の激増と、その偏在です。学区変更の検討を迫られることにもつながったと思うのです。このことについて、品川区教育委員会としては、まちづくり部門や企画などの部門の方々に何か思うところはないでしょうか。伺いたいと思います。","respondent":"勝亦学務課長","answer":"学校施設の整備につきましては、そういった開発の状況も踏まえて、可能な限り、ある施設の中で受け入れているところで、学校の教室の整備の計画等を立てているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"ないということで、何か開発はもう聖域というような感じです。私はこの検討、今回検討ですけれども、２点提案したいと思います。伺いますけれども、選択制の存廃も検討課題に入れるべきだと思いますが、いかがでしょうか。委員には、町会などからも当然委員の方が入ると思うのですけれども、検討委員会で選択制は見直すべきだ等の意見が出た場合は、区は検討課題に入れる考えがあるのでしょうか、伺います。","respondent":"勝亦学務課長","answer":"平成２８年度に行いました、前回の学事制度審議会の中で、学校選択制につきましては、その存在意義は認め、ブロック制から隣接選択制へと地域に密着した形で、存在意義があるという形で答申も出てあります。","id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"提案の２点目ですけれども、学級規模です。今回の検討ですが、先ほど３５人という記述もあると紹介しましたけれども、小・中学校の３０人学級を想定して検討する、あるいは少なくとも、最低でも中学校の３５人というものを、やはり想定して検討すべきではないでしょうか。その上で、国を待たずして、区の独自教員も充てて、区としてそれを実施するよう求めたいと思いますけれども、いかがでしょうか。","respondent":"勝亦学務課長","answer":"学級規模の考え方です。国において、現在、段階的に３５人学級の導入が進められてあります。そういった中で、今後３５人学級の整備が必要になってくるというところでの調査、検討を行う部分です。そういった意味で、３０人学級の想定は現在のところは予定してございません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、それはどうされるのかということはちょっと聞き逃してしまったので、後で教えてください。小人数学級ですけれども、やはりこれから求められる教育を考えた場合、あと世界の当然の流れになっているわけです。伺いますけれども、２０２１年度の小学校、中学校の不登校数を伺いたいと思います。今年度も残り僅かですが、２０２２年度の数字、傾向、どうなのか分かる範囲で伺いたいと思います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"中学校の３５人学級のお話ですけれども、今、法律の中では４０人学級というように定めがありますので、それにのっとって検討を進めてまいりたいと考えています。不登校の児童・生徒数です。昨年度、令和３年度、２０２１年度につきましては、小学生が２２２人、中学生が２７０人です。今年度につきましては、若干増加傾向です。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり増えています。かなり激増ですよね。そのような子どもが増えている事実を私は示しているものだと思うのです。ちょっと伺いたいのですけれども、これまでは給食費の納入が、このようなことがあったので、課題があったと思うのですが、４月から区立小・中学校で給食が無償になるということで、不登校ぎみの子どもが登校を希望した場合、きちんと給食を提供してあげるということは可能になるのでしょうか。","respondent":"勝亦学務課長","answer":"来年度から公費のほうで負担する中で、不登校の方、学校にいらっしゃらないものというような形での対応は取ってございません。在籍されている方の給食は、しっかり用意していきたいと考えています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"昨年秋の決算特別委員会で共産党がこのことを求めますと、区は、生徒指導提要の素案の中にも例示されているので、検討していきたいとご答弁されました。現時点でホームページで公開してる学校は、義務教育学校６校、小学校３１校、中学校９校ありますけれども、それぞれ何校ぐらいあるのでしょうか。これも公開するべきだと思うのですけれども、いかがでしょうか。以上３点伺います。","respondent":"矢部教育総合支援センター長","answer":"校則についてのお尋ねです。子どもたち同士が話し合っていくというようなこと、またアンケートも実践しておりますので、大事なことだと考えています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思います。少し前になってしまいますけれども、２０２０年度の予算特別委員会で、私、桜丘中学校の実践も紹介して、児童・生徒の意見を聞いて校則の見直しを求めたのですが、その際、品川区教育委員会が以下のように答弁しているのです。ただ時間もかかる。だとしたら、私は、こうした姿勢で子どもの考える力や自治の力が育つとはちょっと思えないのですけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"地域の方にご意見をいただいていると聞いておりますので、そのような事例を広げていければいいなと考えております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ルールを守ることも大切かもしれないですけれども、なぜこのルールなのだろうなと考えてもらいたい。どのようなルールがいいのだろうかということ、これをみんなで考えて変えていくと、その力を育てていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"私からは、３６７ページのいじめ防止対策費について、同じく３６７ページのいじめ防止プログラム経費について、同じく３６７ページの学校夜間電話対応経費について、３７７ページの学校職員について伺いたいと思います。初めに、３６７ページのいじめ等防止プログラム経費について伺います。そして、このバッジはどのように使用されているのでしょうか。その効果についてお知らせください。","respondent":"矢部教育総合支援センター長","answer":"いじめ根絶バッジのご質問だと認識しました。このバッジは全ての学校で、デザインをお子さんがつくったものを継承して、全てのお子さんたちが胸につけられるものです。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"生徒も、先生も使われているということでよろしいでしょうか。いじめは、大人でいうとハラスメントと言われ、事件にもつながっていくので、しっかりと取り組んでいただきたいと考えています。これは大人になっても同じなので、ぜひ授業等でも、チームや班をつくって意見を出し合い、１つのものをつくり上げるという方法も、多く授業に取り入れていただきたいと思うのですが、本区の考えをお知らせください。","respondent":"矢部教育総合支援センター長","answer":"様々な相談機関をご案内しているということ、また、スクールカウンセラーにつきましては、５年生と７年生全員に面接をしておりますので、１年間に１回ですが、そのようなことも取り組んで、自殺防止、またいじめの防止に努めております。","id":"exchange-027"},{"speaker":"松永委員","kind":"確認","question":"同じく３６７ページのいじめ根絶協議会について伺います。これまで８回、令和２年を除き、毎年行われてきたかと思いますが、この令和４年に行われた協議内容を確認させていただきました。このいじめ根絶協議会にはＨＥＡＲＴＳの皆さんはいらっしゃるのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ＨＥＡＲＴＳの活動につきましては、少しお時間いただいている間に調べます。いじめ根絶協議会につきましては、ＨＥＡＲＴＳの参加はあります。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問・要望","question":"これは３月１３日より、マスク着用は個人の判断に任せられるということですが、本区ではこのマスク着用について、給食等も含めてですけれども、どのように対応されるのでしょうか。現在課題となっている、ギフテッドの方々についてお伺いします。本区内には、そうしたお子さんはおられるのでしょうか。こうしたギフテッドのお子様について、本区の対応について、どのようにされているのかお知らせください。","respondent":"矢部教育総合支援センター長","answer":"来年につきましては、特別支援については特に強化しながら進めてまいりたいと考えておりますので、ギフテッドのお子さんも含めて、強化して推進してまいりたいと考えております。","id":"exchange-029"},{"speaker":"松永委員","kind":"確認","question":"先ほどの令和４年のいじめ根絶協議会の内容についてですが、ヤングケアラーの支援については先日確認させていただきましたので大丈夫です。今回、不登校について伺います。子どもたちが不登校になってしまった原因は、いじめ、虐待などが挙げられますが、そこで本区において、この不登校になってしまった子どもたちはどのくらいおられたのか、改めて伺いたいと思います。その原因についてお知らせください。","respondent":"矢部教育総合支援センター長","answer":"不登校の数と原因ですね。令和３年度は、小学生が２２２人、中学生が２７０人です。","id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"学校、家庭、本人の理由ということでございました。例えばＰＴＡにもそうした周知をしていただきたいと考えておりますが、いかがでしょうか。この地域の行事に参加すると、以前は通知表に書いていただけるというか、何か成果というか、このような子どもですよというように書いていただけるというお話を伺ったのですが、その辺について伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"通知表は学校が定めているので、何か決まりがあるわけではないです。褒めることを書いてあげるということで、子どもたちがとてもいいことをした場合、ぜひ書くというような認識でおりますので、地域で、例えばいろいろな活躍をされたお子さんであれば、当然記入になります。","id":"exchange-031"},{"speaker":"松永委員","kind":"質問","question":"３６７ページの学校夜間電話対応経費と、３７７ページの学校職員について伺いたいと思います。本区において、現在教員不足と言われておりますけれども、このことについて、もし欠員がなければいいのですが、そういった教員不足になっているとしたら、小学校、中学校、義務教育学校前期課程、義務教育学校後期課程を教えていただければと思います。","respondent":"中谷指導課長","answer":"現在の教員の欠員状況です。校種別に申し上げますと、小学校において８名、中学校において５名、義務教育学校前期課程が１名、義務教育学校後期課程が１名、合計しまして１５名というところになっております。","id":"exchange-032"},{"speaker":"松永委員","kind":"質問","question":"そうした欠員で、教育に影響は出ないのでしょうか。今後等の対策について、お知らせしていただければと思います。もう時間がないので、最後にこうした先生の募集について、どのように行われるのでしょうか。本区の考えをお知らせください。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"引き続きそのような取組を、進めてまいりたいと思います。ＨＥＡＲＴＳのほう、数字でお伝えできるものは、まもるっち４,８１１件を受けまして、そのうち相談に乗ったのが２８８件でございました。個人面談は、スクールカウンセラーのほうが５３０件、ＳＳＷのほうが１,３４３件です。","id":"exchange-033"},{"speaker":"澤田委員","kind":"質問","question":"本日は、３６９ページ、市民科・各教科充実経費、地域の歴史・文化学習、３６７ページ、いじめ等防止プログラム経費、３７３ページ、発達障害教育支援員配置について、順不同でお伺いいたします。市民科・各教科充実経費の中の地域の歴史・文化学習として、現在どのような取組を行っているのでしょうか。お教え願います。","respondent":"矢部教育総合支援センター長","answer":"こちらは地域の方をお招きして、地域理解を深めることを目的として、行っている事業です。区民まつりや地区運動会、地域交流会などでお世話になり、また、学校に地域の方を招聘して、まちのこれまでの歴史や文化などをご指導いただいている、そのような事業です。","id":"exchange-034"},{"speaker":"澤田委員","kind":"質問","question":"地域の方や町会長などをお招きして、お話を伺うということは分かりました。どなたが、またどのようにして、講師を選定していらっしゃるのでしょうか。お知らせください。","respondent":"矢部教育総合支援センター長","answer":"本区につきましては、学校の品川コミュニティ・スクールの中にコーディネーターという職の地域の方もいらっしゃって、その方たちからも情報を得ながら、講師を選定していると認識しております。","id":"exchange-035"},{"speaker":"澤田委員","kind":"意見","question":"さらにそれを後押しするように、歴史学者など研究者の方のお話を聞く機会というものもあってもいいのかなと考えますが、区としてのご見解をお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"あくまで地域の方、少なくとも区内の方にお願いしたいので、大学の方など、本当にたけた方がいらっしゃれば、ぜひお願いしたい事業です。","id":"exchange-036"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ研究者の方など、いい方がいらっしゃることを願いつつ、推し進めていただけたらと思います。オープンはまだ先ですが、市民科や社会科などの授業で、地域の歴史・文化学習として、例えば小学校在学中に一度は必ず品川歴史館に行くということはいかがでしょうか。リニューアル以前にも、品川歴史館へは学びに行かれていたのでしょうか。お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"当然令和６年度からも、活用は私たちも楽しみにしていますが、今現状、開催していないのですけれども、ホームページ上には、ペーパークラフトをダウンロードして自分で作成できるものや、動画なども入っておりまして、現状でも品川歴史館とは連携して。","id":"exchange-037"},{"speaker":"澤田委員","kind":"質問・要望","question":"地元を理解して歴史を学ぶという取組は、子どもたちにとってとてもいいと思いますので、今後ともぜひ推進していっていただきたいと思います。続きまして、３７３ページの発達障害教育支援員配置についてお伺いします。支援の必要な子どもたちをカバーし切れておらず、保護者が日中子どもを見守るために来ることはできないかと、学校側に求められるということも多々あるようです。お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"こちらにつきましてはモデルですが、今年度５校で実施してございまして、来年度はプラス１０校というように考えておりますので、来年度また、そちらもモデルですけれども、成果と課題を把握しまして、充実、定着できたらいいと今考えております。","id":"exchange-038"},{"speaker":"澤田委員","kind":"質問","question":"ぜひ、さらなる人員確保というか、子どもたちのためにも、どうぞよろしくお願いいたします。最後になりますが、３６７ページ、いじめ等防止プログラムについてお伺いします。区のいじめ防止のプログラムとして、ＣＡＰという、いじめ、虐待、体罰、誘拐、痴漢、性暴力など、様々な暴力から自分の心と体を守る、暴力防止のための予防教育プログラムが行われていますが、現在の実施状況をお知らせください。","respondent":"矢部教育総合支援センター長","answer":"委員がお話しのとおり、子どもたちが被害に遭わないということを前提に、全区内の区立学校の３年生を対象に実施しているものです。","id":"exchange-039"},{"speaker":"澤田委員","kind":"質問・要望","question":"私自身も、昨年子どもが通う小学校の勉強会でＣＡＰを受けた経験があり、疑似的に言葉の暴力などを体験することで、大変勉強になりました。ぜひ今後とも多くの保護者の方に受けていただき、理解を深めていただけますよう、拡充を要望いたします。現在小学校では、何校くらいが小動物を飼育していらっしゃるのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"現在、小学校で小動物を飼っている学校は、３７校中２２校です。","id":"exchange-040"},{"speaker":"澤田委員","kind":"質問","question":"まだ、十何校、１５校ぐらいですか、小動物を飼っていない学校があるようですけれども、ペットが禁止のマンションなども多く、なかなか小動物と触れ合う機会を持てない子どもたちも多くいますので、ぜひ、今まだ飼っていない小学校では、小動物の飼育を推奨していただければなと思うのですが、区としてのご見解をお伺いします。","respondent":"矢部教育総合支援センター長","answer":"小動物ではないかもしれませんけれども、金魚とか、メダカとか、ザリガニとか、蚕とか、そのような生き物についてはどこの学級でもやっていますので、ウサギやモルモットということでなければ、かなりの学校で定着している活動ではないかなと思っています。","id":"exchange-041"},{"speaker":"澤田委員","kind":"意見","question":"そうなのです。金魚とか、メダカとか、そのようなものもすごくいいのですけれども、ふわふわで生きている、心臓がトクトク動くというような、子どもたちはそのような動物を抱っこしたりで大分違ってくると思うので、そちらのほうもぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"教育費全般で、スピーキングテスト、まもるっち、学校図書館、がん教育、宗教２世等に関する配慮を伺います。スピーキングテストについて伺います。その周知は、子ども、保護者にされているのか伺います。今日は教育費なので、品川区教育委員会に伝えますが、自己情報の開示は権利であるという認識が、区全体で少し薄いかなと感じるときがありますが、周知がされていると期待して伺います。","respondent":"中谷指導課長","answer":"実施後には、自分の力を出すことができたというような声をいただいております。運営上に関して、特に問題があったというようなことは、１例を除いてございません。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"今からでも、品川区教育委員会は、入試にスピーキングテストを実施することについて、中止を求めてほしいと思います。次に行きます。まもるっちについて伺います。都立特別支援学校に通う区内在住の子どもも対象であるということを確認させてください。改善を求めますが、見解を伺います。現状の保護者や地域の方の参加状況を伺います。区立学校以外に通う子どもへの活用周知についても、併せて伺います。","respondent":"宮尾庶務課長","answer":"セーフティ教室に関するお尋ねですが、こちらは警察のご協力をお借りして、登下校中の安全管理方法などを学ぶ教室だと認識しています。参加状況等については、教育委員会のほうでは把握しておりませんが、学校の希望に応じて教室を開催していると聞いてあります。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"生活者ネットワークは、このチラシ作成について、ＫＤＤＩ主導ではなくて、品川区教育委員会と都がもっとＫＤＤＩに主張して改善を図るべきということはこれまでも求めてきました。改めて改善を求めるとともに、やはり２０１８年にも訴えましたが、まもるっちを所管するのは教育委員会にすべきと考えますが、見解を伺います。業者の選定や契約はプロポーザルなのかなど、伺いたいと思います。","respondent":"宮尾庶務課長、吉田品川図書館長","answer":"このように、いろいろなところで適宜連携、協力をしておりますので、所管を教育委員会に移すという考えはございません。それから減額の部分におきましては、図書館としては、現在週１５時間、運営支援業務委託で雇っているところですが、そこを１８時間に延長するように要求いたしましたけれども、区全体での調整の中で。","id":"exchange-045"},{"speaker":"田中委員","kind":"確認","question":"この増額がされて、学校図書司書の配置が増えたということではないということでしょうか。そこは確認させてください。現在、この状況は改善できたのでしょうか。子どもや教員の学びの深さも広がる図書司書配置を、５日間を５年、１０年スパンで実現すると区も示している中で、それを実現するための具体的なスケジュール、計画を立てるべきと考えますが、見解を伺います。","respondent":"吉田品川図書館長","answer":"学校司書につきまして、職員室においてインターネットを使える端末で調べをしている状況については、このまま継続してまいります。今後は利用状況を踏まえ、研究してまいるところです。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"今の学校図書司書配置も、２３区の中で下から２番目です。がん教育について伺います。生活者ネットワークは、これまで個人がワクチンの接種について判断できる情報提供を区に求めてきました。見解を伺います。ですから、注意書についての周知こそ必要だと考えますが、見解を伺います。がん教育という必要な学びであるからこそ、納得して選択することの重要性を伝えるべきではないでしょうか。見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"限られた時間の中で、医療の専門家からの話ですので、そのあと担任から、または養護教諭等から、きちんと配慮をして、しっかりおうちで判断、保護者と一緒に判断するような支援をしてまいりたいと考えております。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"医療の専門家も、こういった積極的な接種の促しなので危険だという話をしているのです。きちんと判断できることが必要だと思うので、ぜひそういったことがないように、当事者の子どもが声を上げにくい環境がつくられてしまうということは非常に問題だと思います。見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"この機会だけで全てを判断するというようには私どもは考えてございませんので、１つの知識として把握して、その後様々な、近くの関係者やご家族と相談して判断していただく、そのような力をつけていると認識しております。","id":"exchange-048"},{"speaker":"須貝委員","kind":"質問","question":"３６４ページ、教育指導費についてお聞きしたいと思います。品川区、現在小・中学校、公立学校ですが、教員の人事権、人件費も含めて、東京都教育長にその人事権等があります。毎年この品川区に、何名ぐらいの教員が入れ替わりで入っているのでしょうか。教えてください。教員の質についてです。","respondent":"中谷指導課長","answer":"一般教員のほうですけれども、こちらにつきましては、小学校のほうの新規採用が３７名、そして区外からの転入という形ですけれども、１０３名となっています。中学校が、新規採用２０名、区外からの転入が３３名いらっしゃるというような状況になっております。","id":"exchange-049"},{"speaker":"須貝委員","kind":"質問","question":"品川区からすれば、せっかく品川区に来られる教員の方がいるならば、Ａ、Ｂ、Ｃランクの教員の配属を希望したいわけですが、現実はＢ、Ｃランクの方を中心に、Ｄ、Ｅランクの方も、品川区で必要な条件を、品川区でこのような方が欲しいのだといっても、それにはなかなか応じてもらえず、逆に押しつけられてしまうような現状があると聞いておりますが、教えてください。","respondent":"中谷指導課長","answer":"教員には５つの柱ということで、能力を教職に必要な素養、学習指導、生徒指導、特別な支援を必要とする子どもへの対応、それからＩＣＴ活用、これが東京都教育委員会のほうから、今度の４月から、しっかり身につけさせてほしいということで案内が来ておりますので。","id":"exchange-050"},{"speaker":"須貝委員","kind":"質問・要望","question":"スキルを身につけさせるのではなくて、その前に、過去にどのような実績があったか、やはりいい人、子どもたちの教育ではないですか。このようなことをやっていていいのでしょうか。そうしたら、自分たちの目で見て、この人なら任せられるなという教員をやはり採用する、そのような姿勢が大事ではないですか、根本で。これは実際そろっているのですか、人数は。その辺についてもご見解をお聞かせください。","respondent":"中谷指導課長","answer":"固有教員のほうですけれども、こちらの採用についてはこれからも進めてまいりたいと考えています。役割としては、やはり一貫教育の推進役というところで、これからも続けていきたいと考えています。","id":"exchange-051"},{"speaker":"須貝委員","kind":"質問","question":"今３割から４割の方が、そのように保持しているというお話です。でも、教員の皆さんは、自分で希望を出せば、３年たつと品川区から出ていけるのです。３年たったら異動できる、では両方の免許を持っている方が品川区に来られて、３年たったら僕異動します、私異動しますと、そのようになってしまう。もう一生懸命やっているのに。その辺についてどうですか。","respondent":"中谷指導課長","answer":"例えば免許のお話ですけれども、１つの免許を持っていて、別の校種の免許を持っていないがために、全くそちらのほうの指導ができないということではないということは申し上げさせていただければと考えています。","id":"exchange-052"},{"speaker":"須貝委員","kind":"質問","question":"ですから、現実論、早急に、品川区が両方の免許を持っている方を義務教育学校に置かないと、これは法律違反になるのではないですかと、私はそのように思っていました。これ品川区で、精神疾患での病気休職者は何人いらっしゃるのですか。先ほど欠員というお話もありましたが、教員の離職者、それで欠員になるのでしょうが、何人いらっしゃるのですか。このような実態に対して、どのようにお考えでしょうか。","respondent":"中谷指導課長","answer":"病気休職をされていらっしゃる方ということで、今年度の２月１日現在のお話になりますが、病気休職を取られていらっしゃる方が２２名、そのうち精神に関することで休職をされている方が１９名という形になっております。","id":"exchange-053"},{"speaker":"須貝委員","kind":"意見","question":"公立学校は大変なのです。大変です。支援学級もある。そのような人も入ってくる。私立はほとんどないのです。そのように受け入れてくれるところが。だから、何もかも、地域とのつながりも教員のほうにかぶってくる。全部それにしてほしいです、本当は。本当に今日本の、特に公立学校のほうの大変さがあるので、私は非常に心配しているのですが、すみません、最後に何かご意見がありましたら言ってください。","respondent":"中谷指導課長","answer":"保護者の対応を、通常は勤務時間内にするのですけれども、勤務時間外に委託のほうで行うというようなこともよくできております。副校長補佐の配置によって、副校長先生の業務軽減をするということも考えております。これからも引き続きやってまいりたいと思います。","id":"exchange-054"},{"speaker":"せらく委員","kind":"質問","question":"３７１ページ、マイスクール運営費について、３７９ページ、学校システム運営費に関して質問します。学校システム運営費のほうで、学校ホームページ経費について、先ほどもご説明がありましたが、ＣＭＳの再構築委託があります。ホームページの仕様が大きく変わるのかなと思いますが、まずこちら、スケジュールを伺います。","respondent":"勝亦学務課長","answer":"ホームページのＣＭＳの変更につきまして、ご予算をいただきまして、来年度中、早い段階でこちらに取り組みまして、秋頃には新しいホームページを立ち上げて、その検証に入っていきたいと考えています。","id":"exchange-055"},{"speaker":"せらく委員","kind":"確認","question":"次に内容のことですけれども、学校ホームページに関しては、議事録を確認していると、以前にも、更新の頻度や表示メニューの項目の部分で学校ごとに違いがあるというようなご発言があり、さらにメニューの項目、順番もそれぞれ違うので、学校の比較がしづらいのではないかと発言を見て捉えました。内容をお知らせください。こちらは全ての区立学校が対象になりますか。伺います。","respondent":"勝亦学務課長","answer":"メニューの統一についても、学校の意見も聞きながら、できるだけ比較がしやすいようにしていきたいと考えています。失礼いたしました。対象については、全ての区立学校を対象とする予定です。失礼いたしました。","id":"exchange-056"},{"speaker":"せらく委員","kind":"確認","question":"メニューのほう統一していただくということで、比較がしやすくなると助かる保護者も多いと思います。更新方法についてですけれども、これまでは学校の職員の方が更新していたと、議事録でも少し確認できたのですが、今後の更新方法、または今まで難しかったところがこのように簡単になるなど、もし決まっているところがあればお知らせください。","respondent":"勝亦学務課長","answer":"それぞれ操作についても、操作性が難しいという部分がございましたので、通常の変更のメニューと簡単に更新ができるようなメニュー、それぞれ用意したいと考えています。","id":"exchange-057"},{"speaker":"せらく委員","kind":"質問","question":"今回の更新では、学校のふだんの生活なども分かるように、ある程度職員の方の更新マニュアルといいますか、職員が更新しやすいように、操作の面と、学校のホームページの運用の方向性までサポートする講習など、せっかくの機会なのでしたほうがいいかなと思うのですが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"今後の運用についてですけれども、まず、現在のホームページになかったヘルプデスクというものを設けまして、学校現場からの問合せ等に柔軟に対応できるようにしてまいりたいと考えています。","id":"exchange-058"},{"speaker":"せらく委員","kind":"質問・要望","question":"学校の様々な日常の活動が、インターネット上で確認できるといいと思います。在籍している生徒からは、少人数だから恥ずかしさがなく、自分の考えをたくさん発表できる、明確なルールがなく、自由だから通えたという明るい声と、もともとみらい学園、不登校特例校は、図書館だった施設をリニューアルした校舎なので、運動場がなく部活がないといった要望の声もありました。","respondent":"矢部教育総合支援センター長","answer":"全体指導というよりは個別指導になりまして、そのお子さん一人ひとりの進捗や心身の状態を鑑みまして、支援をしています。卒業に向けましても、昨年度は全て９年生、進路が決まってありますので、特例校と大きく差のない対応をしていると考えております。","id":"exchange-059"},{"speaker":"せらく委員","kind":"質問","question":"センター長、大変失礼しました。在籍校が別にあるというところで、例えば責任の所在をめぐるトラブルなどはありませんでしたでしょうか。職員も、元校長先生や教員免許を持つ経験者がいらっしゃるということですが、個別指導ということで、担任制のような形などはしていないのでしょうか。その辺りについて教えてください。","respondent":"矢部教育総合支援センター長","answer":"担任ですね、これはマイスクール五反田とマイスクール浜川とマイスクール八潮で少し違っていまして、マイスクール五反田、マイスクール浜川につきましては、担任というより、個別に来たお子さんについて、大体ＡさんだったらＢ先生というような形で、個別に対応している。","id":"exchange-060"},{"speaker":"せらく委員","kind":"質問・要望","question":"マイスクール、学年について最後に聞きたいと思うのですけれども、小学校１年生、２年生が対象となっていないというところで、そういったご相談も柔軟に対応していただきたいと考えています。浜川校が教室拡充ということですが、小学生のほうの不登校児童も増えてきていると思いますので、そちらのほうも見ていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"西村委員","kind":"質問","question":"３７７ページより、学校ＩＣＴ活用経費から情報リテラシー教育について伺ってまいります。昨今、飲食店での迷惑行為や不適切発言などがＳＮＳで拡散されまして、その多くが高校生を含む未成年の投稿でした。学校でのネットリテラシー教育について、改めて小学校と中学校でそれぞれどのように行われているのか教えてください。","respondent":"矢部教育総合支援センター長","answer":"８年生、９年生につきましても、課題に対する冷静な判断の仕方、社会との関わりと自分の役割と、社会マナーの習得、このような事柄で指導をしています。","id":"exchange-062"},{"speaker":"西村委員","kind":"意見","question":"今回、いろいろなニュースがあって恐ろしいなと私自身も思っているのが、この身元が特定されて、在籍する学校や無関係な在校生にも大きな迷惑がかかっているのが事実だと思っています。この日本のメディアリテラシー教育が世界に遅れを取っていると言われているのはなぜなのか、また、迷惑行為などが拡散される時代になってしまいまして、これからの教育に何が必要なのか、区の考えを改めてお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"先ほど市民科のお伝えをしましたが、社会科についても、家庭科でも指導することになっておりますけれども、数年たつと学習指導要領も変わり、市民科のほうは今の課題に適応する教科ですので、我々のほうもしっかり考えて。","id":"exchange-063"},{"speaker":"西村委員","kind":"質問・要望","question":"調べ学習や発表の際に、インターネット上の情報源を見ながら子どもが発表する機会があると思うのですが、このときに併せて、個人情報を公開しないことやインターネットの情報をうのみにしないこと、また、一度投稿した情報は完全に削除できないというようなことを教えていただきながら、使用の制限だけをするのではない、皆で話し合うような授業に取り組んでいただきたいと思いますが。","respondent":"矢部教育総合支援センター長","answer":"タイミングがすごく大事で、全体的に指導は当然ありますけれども、その都度使っていることや、その時と場合、また内容によって、その都度教員のほうが指導していくということは大変効果的だと考えております。","id":"exchange-064"},{"speaker":"西村委員","kind":"質問・要望","question":"昨今投稿しているのが１０代で、拡散しているのは、多くの方がインフルエンサーなどの大人であることも特徴だなと思っています。全児童にタブレットが配付されまして、一定期間が過ぎました。自宅でどのようなタブレットの活用がされているのか、閲覧が長過ぎる児童への指導や、家庭教育などを行っていることがあればお知らせいただきたいと思います。ご意見お聞かせください。","respondent":"勝亦学務課長","answer":"は家庭の中に学習アプリ等がありますので、そういった調べですとか、そういったアプリを使った学習に活用できるかなと考えています。","id":"exchange-065"},{"speaker":"西村委員","kind":"質問・要望","question":"スマートフォンなど、学校から配付されているタブレットではなくても、いろいろな方法があって、放課後の子どもたちの過ごし方は気になっているところですが、指導の限界もあるとは思うのですけれども、引き続き、ゲームやユーチューブを見過ぎという児童の場合、何かのアラームかなというような視点も私は持っていたいと思いますので、よく見てあげてほしいなと思います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"お手元のＧＩＧＡスクールの端末につきましては、全てＳＮＳですとか、ＬＩＮＥですとか、ツイッターとか、そういったものは使えないような仕様になってございまして、現状では、そういったＳＮＳ等は。学校はタブレットのほうを活用するということですが、生徒、中学生以上はスマートフォンの所持率が高いというふうに認識しています。スマホでのトラブルも、生活指導上上がってきたりしていますので、その都度指導しています。","id":"exchange-066"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３６３ページ、就学援助費、３６７ページ、教育相談事業費、３８５ページ、保健運営費についてお伺いいたします。１点目に、保健運営費についてお伺いいたします。例えば目の前で突然人が倒れるケースと、既に倒れているケースがありますが、心停止してからの１０分間が大切なので、すぐにＡＥＤを取りに行くことが求められています。","respondent":"勝亦学務課長","answer":"ＡＥＤの設置です。学校のほう、ＡＥＤにつきましては全校設置済みでございまして、さらに、５分以内にこういった対応ができるように、新たに追加配備を予定しているものです。","id":"exchange-067"},{"speaker":"横山委員","kind":"質問・要望","question":"子どもたちや保護者の方々に、ＡＥＤの適切な使用方法について定期的に伝えていただきたいということを要望いたしますが、研修等をやっていただいているということなので、教職員の方々は十分ご存じかと思うのですけれども、様々なケースがあるかと思いますので、品川区教育委員会のご見解をお聞かせください。２点目に行きます。教育相談事業費についてお伺いいたします。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"繰り返しになりますけれども、毎年、学校の中で、消防署の方ですとか普及協会の方に来ていただいて、研修を受けていただく、または個人で消防署に行っていただく、もしくは。３点目は、夜間の相談についてですが、これも盗撮以外全般だと思いますけれども、午前中に少し話題に出ていました、たくさん情報が載っている、各家庭に配らせていただいています相談機関の紹介ですが、ここでは。","id":"exchange-068"},{"speaker":"横山委員","kind":"質問","question":"夜間の相談のところについてですけれども、海外在住の相談員を活用しているＮＰＯの事例をご紹介します。ＮＰＯ法人「あなたのいばしょ」は、望まない孤独で苦しむ方に、２４時間のチャット相談で寄り添う活動をしています。３点目に、就学援助費についてお伺いいたします。はコロナ禍において、そうした機会を経験することができなかった児童・生徒の、当時の学年と現在の学年を簡単に教えてください。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"修学旅行も実施できませんでした。令和３年度につきましても、多くの５年生、６年生、７年生の移動教室が実施できない状況でございました。令和３年度につきましては、修学旅行は実施できているという状況です。令和３年度の修学旅行については、若干行けなかった学校もあります。訂正いたします。","id":"exchange-069"},{"speaker":"横山委員","kind":"質問・要望","question":"既に高校生以上のお子さんについては、来年度以降の話になってしまいますけれども、例えば二十歳の集いの式典などで、実行委員の実際の方々などの意見をお聞きしながら、当時、学友たちと過ごすことのできなかった貴重な時間を少しでも取り戻せるように、同窓会を開催する際の支援ですとか、区として何らかの予算を検討していただくなど、品川区教育委員会と他課と連携していただいて、検討というか。","respondent":"勝亦学務課長","answer":"集団で自然活動、歴史に触れていく移動教室、林間学校は、非常に貴重な機会です。品川区教育委員会といたしましては、できるだけ同じ仲間で行けるように、令和３年度につきましては、６年生、それから８年生につきまして、移動教室に行けなかった方に代替事業を実施しています。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３８３ページ、給食運営費、３６３ページ、学事制度検討経費からお伺いしてまいります。いよいよこの４月、新学期から、区内全ての小学校、中学校、義務教育学校において、開けやすく、ストローを使わずに直飲みしやすいＳｃｈｏｏｌ ＰＯＰというストローレス容器が導入されることを、昨年の決算特別委員会で確認させていただいたところです。続いての動きがありましたので、確認してまいります。","respondent":"勝亦学務課長","answer":"こちら、東京都で最近、令和４年の１２月に改訂が行われておりまして、今、委員がおっしゃっていただいた第２条のところに、容器のストローにおけるプラスチック削減をはじめとした、環境配慮の取組を積極的に実施している者という項目が追加されていると認識しています。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"しかし、持続可能な社会の実現が求められる今、単に価格だけではなくて、環境への配慮など都が目指すべき方向性からも、事業者を総合的に評価し、決定し、都内全域に学校給食におけるプラスチックストローの削減を波及させていくべきではないでしょうか。都内全域でやってください」ということを求めました。東京都教育長は次のように答弁しました。毎年、供給事業者の決定と割当ては、２月には決まります。","respondent":"勝亦学務課長","answer":"令和５年度の、品川区への牛乳の供給事業者は、雪印メグミルクになったと聞いてあります。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０１８年、プラスチックストロー削減を求める請願が全国で初めて品川区議会で提出されて、これも全会一致で採択して、東京都と雪印メグミルクに送付したことから、品川区から始まったこの全国的な運動ですが、最終的に、東京都の要領改正によって、都内全てで適用されるという決着になりました。ＳＤＧｓの理念だけではなくて環境教育の実践になるということは、これまで何度も確認しています。","respondent":"勝亦学務課長","answer":"こちらのＳｃｈｏｏｌ ＰＯＰへの容器の変更につきまして、雪印メグミルクから変更に当たって、開け方が変わったり、または、口を大きく開けるので異物が入ったりするというような懸念等々、いろいろご相談をいただいておりました。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひ活用していただいて、ＳＤＧｓの環境教育の実践として取り組んでいただきたいと思います。次に、学事制度審議会について伺います。ファミリー世帯向けのマンションが今後できるとすると、ますます教室が足りなくなってくる。２年前に改築されたばかりの城南小学校ですが、この夏休みに大規模な改修工事を行うと伺いましたが、どのような工事になるのかお知らせください。","respondent":"勝亦学務課長","answer":"令和５年度に向けまして、城南小学校の工事です。１階のメディアセンターにつきまして、教室に変更していく、それから、２階の英語ルーム、３階の算数少人数教室、こちらも普通教室に転用していく予定になってあります。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問","question":"３クラス分増やすということでしょうか。一足制も、先日文教委員会で、土足というか、上履きに履き替えない一足制の報告も、区内で３つ目、この城南小学校で導入されるというお話も伺いましたけれども、げた箱があったスペースも活用すると聞いています。最終的な教育委員会の決定を経て、その結果が反映されるのは何年度からの入学になるのか、現在分かる範囲で結構ですので、教えてください。","respondent":"勝亦学務課長","answer":"学事制度審議会につきましては、年度が改まりまして、予定といたしましては７月頃には最初の審議会を開催したいと考えています。具体的には、学識経験者の方お二人、区民の方７名、学校の代表２名という形で、１１名で構成していきたいと考えています。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区民、関係者の皆様が、お子様の将来を検討するに当たって、できるだけ影響が少ないというか、ショックも受けるでしょうし、影響が少ない形で、午前中の答弁でもありましたが、今、限られた資源の中でやっていくしかない、これはもうしょうがない話だと思うのですが、できるだけ影響が少ないような方法を常に模索していただきたいと思うのですけれども、この点、お考えをお聞かせください。","respondent":"勝亦学務課長","answer":"そういった意味では、地域の方のご意見等を伺いながら、また手法はこれから検討してまいりますが、パブリックコメントですとか、前回の学事制度審議会で行いましたように保護者の方や町会の方へのアンケート、そういった方法も考えられると思います。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"私は一昨年、昨年と、学校給食費とともに、それ以外の義務教育に係る費用である学用品や教材費、修学旅行費などの無償化を求めて質問いたしました。そこで、憲法２６条に「義務教育は、これを無償とする」とあるとおりに、給食費以外の学用品なども無償化することを求めますが、いかがでしょうか。学用品等を無償化することも、この理念に沿って行うべきだと思いますけれども、いかがでしょうか。","respondent":"勝亦学務課長","answer":"そういった意味で、個々人の手元に残るもの、それから、個人に還元される学用品については、引き続きご負担いただくべきものだと考えています。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問","question":"そういう授業料だけだということであれば、学校給食費の無償化の説明がつかなくなると思いますけれども、いかがでしょうか。","respondent":"勝亦学務課長","answer":"今回、給食費の無償化に関しましては、そういった中で、「新時代のしながわ」、子育て世帯の負担を軽減していく、「子育て・教育で選ばれるしながわ」をつくっていくのだという考えの下に、無償化を行っているです。","id":"exchange-078"},{"speaker":"おくの委員","kind":"質問","question":"憲法上の要請ではないけれども、「子育て・教育で選ばれるしながわ」をつくるという観点から、学校給食費は無償化したということですけれども、そういう視点であるならば、学用品等を無償化しない理由は一体どういうことになるのでしょうか、伺います。お伺いいたします。","respondent":"勝亦学務課長","answer":"支援の形もいろいろございまして、ご負担を軽減していく中で、給食費というものを無償化しようと考えたという判断です。","id":"exchange-079"},{"speaker":"おくの委員","kind":"質問","question":"私は、学校給食費、「子育て・教育で選ばれるしながわ」という同じ理念に立ちながら、それで、学校給食費にしろ学用品等にしろ、個人のものになるわけですよね。学用品等は有償のままという、その理由は何なのかとお伺いしたのですが、何か、今のではお答えになっていないように思われるのですが、いかがでしょうか。もう一度お答え願いたいと思うのですが。","respondent":"勝亦学務課長","answer":"子育ての方を支援していく、イコール全てを無償化にするという考え方ではないと考えています。ご支援の中で、まず給食費を無償化していくという考え方です。","id":"exchange-080"},{"speaker":"おくの委員","kind":"質問","question":"それに比べれば、１０億円、１２億円、こういう負担、大きな負担でもないというか、出せるお金だと思うのですけれども、そういう視点、他方で、家庭の負担は給食費と変わらない負担であるということからすると、やはり学校給食費を無償にするのだったら、あと同じような額を積み増して、学用品等を無償化するということを考えてもいいのではないかと思うのですけれども、いかがでしょうか。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"そういった中で、一歩踏み出すということで、体ですとか健康のベースとなる食、給食の無償化、こちらを品川区で進めていくという考え方です。学用品に関しましては、それぞれ、学年ですとか学校によって様々な形があります。通常、他の自治体では、漢字ドリルとか計算ドリルというのを私費で購入していることが多いのですけれども、本区におきましては、「ことのはノート」とか、社会科で「調べ・考え・社会をつくる」という参考資料、また、算数や理科。","id":"exchange-081"},{"speaker":"おくの委員","kind":"質問","question":"ほかにも少し無償化しているところがあるというご答弁だと思いますけれども、それでは、小・中学校に係る家庭の負担軽減を、さらに進めていく考えはないのか、あるのか、将来、これから先、その点をお伺いしたいと思います。いかがでしょうか。","respondent":"勝亦学務課長","answer":"今後につきましては、教育委員会、それから区全体の中で、支援の在り方について考えていく考えです。","id":"exchange-082"},{"speaker":"おくの委員","kind":"質問・要望","question":"義務教育の完全無償化を求めて、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"松澤委員","kind":"質問","question":"この相談体制の強化についてお聞きします。相談窓口の設置を図り、教職員の負担を軽減、専門家による迅速な対応を確保すると記載してありますが、これは、教職員が相談したとき、要は専門家が相談に乗って、心のケアというのですか、負担を軽減するものなのか、学校でトラブルが起こった際に、専門家がこれを全て解決するようになるのか、そこら辺が少し分からなかったので、ご説明をお願いします。","respondent":"宮尾庶務課長","answer":"基本的にはそのやりとりの中で解決に導いていくものですが、高度化・複雑化するいろいろな問題に迅速に、また的確に対応するために、我々事務局がさらに多角的なアドバイスをいただく必要があると考えまして、外部の専門機関と契約をすることで。","id":"exchange-084"},{"speaker":"松澤委員","kind":"質問","question":"分かりました。要は、多様な中で、教師のストレスというか、多分、本当に計り知れないわけではないですか。品川区では、お調べすると、ＨＥＡＲＴＳですかね、スクールソーシャルワーカーが、実際これは何人で、年間３６０時間の勤務時間をどのように割り振っているのか。重点措置として、年間１２０時間加算申請することができると書いてありましたが、実際そのようなケースがあったのか、教えてください。","respondent":"矢部教育総合支援センター長","answer":"品川区は派遣型の活用をしておりまして、日常の目安箱、アイシグナル、まもるっちなどの相談を受け、または学校、保護者、児童・生徒の要請に基づき、学校訪問、家庭訪問を実施して、関係機関が出席するケース会議などに参加している、そのような活動です。","id":"exchange-085"},{"speaker":"松澤委員","kind":"質問","question":"週４日で１,６００時間、６人が、それぞれ何かあったときに学校に行くということですね。お互い専門性の違い、そして機能を理解して役割を分担し、設置していくことで、子ども一人一人の生活の質、要はＱＯＬを高めていけるのではないでしょうか。ソーシャルワーカーを、今はＨＥＡＲＴＳにいらっしゃいますけれども、これからどんどん拡充していく、そういった取組についてのご見解をお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"少しずつここ数年、予算をつけていただきまして、広げているところです。ぱっと広げれば成果が出るとは思いませんので、一つずつ丁寧に対応しながら、どういう形がいいのかということで少しずつ広げていく、そんな予定です。","id":"exchange-086"},{"speaker":"松澤委員","kind":"質問","question":"今、福祉、医療につなげるというお話が少し出ましたけれども、例えば品川区では、そういうスクールソーシャルワーカーというのがどういうふうにつないでいくのか、その仕組みというのですかね、その仕事を少し詳しく教えてください。","respondent":"矢部教育総合支援センター長","answer":"様々なケースがあるのですが、特に不登校のお子さんの対応が多くなっています。","id":"exchange-087"},{"speaker":"松澤委員","kind":"質問","question":"私、少し思うことがありまして、自分の周りに起こったことなのですが、６年生の子どもが、要は毎日、嫌がらせに遭っているのですよね。そうすると、やはりその家庭に何かがあるかもしれないというのですかね。そういった意味も踏まえまして、さらに拡充といいますか、１校に１人ではないですけれども、そういった部分の幅広い拡充というのを、もう一度力強い答弁でお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"加害のお子様の話が出ましたけれども、実態は学校、またはその家庭の背景への支援について、心理面とか福祉面とか指導面、そういったことで、それぞれの立場のスタッフが共有して、子どもや保護者を支援していくと、そういうシステムですので。","id":"exchange-088"},{"speaker":"松澤委員","kind":"質問・要望","question":"スクールソーシャルワーカー、そしてスクールカウンセラー、養護教諭が担う役割というのを、お話のとおりしっかりと明確化して、それぞれの強みを生かしながら、協働して包括的に課題解決に取り組むことを再度要望しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは、３８３ページ、学校給食費無償化、そして、庶務課の学校運営費、３７３ページ、発達障害教育支援員配置についてお伺いします。続けます。私には区民から、この所得制限を給食費より先に撤廃してほしいというお声もあります。そちらについて見解をお聞かせください。東京都全体で支援していただきたいという要望を、何かの機会に区からもお伝えしていただきたいですが、見解をお聞かせください。","respondent":"勝亦学務課長","answer":"日常的にも区立学校との密な交流・連携はしていただいておりますけれども、こういった支援をしていく中でも連携・協力を仰いでいきたいと考えています。そういった中で、支援の拡充について、東京都への要望等についても検討していきたいと考えています。","id":"exchange-090"},{"speaker":"せお委員","kind":"質問・要望","question":"次に行きます。私は、２０２０年の予算特別委員会で、学校などで増えている人工芝がマイクロプラスチックとして海洋に流れ出ないよう対策をという趣旨の質問をしています。そちらの見解をお聞かせください。そのような課題が子どもたちの身近に起こっているわけですから、せっかくですから環境学習として、そういったことを取り入れていただけると分かりやすいかと思います。見解をお聞かせください。","respondent":"宮尾庶務課長","answer":"もちろん学校の規模と、それから敷地の形状ですとか、もろもろ状況が違うところはありますが、基本的な考え方としては、学校によって差が出ないように統一を図っているところです。","id":"exchange-091"},{"speaker":"せお委員","kind":"質問・要望","question":"環境の学習ですが、せっかく実物を見られるので、ぜひ取り入れていただきたいと思っています。最後に、発達障害教育支援員ですが、歳入でも触れたのですが、この支援員へは、２分の１の補助が東京都から出ています。この状況で東京都教育委員会は、いわゆる発達障害のお子さんに対してどのような支援を目指しているのでしょうか。どのようなビジョンなのか、ご存じのところがありまたら教えてください。","respondent":"矢部教育総合支援センター長","answer":"短い時間ですけれども、普通の通常の学級から１時間、２時間、引き上げてしまいますから、どうしてもそこのお勉強ができなくなるという課題もありますので、そういったことで１年間と捉えております。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３７１ページ、特別支援教育サポート経費、３７７ページ、教材教具費、３７９ページ、学校環境整備事業、この３つの中で順不同でお伺いしたいと思います。この費用について、例えば５年生は、年間、教材費として１万８０００円強ぐらいかかっているというところですが、現在、どれぐらいご負担いただいているのでしょうか。参考までに伺います。","respondent":"勝亦学務課長","answer":"大体その辺りが学校で負担している金額に当てはまるのかなというところで、小学校１年生ですと、教材費で大体１万円から２万円程度、中学生になりますと、２万円から３万円程度をご負担いただいている状況です。","id":"exchange-093"},{"speaker":"こんの委員","kind":"意見","question":"この教具に対してこのようなお声がありますので、ご紹介します。今、取り上げました教具ですけれども、小学校６年間の中で二、三年しか使用しないものもあります。これらの教具は個人教具としてではなくて、例えば学校の備品として、学校が購入する教材としていただいて、教材費の負担軽減をというお声があるのですが、こうしたお声について区のご見解をお聞かせください。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"そういった中で、今、ご案内に出ました個人が使っていくようなもの、色鉛筆ですとか、そういったものは、個人のものとして手元に残せるもの、もしくは個人に還元していくものは、ご負担いただくという考えに立っているものです。一例ですが、算数セットという、例えば時計が入っていたり、棒が入っていたり、タイルが入っていたりするものは、よく学校で一括して買ったり、また、前に使っていたものを１階の算数のお部屋に置いて、みんなで使っているということも。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。この報告書は、点検方法の改善や外部人材の活用も求めるとありまして、全国の公立小・中学校計１,２８２校にアンケート調査したところ、９７.８％の学校は、安全点検の点検表があると答えていたと載っておりました。現在、品川区においてこの点検はどのようにされていて、点検表というのはどういう状況になっているのですか。お伺いします。","respondent":"矢部教育総合支援センター長、森学校施設担当課長","answer":"月１回、安全点検の日がありますので、役割が教員は決まっていまして、トイレの人とか、自分の教室はやるのですけれども、あとは階段の人とか体育館の人と分かれていまして、そこを月１回点検して。庶務課では、建築基準法に基づきまして、年に１回、建物を点検しております。建物の内部、それから外装部もそうですし、それと遊具についてもチェックしております。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問","question":"この点検ですけれども、担任の先生がされるのでしょうか。それとも、これはきちんと専門家が点検するのか、その辺を教えてください。","respondent":"矢部教育総合支援センター長、森学校施設担当課長","answer":"学校のほうは教職員です。なおかつ我々も行って、再度点検を行い、状況によっては、そのまま工事へ移行したりしております。追加です。コミュニティ・スクールでは、委員の方々に、皆さんの目でも点検をということで、お願いしています。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問","question":"建物のほうは、いわゆる事業者等々の専門家の目というところですが、教職員の方の点検というのは、細かく点検表でこことあそことというふうに、いわゆる視点を持っての、そういう点検表ということでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"こんの委員","kind":"質問","question":"引き続きよろしくお願いいたします。次の質問に行きます。特別支援教育サポート経費に関連しまして、通級指導についてお聞きしたいと思います。現在、品川区では、既にこうした、いわゆる訪問指導という形で実施をしていると理解しておりますが、その理解でよろしいでしょうか。現在の指導体制と実施の状況もお知らせください。","respondent":"矢部教育総合支援センター長","answer":"そのような機能をしているところが特別支援教室で、そちらは拠点校と訪問校がございまして、拠点校に都の先生が配置されておりまして、その教員が、訪問校を週１回程度回って、そこのお子さんを指導すると、そのような形になっております。","id":"exchange-098"},{"speaker":"こんの委員","kind":"確認","question":"いわゆる保護者がお子さんをそこまで送迎しなければいけない、この負担を軽減するためにこうした措置を取っていく、いわゆる教員が学校へ出向いて指導をしていく環境を整えていくですけれども、そうすると、私の理解をまた確認したいのですが、それは品川区としてはもう既にしているという理解でよろしいのでしょうか。それとも、これからその体制を取るという状況なのでしょうか。確認させてください。","respondent":"矢部教育総合支援センター長","answer":"ただいまご説明いたしました特別支援教室につきましては、東京都の方針に基づいて、全ての小・中学校で品川区においては行っております。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"障害児を持つお子さんのお母様方からは、いろいろな細かいご要望をお受けいたしますが、一つには、教育というところでの、お母様方、保護者の、またお子さんが環境を変えずに、そのまま慣れたところで指導を受けられる、こうしたことが一番の、お子様にとっても保護者にとっても望みだというお声がありますので、どうか引き続きこの体制で、品川区の教育を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"芹澤委員","kind":"質問・要望","question":"３６７ページのいじめ防止対策費、３６９ページ、学校２０２０レガシー事業、時間があれば、３８３ページの学校維持管理費についてお伺いします。いじめ防止、自己肯定感のところをお伺いしたいと思います。区長の施政方針演説の中でも、区民の幸福、幸せをテーマに掲げていただいて、様々な施策の展開を図るとお話がありました。何か教育で展開があれば、まずその１点をお聞かせいただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"当初おっしゃった自己肯定感につきましては、日本人の奥ゆかしさなども言われておりますので、そこも大切にしながら育ててまいりたいと思います。小動物については、それらの活動の一つとして、様々な活動の中で、子どもたちのよりよい心の醸成を図っていきたいと考えております。","id":"exchange-101"},{"speaker":"芹澤委員","kind":"質問・要望","question":"関連してになりますが、オリンピック・パラリンピックについてもお伺いします。オリンピック・パラリンピックはもう終わってしまいましたけれども、まさにレガシーとして、残念ながら当時できなかった子どもたちのプロスポーツを見るという機会を、ぜひこれから拡大していっていただきたいと思いますが、ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"なので、そういった品川区内の貴重な施設を使いながら、子どもたちが感動を味わえる体験ができるようにということで、様々な情報を集めまして、またこれに加えまして、東京都教育委員会からのご案内も集めて、学校のほうに周知をして、参加を促していきたいと考えています。","id":"exchange-102"},{"speaker":"芹澤委員","kind":"質問・要望","question":"そこの費用をどうするのだという問題は出てくると思いますが、それも検討の一つだと思いますし、あとは、本当に今後の話ですが、アリーナが例えばこれからできるのであれば、それも一定程度、地域の貢献枠として、学校と連携した、スポーツに興味のない方々が体験できる、観戦できるというような施策をしていただければと思いますが、最後、ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"今、各学校にオリ・パラレガシーの予算がございまして、そういったものも活用しながら、スポーツを見ることができ、そして体験することもできるというプログラムを、既に実施している学校もありますので、そのよさを共有しながら、今回も。","id":"exchange-103"},{"speaker":"芹澤委員","kind":"質問","question":"最後に、学校維持管理費の中から人工芝について、今お話があったので、最後に伺いたいと思います。飲食がやはりできないというので、何かブルーシートとかを敷いたりするのですけれども、人工芝は進めながらも、これから、子どもたちがイベントをぜひ一緒に楽しむための設備費用というのも、ある程度学校のほうで予算化できないかなと思って、最後、ご意見をお聞かせください。","respondent":"森学校施設担当課長","answer":"人工芝のご質問です。委員のおっしゃるとおり、今後はこの人工芝と、お祭りであったりそういう集会と、どう一緒にやっていくかというのは課題になってくると思います。養生材等がいろいろありますので、その辺を踏まえながら、様々検討していきたいと考えています。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３６０ページの教育費全般に関わって、産休・育休代替が埋まらない教員不足について伺います。子どもたちの教育環境が整わない、深刻な事態だと思います。そこで伺います。産休・育休代替、または時間講師として補充できているのか伺います。日経新聞の調査では、欠員が夏休み明けに増えたということで報道しているのですけれども、品川区の状況を伺います。","respondent":"中谷指導課長","answer":"中学校につきましては、必要数が２２名、そのうち代替教員で補充済みのものが１９名、そのほかの時間講師等の任用はございませんで、未補充が３名という状況です。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"夏休み明けに欠員が増えたというところで、品川区の状況を伺ったので、それも分かればお答えいただきたいと思います。こうした状況の下で、文部科学省が事務連絡を出しました。区として加配を要望した人数と、実際に配置予定の人数を伺います。こうした仕組みも活用して、来年度は、年度当初から欠員が出ることがないようにしていただきたいと思いますが、いかがでしょうか。","respondent":"中谷指導課長","answer":"令和５年度の状況というところはまだ調整中なので、正確な数が出ないということをご承知おきいただければと思います。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"来年度はまだ精査中ということですが、そうすると、国が出した事務連絡で、加配を要望していないということなのか、伺います。","respondent":"中谷指導課長","answer":"こちらの制度としましては、本来ですと産休を取得される日にちが決まってから、代替教員の補充というところでしたけれども、それが前倒しになりまして、最大で４か月前に加配という形で、例えば担任をしていただいたり、少人数指導をしていただいたりという形でもって。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、取りまとめ途中ということですね。これを活用して、来年度、欠員が出ないようにしていっていただきたいと、これは強く要望しておきたいと思います。教員の多忙化解消と、一人一人の子どもに向き合える環境を保障するために、管理職と一般の教職員が話し合う場をつくって、学力テストや研修など不要不急の業務削減を求めますが、いかがでしょうか。","respondent":"中谷指導課長","answer":"その副校長補佐を配置する学校に、働き方改革推進部というのを設置していきたいと考えております。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"特別支援教室の教員についても欠員が出ていると聞いておりますので、伺いたいと思います。以前に質問した際、特別支援教室について補充の仕組みがなく、非常に課題だと区も認識しているということで、東京都に特別区として要望しているとのことでしたけれども、要望した結果はどうなったのか、欠員補充はできているのか、していただきたいと思いますが、いかがでしょうか。","respondent":"中谷指導課長","answer":"中学校についてはございません。２つ目としまして、私から特別区の室課長会で、こういった、今、欠員があるという状況に関して、ぜひ柔軟な対応をお願いしたいということを申し上げているところです。","id":"exchange-109"},{"speaker":"木村委員","kind":"質問・要望","question":"どうぞ頑張っていただきたいと思います。次に、この下にありますけれども、８３運動経費５５万円余ですけれども、継続して取り組んできているこの事業の経緯と、それから、これまでの成果をお聞かせください。そして、８３運動をさらに近隣区や都内で広げていくべきだと考えますけれども、他の自治体との関係や、また取組などはどのようになっているのか、お聞かせいただきたいと思います。","respondent":"宮尾庶務課長","answer":"近隣区等へ広げていくという考え方ですが、他の自治体での詳細な取組状況までは把握をできてございませんが、例えば先ほど申し上げた発起人の方が各地で講演に招かれたりするなど、運動は広がりを見せていると認識しています。","id":"exchange-110"},{"speaker":"木村委員","kind":"質問・要望","question":"最近は、学校が終わった後も、すまいるスクールや学習塾に通うなど、子どもの帰宅する時間が遅くなっているように見受けられます。地域でこのような子どもたちへの見守りをしていくにはどうすべきか、また時間のやりくり等ができないのか、お考えがあればお聞かせいただきたいと思います。","respondent":"宮尾庶務課長","answer":"前述いたしました８３運動をはじめ、８３運動といいますのは、個々のお力というのは小さいものですけれども、これが集まって地域の目として、その力を合わせて、大きな力で児童を見守っていければと考えています。","id":"exchange-111"},{"speaker":"木村委員","kind":"質問・要望","question":"３８３ページの一番上にありますけれども、学校維持管理費からの質問です。先日３月１日に埼玉県戸田市の中学校で、刃物を持った高校生が切りつける事件がありました。これからの対策等をお聞かせいただきたいと思います。万が一侵入された場合、どのように対処されるのでしょうか。中途半端ではなく本格的に行っていただきたいが、教育委員会としての宣言をいただきたいのですが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"マニュアルもご説明いたしますと、学校危機管理マニュアルというのがございまして、このたび見直しを進めました。学校の中で組織的な対応ができるとともに、万一の侵入に備え、不審者訓練を行って、児童・生徒の避難の仕方、職員の対応、警察との連携等を全校で確認しています。","id":"exchange-112"},{"speaker":"木村委員","kind":"意見","question":"このような事件が二度と起きないことを願い、次に移りたいと思います。次に、３８５ページの保健運営費からですけれども、新型コロナウイルスの対応で、３月１３日からマスクの着用が個人の判断となりました。現在、品川区における学校でのマスクの取扱いはどのようになっているのか、お聞かせください。卒業式や入学式の扱いなど、４月以降の取扱いなども、どのようになっているのかお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"卒業式ですが、今回は校歌等の歌唱時、歌うときには飛沫の飛散予防のためにマスク着用を基本としています。入学式等、また４月以降につきましては、国から通知が出る予定ですので、それを踏まえて対応してまいりたいと思います。","id":"exchange-113"},{"speaker":"小芝委員","kind":"質問","question":"私からは、３８７ページ、学校改築推進経費について、地域とつながる学校の在り方について質問いたします。改築の進捗状況にもよると思いますが、これまで学校改築をめぐって、地域の方への説明会が様々な学校で行われてきたと思いますが、学校の改築に当たりましてどのような声、期待の声もあったかと思いますが、教えていただければと思います。","respondent":"森学校施設担当課長","answer":"町会長をはじめとした地域の皆様のご意見を賜りながら、改築を進めているところです。説明会につきましては、計画説明会、工事説明会等を行いまして、保護者の皆様であったり、児童・生徒、それから近隣の皆様への説明等も、併せて行っているところです。","id":"exchange-114"},{"speaker":"小芝委員","kind":"質問","question":"その中で何か期待の声とか、そういったものはありましたでしょうか。","respondent":"森学校施設担当課長","answer":"期待の声というところは、大体どの改築につきましても、待っていましたというような、いい学校にしてくださいと、そのような声援のようなご意見はよく賜るところです。","id":"exchange-115"},{"speaker":"小芝委員","kind":"質問","question":"学校の改築では、地域とのつながりというのも恐らく意識されて、設計段階でもそういったものが反映されておるのではないのかなと思いますが、詳しいことが分からないので、そのあたりを教えていただければと思います。","respondent":"森学校施設担当課長","answer":"それで、そのまま伐採してしまうのはもったいないので、芽接ぎ、接ぎ木ということで、その木の枝を落として接いでいくということで、その木自体の遺伝子を残していくということをやってみたり、伐採してしまった木の材料を用いまして。","id":"exchange-116"},{"speaker":"小芝委員","kind":"質問・要望","question":"ここで、地域とのつながりのところで取り上げさせていただきたいのは、地域に根差して歴史をつくってきました伝統文化に携わる方々のことです。なかなかそういう方々と接する機会が少ない中で、子どもたちにこの品川区の歴史だとか、また伝統を教えてくれる貴重な存在でもあります。そのたたけない理由として、恐らく近隣住民への配慮もあるかなと思いますが、そのあたり、ぜひ教えていただければと思います。","respondent":"森学校施設担当課長","answer":"今後、地域の皆様の声から、防音壁を用いた防音室みたいなものが必要だ、あるいは学校教育の中で、防音室であったり無音室みたいなものが必要だということになれば、当然整備してまいりますけれども、今のところは教育課程の中でも。","id":"exchange-117"},{"speaker":"小芝委員","kind":"質問・要望","question":"理由については、なかなか遮音性が働かないような話も聞きましたので、理由については理解いたしました。先ほど答弁がありましたとおり、遮音性は今の段階ではなかなか難しいということでございましたが、伝統文化をその会だけに任せるのではなく、ぜひ、地域もそうですし、また行政、教育機関も一緒になって、伝統文化を守る取組を展開していただきたいと思いまして、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"たけうち委員","kind":"提案","question":"同じく３８３ページ、防災ヘルメット購入について伺いたいと思います。まもるっちについては、私は平成１７年、２００５年の第３回定例会の一般質問で、まもるっちの私立小学校等への拡充を提案し、その後、保護者からの要望が多かった中学生への拡充について、会派としても何度も求めてまいりましたが、私立等への拡充は実現しておりますけれども、中学生への拡大は実現に至っておりません。","respondent":"矢部教育総合支援センター長、宮尾庶務課長、勝亦学務課長","answer":"比較的軽度のところで、学校、または関係機関で対応して、いじめを防いでいると、解決に向けて進んでいると解釈しています。中学生になりますと、部活ですとか塾、それから、１人で外出する機会が、小学生に比べて格段に活動の場が広がるというところから。ヘルメットに関しまして、いざというときにかぶっていただくときに、なかなか取り回しが難しいという部分があります。","id":"exchange-119"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いじめに対しては分かりました。まもるっちについては分かりました。それから、ヘルメットも分かりました。東日本大震災のときに釜石の奇跡というのが非常に言われまして、子どもたちがやはり自主的に避難をするのが大事だよと言われた中で、品川区でも各学校で抜き打ちで避難訓練などが行われていたこともあったかと思うのですが、今の学校での避難訓練の現状を教えていただきたいと思います。","respondent":"矢部教育総合支援センター長、宮尾庶務課長","answer":"中学生の主張の内容ですけれども、各学校に戻りまして、生徒からしっかり報告をしていると聞いております。地域で守る意識を醸成する、例えば先ほど言った８３運動等も含めまして、総合的に児童の安全を確保していきたいと考えています。避難訓練のことですけれども、こちらは予告を大体してからやるのですが、予告なしという避難訓練は必ず入っておりますので。","id":"exchange-120"},{"speaker":"たけうち委員","kind":"提案","question":"分かりました。まもるっちについては、当初はやはりいろいろなところでの拡大が期待されておりました、近隣区にその特許的なものを売るだとかということもあっただろうし、活用していただこう、また、我々も提案してまいりましたが、独り暮らしの高齢者への対策だとか、いろいろなことに夢があったのですが、今はなかなか。以上をもちまして、終わらせていただきます。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"３６１ページ、委員会運営費、３７３ページ、特別支援学級整備、３８３ページ、学校給食費無償化、３８７ページ、学校改築推進経費です。３６１ページの委員会運営費に関連してですが、教育委員会は首長、区長からの独立性ということが、教育委員会の特性の一つと認識しております。これはどのような内容か、改めてご説明をお願いします。","respondent":"宮尾庶務課長","answer":"教育委員会は、区長部局から、今、委員からお話がありましたように、一定程度独立して、一定程度権限を有している、独立した機関であると認識しています。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"そのとおりですね。私もその認識でおります。教育委員会の責務、権能について、地方教育行政の組織及び運営に関する法律第２１条で、教育委員会の職務権限が定められています。その第１項について、改めてご説明をお願いします。","respondent":"宮尾庶務課長","answer":"地方教育行政の組織及び運営に関する法律第２１条には、教育委員会の職務権限ということが記されておりまして、具体的に１１項目の教育委員会が有する権限について、明記されているところです。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"確認","question":"しかし、議題として供された形跡の存在が確認できていません。この教育委員会の廃園問題は、デュープロセスとコンプライアンス違反の観点から、私は第３回定例会の一般質問や決算特別委員会において質問してきましたが、答弁は方針の決定というものでありました。これらは明らかに区長部局の決定と言えます。このような経緯について、教育委員でもある教育長の見解を伺います。","respondent":"宮尾庶務課長","answer":"伊藤幼稚園の廃園に関することにつきましては、今年度、教育委員会で２回ご審議いただきました。その中で様々な議論をいただきまして、教育委員会として承認をしたというものです。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"その審議は、条例をどうするとか、そういうのではなく、報告に関して審議をしたということだと受け止めています。この審議審査の前に、なぜ教育委員会事務局が教育委員の皆さんに、教育委員会の独占権限である地方教育行政の組織及び運営に関する法律第２１条第１項についてご説明し、そして、教育委員会で審議していない内容であり、どうしてこれを陳情審査できたのか、教育長のご見解をお伺いします。","respondent":"宮尾庶務課長","answer":"こちらにつきましては、先ほどの繰り返しになりますが、教育委員会で２回、案件としてご議論をいただいたということ、それから、陳情審査の際には、保育課長の説明に先立ちまして、私ども教育委員会事務局の学務課長からもきちんと説明をした上で。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということで、今までいろいろお答えを伺ったのですが、私としては明らかにコンプライアンス違反であり、ほかにこのようなことが生じていないか、全庁でチェックが必要と考えます。この幼稚園の廃園に関しては、東京都に報告することになっていると思うのですが、それは、教育委員会の議決、議会の議決がないのに、東京都に報告しているのでしょうか。それを伺います。","respondent":"宮尾庶務課長","answer":"今後、廃園の時期から見まして適切な時期に、教育委員会で条例の改正の審議というのは当然に行うと認識しています。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問","question":"東京都に報告していないと受け取ってよろしいのでしょうか。","respondent":"勝亦学務課長","answer":"廃止について条例が決定しておりませんので、報告等はまだ行っておりません。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、しっかりとした過程で幼稚園の廃園がやはり決まっていないという、コンプライアンスに関することに私は疑問を感じています。この話は、また機会があったら改めて、できたらやりたいと思います。令和６年度に開設されます。ただ、先ほどもいろいろありましたけれども、先生方ですね、教員の確保・養成について、教育委員会として現在どういう準備をしているか、その状況を伺います。","respondent":"矢部教育総合支援センター長","answer":"小学校の免許を持った先生をということで、都の教員を配置するよう、指導課と連携して、今、配置に向けて進めています。ただ、在籍するお子さんの数に関わりますので、今それぞれ連携して進めているところです。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"十分に準備をしていただきたいと思います。そして、特別支援学級、あるいは教室の経験者で指導力の高い先生方を、異動で確保しております。その中には多数の品川区の教員が含まれていて、管理職を含めれば５人の先生が、こちらの学校に異動しています。逆に言うと、そういった形で指導教員を品川区は確保して、６年度に向けてやっていけるのでしょうか。その準備について先ほど伺ったのです。","respondent":"中谷指導課長","answer":"令和６年からのスタートになりますが、当然、おっしゃっていただいているとおり、令和５年度からの準備が必須と考えていますので、現在から、教員の専門性を持つ方の確保というところで動いて、やらせていただいております。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"意見","question":"非常に経験豊かな管理職の方々、そして、経験豊かな先生方が、言葉は失礼ですけれども、他区に流出してしまったというところがあると思います。ということは、令和５年度にどれぐらいの方が応募してきて、その準備をやっていただけるのか、私は非常に不安です。その志、情緒をつくるというのはすばらしいことなのですが、その人材確保について、もう一度どのような決意で進めるか、お願いします。","respondent":"中谷指導課長","answer":"現在から、次年度の教員配置で、特に今おっしゃっていただいた転入というところにつきましては、例えば特別支援教育に特化して、東京都の代表として研究された方をお迎えできるような要望を出させていただいたり、実際に他区で、品川区で経験されたのと同様に。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は予算書３６７ページ教育指導費、教育相談事業費からしつけについて、３６９ページ特色ある教育活動経費から蝶の道プロジェクトについて、３８５ページ学校管理費、保健運営費からブコラムとエピペンについて順不同にお伺いしてまいりますので、よろしくお願いいたします。ブコラムについてお伺いします。実際品川区の学校でブコラムを使用した事例があったかどうか、併せてご説明をお願いいたします。","respondent":"勝亦学務課長","answer":"従来てんかん発作時は、学校での緊急対応は座薬の挿入でしたが、座薬であるため投与が難しい面もございました。口から投与できるブコラムが承認されたことにより、緊急時の投与がより迅速に対応できるようになるものと認識しております。","id":"exchange-131"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ブコラムについて。学校等で生徒がけいれんを起こし、発作が５分以上続くとき、プラスチックのシリンジを口の中の歯ぐきとそれから頬の間に注入します。効果は即効性であり、ほとんどのケースで５分以内に発作が止まると言われています。これに関連して、同じように教職員が注射可能なアナフィラキシー対応のアドレナリン自己注射エピペンに関してもお尋ねします。","respondent":"勝亦学務課長","answer":"大事には至っておりません。現在、エピペンを携帯している児童・生徒に関しましては約２３０人おりますけれども、今年度エピペンの投与実績はございませんでした。","id":"exchange-132"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ご報告ありがとうあります。歳入でも質疑しましたが、２００８年頃、品川区で環境課を中心に蝶の道プロジェクトが行われ、区内小・中学校も数校このプロジェクトに参加し、チョウの食草を栽培し、チョウの飼育が行われたとお聞きしております。その後現在まで、区内の小・中学校でチョウの食草の栽培とかチョウの飼育などが現在も行われているか、そういう学校があるかどうかお伺いしたいと思います。","respondent":"勝亦学務課長","answer":"最近まで鮫浜小学校ではチョウの食草の栽培が継続されておりましたが、改築工事となりましたので、休止となったと聞いてあります。しかしながら今年度、校庭や外構の整備が終了いたしまして、来年度からチョウの食草栽培を再開する予定となっております。","id":"exchange-133"},{"speaker":"鈴木（博）委員","kind":"質問","question":"はいろいろと自然保護、チョウに関する活動が続いているということをお聞きしまして、非常に喜ばしい限りだと思います。これは非常にすばらしい取組であったと高く評価しておりますので、ぜひ今後も小・中学校も含めて、再開と活動の輪を広げるように希望いたします。これに関してはいかがでしょうか。","respondent":"勝亦学務課長","answer":"こちらは特色ある教育活動の中で予算を組み実施をしています。チョウをはじめとしまして、生き物との関わりを自然の中で体験していくことにつきましては非常に意義のある活動だと考えています。","id":"exchange-134"},{"speaker":"鈴木（博）委員","kind":"質問","question":"非常に期待しております。できたら私も参加したいと思います。次に、しつけ教育について伺います。複数の外食チェーン店で客の青少年が迷惑行為を行い、しょうゆ瓶や湯飲みをなめ回したり、回転レーンで流れてくる寿司につばをつけたりする動画がＳＮＳ上で拡散され、大きな社会問題となりました。品川区のご見解はいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"規範意識や食べ物を大切にする気持ちなどは、家庭での指導を中心に毎日の積み重ねが肝要と捉えております。委員ご指摘のような事例に結びつかないように、学校においても引き続き力を入れて指導してまいりたいと考えております。","id":"exchange-135"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区の教育でも、ぜひ自己肯定感を高めるようないろいろなその取組を積極的にしていただけるようにお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、３８３ページの学校給食費の無償化について伺いたいと思います。これは区立小・中学校だけでなく、特別支援学校については前向きにやる方向で検討するということですが、私立の小学校に通う子どもも含めて、品川のすべての子どもの給食費無償化を求めて質問したいと思います。","respondent":"勝亦学務課長","answer":"特別支援学校に通われている方、２００人から３００人と把握しています。私立・国立・都立に通われている方、こちらの方が大体５,０００人程度と見てあります。申し訳ございません、小・中学校の別については、現状数字を把握してございません。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"なぜ今回区立の小・中学校に限定したのか伺いたいと思います。それから加えて、私立・国立も含めて給食費の無償化もすべての子ども、すべての子育て家庭を対象にすべきではないかと思いますが、いかがでしょうかということです。そういうところからしても、私立に通うということも保障されるべきものだということです。それなので、すべての子どもを対象にすべきだと思いますが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"なぜ今回区立学校の無償化なのかです。区教育委員会といたしましては、まず所管をしております区立学校、こちらの給食について事務処理、予算等を行っておりますので、そちらのほうは教育委員会としてまず無償化ができるものとして、実施しているものです。","id":"exchange-138"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"所管のところはそうだということなので、品川区としてどう考えるかというところはどうでしょうかというのを、どこになるのでしょうか、伺いたいと思います。それから、すべての小・中学生の子ども、そのすべての子育て家庭を対象に実施するとなると、課題があるのか。あったらその課題ついても伺いたいと思います。","respondent":"勝亦学務課長","answer":"委員がおっしゃったように所得制限なしでという部分はありますけれども、まず区教育委員会としては区立学校のほうを所管しているという部分で、私立、国立、都立といった部分につきましては、そういった中で設置者の違う学校を選び取っていただいているという部分で。","id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"教育委員会は所管するところがそうなのでということですけれども、私立とか特別支援学校の教育というのは、ではどこになるのですか。そこのところをこのように無償化すべきだということを答えていただけるところはどこになるのでしょうか。","respondent":"勝亦学務課長","answer":"都立特別支援学校については都立、私立についても基本的には東京都が情報集約、所管しているものと考えております。","id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それでも品川区の子どもたちではないですか。では都立の特別支援学校に行っている子どもたちや私立の子どもたちをこの品川区ではどうするかということは、話し合う場所がないということですか。そこのところを伺いたいと思っているので、区としての考え方をどのように考えるべきかというところを伺っているので、企画のところでも結構ですのでお聞かせください。区長でもお聞かせいただけたらと思います。","respondent":"勝亦学務課長","answer":"そういった中で、都立特別支援学校につきましては、入学の際に区との就学相談を行っていたり、学校の中で交流しているということで、今回対象とさせていただいたです。","id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"企画部になるのですか、どこも答えていただけないのでしょうか。ここは、私はぜひとも「すべての」と区長がこれだけ強調しているわけですから、すべての子どもたちにすべきだということを実現していきたいし、特別支援学校もやる方向でと言っているわけですから、そこのところも。では、まもるっちは私立の子どもたちにも行っていると思うのですけれども、それはどういう経過で実現したのでしょうか。","respondent":"勝亦学務課長","answer":"それ以外の私立等々につきましては、また今後の研究の課題なのかなとは考えてありますけれども、まもるっちの経緯については所管ではございませんので、経緯はこちらのほうではお答えしかねる部分がありますけれども。","id":"exchange-142"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"はということで研究課題ということですけれども、これだけすべての子どもたち、すべての子育て家庭ということで区長自らが強調して言われているわけですから、ぜひとも区長のほうからも、すべての子どもたち、すべての子育て家庭、こういうことで実現の方向にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"予算では中学校２校ということで、また新たに増設されるということです。操作も非常に簡易で、また色の調整とか光の具合も手元でデジタルで大変操作しやすいというところで、少し早いですけれども、来年度は中学校の２校というところで、ぜひまた令和６年度以降、しっかりとペースを進めていただきたい、保護者、また児童・生徒の思いに応えてほしいという意味で、要望も含めてお聞きいたします。","respondent":"矢部教育総合支援センター長、森学校施設担当課長","answer":"課題につきましては、やはり人材の確保ということで、どなたでもいいということではございませんので、きちんと対応してくださる方とか、お子さんとその支援員とのマッチングもありますので、その辺りは課題かと捉えております。委員からご案内のありました舞台照明のＬＥＤ化ですけれども、今年度小学校２校、来年度は中学校２校を実施する予定です。小学校では実施いたしました。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問","question":"発達障害に関するところは、要するにこの１年間、５校で１０名の方が配置されて、その５校については学習支援員と介助員が同時にいらっしゃる。ここをしっかりモデルという意味では検証して１年間見て、また次年度は１０校に増やしてと。これもいわゆるモデルという言葉使いが先ほどありましたけれども、この１年間、この５校でこの３者、これの評価をお聞きしたという意味です。","respondent":"矢部教育総合支援センター長","answer":"ただ、学校によってはやはり１人１日いても、Ａさん、Ｂさんと対応していくうちに、やはり十分な人数ではないというご意見をいただいて、学習支援員を配置したという学校がありますので、基本的には今回配置する１０校につきましては、学習支援員。","id":"exchange-145"},{"speaker":"若林委員","kind":"提案","question":"こういった心理士、また福祉、教育の専門家が集まって、例えばこの特別支援教育というのは一人一人のニーズに合ったということがまくら言葉にあるわけですが、そこが一番大きな目的なわけですから、いわゆるチームとしてしっかりと機能して、例えばＡ君、Ｂさん、Ｃ君、それぞれのケーススタディというかそういうことを行って、一人一人のニーズに合った教育を施していくということが。","respondent":"矢部教育総合支援センター長","answer":"学習支援員、介助員は、どうしてもなかなか担任と接点がとれない、その場にいられない場合もありますので、ノート等の交換で情報共有をしているです。これからも進めてまいります。","id":"exchange-146"},{"speaker":"若林委員","kind":"質問・要望","question":"基本的には学習支援員と介助員はこれから配置を控えていくという一つの方向はお聞きしておりますけれども、先ほど申し上げましたように品川区の強みをしっかり生かしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"本日は３６１ページ学校職員被服貸与費、３７３ページ教職員被服貸与費、３６７ページいじめ防止対策費について伺います。最初に学校職員被服貸与費、教職員被服貸与費について伺います。一方、教職員の被服貸与費については、令和３年度が約６６０万円、令和４年度が約７００万円に対して、今回の令和５年度が約１５０万円ということで大幅に減っているようです。","respondent":"中谷指導課長","answer":"令和５年度は安全靴のみの購入という予算立てをしております。背景としましては、安全靴以外の品物の在庫が非常にあるというところを確認したことによる減額というものになります。","id":"exchange-148"},{"speaker":"松本委員","kind":"質問","question":"防災の関係ということなので、そこは納得できるかなと思います。ほかの区だとよく問題になるのが、トレーニングウエア、運動着の関係とかです。この辺りについては、当区の場合は貸与はしていないという理解でよろしいのでしょうか。","respondent":"宮尾庶務課長","answer":"教職員につきましては、先ほどご答弁させていただいたとおり、防災服のみということになります。","id":"exchange-149"},{"speaker":"松本委員","kind":"確認","question":"しかも選ぶのも自分たちで好きなものを選ぶというような話がありましたので、当区の場合はどうなっているのかというところで確認させていただきました。この規程を読むと、職務の執行上必要な被服の貸与について、必要な事項についてはこの規程の中に定めはなくて、別に教育次長が定めるというふうになっております。なので、ここの部分はしっかりと定めていただければと思いますが、いかがでしょうか。","respondent":"宮尾庶務課長","answer":"それぞれが、例えば先生方なら先生方とも同様に定めているところです。当面このやり方で、特段我々は課題があるというところは認識してございませんので、これからも適切にこのやり方にのっとって執行させていただければと考えています。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問","question":"もう一度、今定めというのは、総括的なというか概括的な規程はきちんと公開されていると思うのですけれども、今の個別のこういう服ですみたいなのはどこに定めがあるのでしょうか。どういう定めになっているのか。定めがあるのは分かったのですけれども、どこに定めてあるのか、もう一度お伺いします。","respondent":"宮尾庶務課長","answer":"こちらにつきましては、文字どおり別に定めるということで、この被服貸与規程を受けまして、事務局のほうで意思決定をとって適正に管理しています。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"その定められているものの表題は何になるのですか。","respondent":"宮尾庶務課長","answer":"すみません、今そのタイトルにつきましては、すみません、今手元に資料がございませんが、この規程にのっとりましてそれぞれ内部で意思決定を取って、それにのっとって執行しています。","id":"exchange-152"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望というところでお願いしたいと思います。続きまして、いじめ防止対策費について伺います。その中で、感染拡大期にはハイブリッド授業も行われたと聞いています。今日は特に中でもいじめの被害者についてお伺いしたいのですけれども、いじめの被害を受けて学校に通えなくなった場合のフォロー体制、特にこのＩＣＴを活用したフォロー体制についてお伺いできればと思います。","respondent":"矢部教育総合支援センター長","answer":"今効果的だなと捉えているのが、学校の一室、別室に来るのですけれども、そこで今やっている１年１組の授業とか５年１組の授業を配信して、それを見ながら参加してという、これで出席になっておりますし。","id":"exchange-153"},{"speaker":"松本委員","kind":"質問","question":"一方で、ではいじめの加害者との関係でどうなのかというところを少しお伺いしたいのですけれども、よくやはり加害をした児童・生徒が教室にいるので、被害児童・生徒がなかなか教室には行けないという話が昔からあると思うのですけれども、一方、これは学校教育法上では加害者の出席停止が認められていると。けれどもほとんど活用されていない。","respondent":"矢部教育総合支援センター長","answer":"その後、加害者のその児童・生徒の様子、当然保護者と一緒に話をしながら、どのように対応するかということになりますので、当然別室、オンラインもあるでしょうし、もしかしたら被害者の方が同じ校舎内にいることすら苦手な場合もあるかもしれません。","id":"exchange-154"},{"speaker":"松本委員","kind":"質問","question":"今の進めているというところで実績があるのかどうか伺っているので、実績としてそういう事例があるのでしょうか。伺います。","respondent":"矢部教育総合支援センター長","answer":"実績はつかんでございませんが、ないとは申し上げられないです。今はここまでです。","id":"exchange-155"},{"speaker":"吉田委員","kind":"確認","question":"いろいろな方から質問が出ました学校における動物の飼育について伺います。それで、先ほどの質疑で分かったのですけれども、先行していた５校については、これまでどおり会計年度任用職員を配置して、そして新たな１０校について、このプロポーザルのところで応募したところに派遣を委託するという理解でよろしいでしょうか。ただ、予算書の３７３ページに５,３３２万５,０００円ですか。","respondent":"矢部教育総合支援センター長、宮尾庶務課長","answer":"人事のほうの費用になっていると聞いておりますので、こちらにはまとめたことしか計上してないと伺っていますので、すみません、少しフォローしていただいていいですか。ですから、来年度の派遣につきましては計上されているです。会計年度任用職員の給与面に関しましては、今年度から全庁的に、それまで各課に計上していたものが人事課のほうに移行するということになってあります。","id":"exchange-156"},{"speaker":"吉田委員","kind":"質問・要望","question":"何かやはり同じような仕事をするのであれば、同じような報酬であってほしいと思って伺ったので、それはあまりこの場合は私の質問の中では重要なところではないので、後で分かったらぜひ教えてください。第４回定例会で生活者ネットワークが一般質問をしたそのご答弁では、普通学級に障害児を通わせているお子さんの親の付添いを学校から求めることはないというご答弁をいただいております。","respondent":"矢部教育総合支援センター長","answer":"一番最初のご質問ですけれども。その辺りを私たちも注視しながらモデルを進めてまいりたいと思っています。学習支援員、介助員につきましては、ＮＰＯ団体にお願いをして委託をしております。","id":"exchange-157"},{"speaker":"吉田委員","kind":"質問","question":"すみません、一気に聞いてしまえばよかったのですけれども、確実に増えているということについての、例えば過去５年間で何人から何人に増えたとか、そういう実績で増えたということが分かるようなことがあったら教えてください。","respondent":"矢部教育総合支援センター長","answer":"５年前、平成３０年からです。通常の学級に配置した学習支援員・介助員が３９２名、令和元年が４５７名、令和２年が５１８名、令和３年が５６３名、本年度５２４名となっています。","id":"exchange-158"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひその辺は配慮していただいて、きちんと支援員は増やしていただきたいと思います。その主体性はとても大事にするべきだと思います。そう考えると、教員を支援するほうが妥当なのかというふうに思うのですけれども、教員を支援する形で、結局その障害児とかそういう人たちがクラスの中で過ごしやすい環境にしていくという考え方がよいと思うのですけれども、ぜひ見解があったら伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"それが、以前からお伝えしてまいりましたとおり、教員の支援につながっていると考えています。お子さんと支援員のマッチングがうまくいかないということもあるかもしれませんが、やはりその辺りは担任を中心にどのような人間関係でやっているのかと。","id":"exchange-159"},{"speaker":"吉田委員","kind":"質問","question":"次の質問に行きます。２回選挙がありましたから２回目に行ったけれども、全然改善されていなかったということで、とにかくその動物のために何とかしたいということなのですが、この点について品川区の公立学校の方針はどのようなものなのか伺いたいと思います。子どもたちが小動物を飼う場合の関わり方、昔はよく飼育係とか結構人気の係があったと思うのですけれども、今はどうなのでしょうか。","respondent":"勝亦学務課長、森学校施設担当課長","answer":"現状、そういった不適切なものがあれば改善を図ってまいりますけれども、例えばウサギに関しましては１日、ふんですと１センチ大のものが大体１００個から２００個ぐらい出るとは聞いております。ウサギ等の飼育ですけれども、長期休暇の場合は、過去は学校の先生がボランティアの形で連れて帰っていただいたりというのがあったのですけれども、やはり働き方改革等もありますので、今は委託のほうに。","id":"exchange-160"},{"speaker":"吉田委員","kind":"質問","question":"最後のこのようなたまたま選挙が２回続けてあったというのはあまりないかもしれませんけれども、近隣の方がそういうことを知ってしまったときに、ＰＴＡではないわけですね。どうしたらいいのだろうかと。この方は学校には言ったらしいのですけれども、適切な対応はしてもらえなかったということで、それについてぜひお答えください。ぜひその辺についての見解を伺いたいと思います。","respondent":"勝亦学務課長","answer":"改善の対応につきましては学校にお声を掛けていただいたですけれども、教育委員会のほうで一定程度、獣医師会と連携しながら飼育の方法ですとか動物の面倒等を見ておりますので、教育委員会のほうに言っていただければ対応できるかと考えています。","id":"exchange-161"},{"speaker":"吉田委員","kind":"質問・要望","question":"皆さんもこの動物を飼うということについては価値を置いておられるようなので、ぜひその方向で進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-162"},{"speaker":"渡部委員","kind":"質問・要望","question":"小学校の学区域に基づいて、いわゆる一つの小学校から、学区域として２つの学校、３つの学校に行くということはないというふうに分かりやすい制度になった。例えばここだって、あと５年、６年したらそこにすごいマンションが建って、人が増えてとなれば、ではこの界隈の学校が大丈夫なのかというのもあるわけですから、しっかりそこは進めていただきたいと思います。","respondent":"勝亦学務課長","answer":"学事制度審議会の関係で、学校選択制です。隣接校を選択する方式につきましては、平成２８年度に実施いたしました学事制度審議会でも、その存在の意義を答申でいただいております。そういった意味では、引き続き学校選択制は隣接校の形で実施していきたいと考えています。","id":"exchange-163"},{"speaker":"渡部委員","kind":"質問・要望","question":"そういうような思いでお伺いさせていただきました。欠員が埋まらないということは、その学校は、では例えば担任の先生とかが何がしかで外れてしまったら、副校長が取りあえず入っていますよとか、何かいろいろ例えば指導課の中の指導主事が代理で入っていますよとかというような形で、何かしら実は簡単に欠員が何名ですでは片付かなくて、それなりのことを教育委員会でいろいろやっているのでしょうか。","respondent":"中谷指導課長","answer":"実際に理由も様々で、病気のことでお休みの方もいらっしゃれば、産休育業のことでお休みとある中で、そのお休みされる期間に対して教員を置いていくという考え方で、その中で正規の教員でない場合に、例えば期限付の教員であったりとか講師の方であったりとか。","id":"exchange-164"},{"speaker":"渡部委員","kind":"質問・要望","question":"それで、これは別のときにも聞きましたけれども、公務員の定年の問題があって、教員もそれはご多分に漏れず同じだと思うのです。結局校長先生だって、管理職先生は役職定年がついてしまって、そうしたら校長先生を終わって６０歳過ぎて役職定年が来てしまうから、そのあと受けられないとかいうのを少し心配しているのですけれども、その辺の考え方を教えてください。","respondent":"中谷指導課長","answer":"それに伴いまして、定年退職以降の方に関しては暫定再任用管理職という、考え方としては現在の再任用の方と同じで定年退職以降、６５歳になるまでの間を暫定再任用管理職ということで働くような形となります。","id":"exchange-165"},{"speaker":"渡部委員","kind":"意見","question":"ではいわゆる校長先生として残っていただく方は、６０歳で一回そこで区切りをつけてもらって退職という形をとって、違う形の再任用ということですね。もし校長先生まで行かれた方が一般教員で残りたいとなれば、６５歳までそのランクを下げたと言ったら失礼だけれども、そうした上で残れるという仕組みでいいのですよね。","respondent":"中谷指導課長","answer":"校長先生もしくは副校長先生、管理職をなさった方が６０歳を迎えて役職定年ということになりますので、それ以降の考え方としては基本的に降任ということになりまして、役職ですと主幹教諭以下の役職になっていくと。","id":"exchange-166"},{"speaker":"渡部委員","kind":"質問","question":"分かりました。それと、教育ルネサンスの中で少し聞きたかったのが、２年前に中央教育審議会のほうで、令和の日本型学校教育という形の発表がなされて、どういうふうにやっていくのだと書かれています。ここ数年、これを聞いていなかったのですけれども、実際この国のほうの学習指導要領と、品川区の結局品川区立学校教育要領との違いというのが、よその区はこういうのを作っていないわけではないですか。","respondent":"中谷指導課長","answer":"これに関しては、品川区はいち早く取り組んで、今充実しているところと認識しております。","id":"exchange-167"},{"speaker":"渡部委員","kind":"質問・要望","question":"すみません、時間がなくなってしまったので思いだけ伝えますと、その令和の日本型学校教育の中で、結構私はこれを見ていて目立つのが、そのＩＣＴ教育のところがいい意味で目立ってしまっているのです。その学習の中でこれからもしっかり品川区は取り入れていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"学校改築にあたっては、今、様々学校改築が進んできていて、計画を持って学校改築を進めている中で、どうしても昔の校舎を見てみたいという地域の方や同窓生の方がいて、改築して取り壊しする前にはぜひ学校見学をしたいというようなご要望、今までもあったかと思うのですが、対応をどのようにしてきているのかというのと。","respondent":"矢部教育総合支援センター長、中谷指導課長、森学校施設担当課長、勝亦学務課長","answer":"部活動指導員事業についてお伝えいたします。２人ですが、今年度までも１人というところでも時間数ですね。既に部活動指導員に何らかの形で関わっていただいている部活の中で、少しその指導の回数を増やすということにご了承いただけたような形で。ちなみに今回、第四日野小学校の６年生が、今改築を進めているところですけれども、完成を見る前に卒業してしまうということですので。変更の理由ですけれども、現行のホームページのシステムが平成２４年にできてあります。","id":"exchange-169"},{"speaker":"大倉委員","kind":"質問・要望","question":"地域の方にも見ていただきたいと思っているのですが、コロナで入れなかったというところでは、学校の例えば形を残していくという、例えば今クロスリアリティとかＶＲとかＡＲとか、様々な技術革新でそういったことができる中で、少し取組として、学校をアーカイブとしてデータ上に残していくというような取組をされているところがあって、３６０度撮影可能な３Ｄスキャンカメラで撮影をした映像というのが。","respondent":"矢部教育総合支援センター長、勝亦学務課長、森学校施設担当課長","answer":"部活動指導員の公募ですが、例年１２月から１月ぐらいに区のホームページで上げさせていただいています。更新に関しましては、必ず外部の外の端末でもパスワード等でアクセス制限をして、更新にあたっては必ず管理職の確認。今は紙でやっておりますので、そのデジタルと紙をどうするかというところですけれども、やはり費用対効果ということであったり。","id":"exchange-170"},{"speaker":"大倉委員","kind":"質問・要望","question":"当然、ある程度セキュリティをかけて見られないところとかを見えないようにしながらやらなくてはいけないところもあるかなと思うのですけれども、学校公開とかで、先ほどのデジタル学校要覧みたいな話で、ホームページ等でそういった学校の中が見られるとか、風景が見えるとか、そこに動画を配置して授業の様子が見えるとか、そういうのができたら、それはそれでまた学校の新たな魅力として。","respondent":"森学校施設担当課長","answer":"ただ、やはり費用対効果であったりとか優先順位がありますので、世の中の要請、区民の皆様からの要請も鑑みながら判断して検討してまいりたい、研究してまいりたいと考えています。","id":"exchange-171"},{"speaker":"石田委員","kind":"質問","question":"私からは、３６４ページの教育指導費でいいのか、命の安全教育について伺いたいと思います。熱心に取り組む学校もあれば、公開されている文部科学省のユーチューブ動画を見せるだけ、スライドを読むだけという指導にとどまる学校もあるのではないかというふうにも言われているのですが、品川区はこの生命の安全教育についてどのような姿勢で取り組まれていくのか、まず伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"委員ご案内の教育につきましては大変重要だと認識しておりますので、令和５年度はすべての学校、全学年で取り組みます。","id":"exchange-172"},{"speaker":"石田委員","kind":"質問","question":"性交渉については教えないという。そうすると、どうやってそうした性犯罪・性暴力から自らを守るのかというのが分からないままになるのではないかと思うのですけれども、そういったところでも区独自にぜひ工夫をしていただけたらと思うのですけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"一番肝要なのは、自分の体と心の成長を理解することと、自他を大切にすることに気づかせるというところがポイントですので、ここに目標を置いてきちんとした指導をできるように、我々のほうもきちんと見て指導してまいりたいと考えています。","id":"exchange-173"},{"speaker":"石田委員","kind":"質問・要望","question":"被害に遭った子どもに「あなたも悪かったんじゃないの」などと知識なく言った一言で、自分が悪いと追い込まれてしまう、相談ができなくなるということもあると思いますので、ＰＴＡや保護者にも生命の安全教育をきっかけにした人権としての性教育を受ける機会というのを、教育委員会としても子どもを守る立場から進めていただきたいと思うのですが、いかがでしょうか。","respondent":"中谷指導課長","answer":"４月からが本格始動になるかと思いますが、こういったものを校内研修でまずは教職員にお知らせしつつ、どうやって体制を組んでいくかというところをしっかり進めてまいりたいと考えています。","id":"exchange-174"},{"speaker":"石田委員","kind":"質問","question":"教職員ではなくて、地域の大人や保護者への性教育も必要だと思います。やはり親たち、大人たちも十分な性教育、正確な性教育というのを受けていませんので、そういった相談を受けてもどう答えることが正解か分からなくて困るという声も寄せられておりますので、子どもが安心して相談できる環境をつくるための大人の準備も必要だと思うのですけれども、教育委員会としてはどうお考えでしょうか。","respondent":"矢部教育総合支援センター長","answer":"保護者の、また大人の性教育を学校がどこまでやるかというところもあるのですが、保護者として必要な知識を共有する場というのは保護者会とか報告会などであるのかなとは思っております。","id":"exchange-175"},{"speaker":"塚本委員","kind":"質問","question":"私からは、初めに３７５ページ図書館運営費、それから３７１ページマイスクール運営費についてお伺いしていきます。最初に図書館運営費については、この図書館の座席、いわゆる閲覧とか座って本を読んだりできるそういうスペース、これの使用状況について、今、図書館として区内１０か所、あと分館が１か所ありますけれども、どのような状況になっているのか現況をお聞かせください。","respondent":"吉田品川図書館長","answer":"実際現場とかを見てみましてもなかなかまだその辺は、感覚的なところなのかもしれませんけれども、ソファとかにつきましては少し離れた形で座っているというのが現状です。まだその辺の周知については時間がかかるものと考えております。","id":"exchange-176"},{"speaker":"塚本委員","kind":"意見","question":"私も時々、それほど区内全部の図書館に行っているわけではないですけれども、地域の近い図書館等に行くと、やはりなかなか席は空いてないです。いつもいっぱいでなかなか空きがないと。このことについて、こういった受験生の声について区としてどのように今お考えになるかということと、何かしらの対応等がなされているのであれば、それについてもお聞かせください。","respondent":"吉田品川図書館長","answer":"令和３年の秋口ぐらいから、閉めていた部屋を何か利用できないかということを考えたところ、会話をしなければ、勉強部屋としての利用ならできるのではないかというところで、図書館の多目的室を中・高生以上の方たちに勉強してもらうスペースとして利用できないかと。","id":"exchange-177"},{"speaker":"塚本委員","kind":"質問","question":"すべての図書館にこういった多目的室があるということではないと思うので、区としてこの品川区内の図書館において、そういった受験生が勉強できるようなスペースがあるといいのだけれどもという声に対してどのようにお考えなのかというのを改めてお聞きするのと、そういった意味では現状なかなかそういった多目的室みたいなものを作ろうとしても。","respondent":"吉田品川図書館長","answer":"なかなか施設による差異もあります。その中で、今年度からは大崎図書館と大崎図書館の分館においても、多目的室を利用した学生向けの勉強スペースを用意しています。今後につきましては、その各施設の状況等を踏まえまして検討してまいりたいと思います。","id":"exchange-178"},{"speaker":"塚本委員","kind":"質問","question":"品川区でも多分これは全国的な傾向と同じと認識しております。この不登校、または不登校気味というような児童・生徒、こういった児童・生徒に対して、タブレットによるオンライン授業というのか、オンラインを活用したいろいろな学校の学業の推進みたいなことというのはある程度されているのか、どのような状況にあるのか、最初にお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"不登校のお子さんにつきまして、タブレットの活用は、在籍校のほうでかなり頻繁にされていると認識しています。マイスクールに来るお子さんにつきましては、試みはしております。","id":"exchange-179"},{"speaker":"塚本委員","kind":"質問・要望","question":"むしろ、これがもしかしたら不登校とかを何かしら解決していく手段としてうまく活用できる部分もあるのではないか。こういう部分も大変に感じているところでありますので、ＩＣＴ支援員の強化とかいうことも今年度されるですので、ぜひ今後、今ご答弁あったとおり、課題は課題として認識されていると思うのですけれども、一層の活用に向けての検討等を進めていただきたいとお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-180"},{"speaker":"渡辺委員","kind":"質問・要望","question":"３６３ページクラブ・部活動等経費、部活動の地域移行も含めて伺います。こちらはやはり私たち自民党からも、あるいは議会全体でも取り上げる機会の多い部活動地域移行についてですが、私たちも強い要望として伺って、要点だけを言うと、そのときにそれぞれどうなっていくのかと、あるいは希望も言った中で、ご答弁の中で次年度には少なくとも各学校１つの部活動が地域移行できるようにという点。","respondent":"中谷指導課長","answer":"部活動の地域連携に向けた部活動指導員を拡充していくということにつきましては、先ほどもお伝えさせていただいたとおりになっておりまして、令和５年度に拡充という形で進めさせていただきたいと考えています。","id":"exchange-181"},{"speaker":"渡辺委員","kind":"質問","question":"私も少し理解に苦しんでいるのですが、ひとつ予算書はまだ準備が難しいのかなと思いながらも逆に伺います。予算書のどこにが今ないようですので、１２月ですから間に合わなかったのか、あるいは重要度の問題なのか、あるいは私たちは議会人ですから議会として、いつこういう質疑をすると翌年の事業に間に合うのか。これでは、今入っていなかったら、再来年度の予算審議でやってくれと言わんばかりになる。","respondent":"矢部教育総合支援センター長","answer":"部活動指導員の倍増ですので、こちらの会計年度任用職員で先ほどお話があったとおり、３６５ページの職員給与費の中に含まれているです。","id":"exchange-182"},{"speaker":"渡辺委員","kind":"質問","question":"それはもうそのとおり異論はないです。では地域でそれができるかって、そうではないから、経済的負担もどうしようというのが主な考え方です。そういう思いで今伺っていますので、ここを別に今どうこうではないのですが、もう少しスピード感も含めて、あるいは先ほど３６３ページ、クラブ・部活動等経費、ここなどは当初予算ベースで令和４年よりも総額で言えば横ばいあるいは減少している事実があるのです。","respondent":"中谷指導課長","answer":"ですので、こういったお声を含みながら、また保護者や地域の方からのご意見も校区教育協働委員会から聞いてございまして、現在の部活動のメリットを維持しながら、段階的に地域移行してほしいというようなところもいただいているので。","id":"exchange-183"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それを踏まえて最後ご答弁いただきたいのは、そもそもですが、やはり学力・体力の向上と共に、部活動への期待というのはやはり人間力、あるいは協調性とか、やはりこの原点というか一番分かりやすいすべての世代に伝わる教育の環境だと思いますので、その辺品川らしさ、私で言えば地域力かなという感じがしていますので、その辺を十分踏まえて現場の先生たちをしっかり応援できる。","respondent":"中谷指導課長","answer":"そしてどういった指導者と共に自分を導いてもらったかというような、そういった経験を、地域移行という形になったとしてもそこをしっかり保証するということをやっていきたいと考えています。","id":"exchange-184"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491981?Template=document&Id=1174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":124522,"voices":436}},{"id":"r05-20230322-3","meetingId":"r05-c-budget","date":"2023年3月22日","dateIso":"2023-03-22","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時４４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を154件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤副委員長","kind":"質問","question":"品川区議会自民党を代表し、鈴木真澄委員と共に総括質疑を致します。経済的支援について。そこでまず、区は逼迫する区民生活をどのように捉え、現在どういった生活支援を行っているのかをお知らせください。複数の町会では春の桜祭りにおいて、物価高騰により、ちょうちんの電気はつけないとお伺いしておりますが、そういった事態をどう受け止め、どのような対策を取っているのかもお知らせください。","respondent":"久保田企画部長、伊崎地域振興部長","answer":"具体的には、第４回定例会におきまして、約８億円の各種支援策を議会にご提案し、議決を頂き、現在、各施策を進めているところであります。引き続き、区民の生活状況等の把握に努めまして、区として適切な支援を進めてまいります。物価高騰への対応経費としての直接の助成制度ではございませんが、活動活性化の支援策として実施している補助金を活用していただくことが可能です。","id":"exchange-001"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"様々な支援メニューがあることは確認できましたけれども、そういった支援を区民や町会等が知らなかったということがないような、寄り添う形での支援体制の強化をお願いしたいと思います。そういった要望に対して、区長会を通じ、区や東京都へ予算要望をしていただき、区独自の支援もできる限り行っていただく必要があると思いますが、区のご見解をお知らせください。","respondent":"久保田企画部長","answer":"国における電気料金の値上げ審査につきましては、厳格かつ慎重に判断するとも聞いております。区としましては、引き続き区民の生活状況等の把握に努めるとともに、国や東京都の動向を注視しながら、適切な支援を実施してまいります。","id":"exchange-002"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"廃業を余儀なくされている事業所も報告されておりますので、物価高騰で打撃を受けている事業者や団体からの要望は、会派からも引き続き要望しますので、その時々に必要な支援を行える体制を要望いたします。健康支援についても、区では区民の健康を支える取組を行っていただいておりますが、令和５年度の予算案には、会派より要望しておりました帯状疱疹ワクチン接種の一部助成も盛り込んでいただきました。","respondent":"福内健康推進部長","answer":"がん検診は、肺がん、大腸がんは毎年、胃がん、子宮がん、乳がんについては、２年に１回の受診となっており、これは、厚生労働省の、がんの死亡率を減少させることを目的としたがん検診実施のための指針に従い、実施しているものです。","id":"exchange-003"},{"speaker":"湯澤副委員長","kind":"確認","question":"受診によって早期発見されているケースもあるということが確認できましたが、今後は受診率を上げるための取組が重要であると考えております。民間自動車保険会社のように、期限が迫るとお知らせするようなサービスも、受診率を上げる取組かと思いますけれども、ご見解をお知らせください。","respondent":"福内健康推進部長","answer":"今年度、肺がん検診でも同様の取組を行っており、これらの効果を見極め、今後も効果的な受診促進策を検討してまいります。","id":"exchange-004"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"人生１００年時代において、健康的に年齢を重ねていくことは極めて重要だと考えております。続いて、災害についてお伺いします。本区においても、災害に強いまちづくりを目指して、品川区地域防災計画の大規模修正が行われます。そこで、主に修正内容がどういったものなのか、また、いつ起きてもおかしくない大災害に備え、できるだけ早い作成を望みますが、いかがでしょうか。","respondent":"滝澤災害対策担当部長","answer":"計画修正のスケジュールですが、令和５年度に入りましたら直ちに修正作業を開始し、令和６年１月には修正計画を決定できるようにしてまいりたいと考えています。","id":"exchange-005"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"風水害や、今ありました火山の噴火、また感染症対策といった多岐にわたっての修正になるかと思いますので、大変ご苦労があるかと思いますが、区民の命を守るために全力で取り組んでいただきたいと思います。備蓄は、現存するもので足りるのでしょうか。そのような帰宅困難者の命を守る区独自の取組について、国や東京都に対して予算の拡充を求めるべきと考えますが、それぞれご見解をお知らせください。","respondent":"滝澤災害対策担当部長","answer":"交通機関の復旧とともに、分散している帰宅困難者に安全に帰路についてもらえるよう、正しい情報を共有し、連携した帰宅行動が取れるべく対策を講じていく必要があります。引き続き、国や都と連携しながら、帰宅困難者対策を一体的に推し進めてまいります。","id":"exchange-006"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"こういったよい取組を一過性にせず、今後もリアル訓練と並行して行い、時代や世代にマッチした開催によって訓練参加率を上げていくべきと考えますが、区のご見解をお知らせください。ペット同行避難についてもお聞きします。動物以外のペットもいて、大変難しい課題であるかと思いますけれども、ペット同行避難について、区のご見解と今後の取組についてお知らせください。","respondent":"滝澤災害対策担当部長","answer":"本年５月に実施する区職員による自主避難施設開設訓練や、１２月に実施する区内一斉防災訓練における区民避難所訓練においても、ペット同行避難をテーマとした訓練の働きかけを実施して。","id":"exchange-007"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"防災力を高めるには、正しい知識と、訓練を繰り返し行うことが大切だと考えています。次に、犯罪から区民を守る取組についてもお伺いします。特殊詐欺等に対する区の相談件数はどのくらいあるのか、またどういった対応をしているのか、区のご見解と今後の区民への啓発方法についてお知らせください。","respondent":"伊崎地域振興部長","answer":"詐欺から守る地域の輪！」をスローガンに掲げた啓発を行っております。特に自動通話録音機につきましては、区内４警察署からのご案内も含めて約５,０００台を貸与しており、今後もさらなる周知に努め、ご希望の方に行き渡るように努めてまいります。","id":"exchange-008"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"無料貸付機も５,０００台貸与されているということでありますけれども、報道では、アポ電で捕まる指示者役も氷山の一角にすぎないと言われております。区民の不安解消のために、自動通話録音機とともに、録画機能つきのテレビインターホンの設置助成をすることも検討いただきたいと思いますが、いかがでしょうか。","respondent":"伊崎地域振興部長","answer":"現在、様々な詐欺被害の拡大や、今ご指摘にあったように、宅配業者を装った犯罪など、区民の方のご不安になるような犯罪が続いているということは認識しております。区では、区民の不安解消策として、区と警察が合同で、「自宅の防犯対策を見直しましょう！","id":"exchange-009"},{"speaker":"湯澤副委員長","kind":"提案","question":"ご提案した録画機能つきのテレビインターホンにつきましては、大体１万円から２万円程度で販売されておりますので、区民が安心して生活できるような先行区としてご検討いただければと思います。次に、子育て・教育について、ご質問します。","respondent":"久保田企画部長","answer":"令和５年度に本格的に実施いたします行政評価によりまして、不断の検証や見直し、改善を実現しまして、財源を生み出してまいりたいと考えているところです。","id":"exchange-010"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"今ご紹介がありましたような、子育て事業も令和５年度には様々取り組まれておりますし、あと所得制限なしで幅広く新規計上もされておりますので、自民党からの要望も多く採用していることに関しまして大変うれしく思っております。子育てプランに対して相談やアドバイスを行える伴走型支援も有効であると考えますが、ご意見を伺います。","respondent":"柏原子ども未来部長、福内健康推進部長","answer":"転入時や親子健康手帳の配付時といったところで配布させていただいてあります。こちらは区のホームページでもＰＤＦ化しておりますけれども、今後の利便性を考えて、電子ブック化できないかというところの検討も今しています。私からは、子育て伴走型支援についてお答えいたします。区はこれまでも、妊産婦ネウボラ相談から始まり、支援が必要な方へ、子育てサービスの提供や保健師の訪問など、伴走型の支援を実施してまいりました。","id":"exchange-011"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"区が行っている両親学級に参加した方からは、大変参考になり、応募してよかったというお声を頂いておりますが、こうした両親で学べる教室については、今後、拡充していただきたいと考えますが、いかがでしょうか。父親も母親の妊娠時から子育てを理解し、プレッシャーを感じることのない、積極的に子育てに参加できるような取組が今後さらに必要だと考えますので、区のご見解をお知らせください。","respondent":"福内健康推進部長","answer":"感染予防のため減らしている定数についても、状況を見ながら見直すとともに、これまでの父親学級での利用者の声も踏まえ、プログラムを検討してまいります。","id":"exchange-012"},{"speaker":"湯澤副委員長","kind":"質問","question":"学校のマスク着用についてもお伺いしますが、マスクを着用できないことによって子どもが差別を受けているという保護者の思いも受けて、教育委員会では今年の２月に全児童・生徒に向けて、「マスクを着けられないお友達やマスクを外せないお友達がいます」といったプリントを作成していただきました。配布後の子どもたちの反応はどうであったのか。","respondent":"米田教育次長","answer":"児童・生徒に向けたメッセージ動画等についてですが、これまでも学校向けに、しながわネットＴＶのＹｏｕＴｕｂｅ番組等を作成してきましたが、今後についても検討してまいります。","id":"exchange-013"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"ぜひ、学びの機会に関しましては、学校単位でなくて、全ての児童・生徒を基準に等しく行っていただきたいと考えています。次に、高齢者・障害者支援についてお伺いします。認知症の予防や発症を遅らせる取組については、認知症の正しい知識とともに多くの区民に知っていただくべきと考えますが、区のご見解をお知らせください。","respondent":"今井福祉部長","answer":"令和５年度に取組を強化する事業につきましては、今年度も実施いたしました認知症検診推進事業、もの忘れ検診です。特に検診受診後の継続的な関わりを強化すべく、訪問看護ステーションとの連携の下、受診後の伴走的な支援をさらに予定しております。","id":"exchange-014"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"品川区では、認知症の方と家族等の一体的支援事業として、区内２か所に認知症ミーティングセンターを開発・設置されましたので、まず、その成果と見えてきた課題についてもお知らせください。ミーティングセンターは、当事者が安心して生活できる取組ですので、今後もニーズに合わせて拡充を図っていただきたいと思いますが、課題や展望があればお知らせください。","respondent":"今井福祉部長","answer":"課題としましては、このミーティングセンターの理解促進と周知を図ることと捉えておりまして、今後におきましては、認知症地域支援推進員の協力の下、事業拠点の拡大につなげますよう積極的に取り組みまして、令和５年度は計３か所の拠点へと拡充すべく。","id":"exchange-015"},{"speaker":"湯澤副委員長","kind":"確認","question":"人生１００年時代において、誰もが認知症や病気、また障害を負う可能性があります。自分の将来、身の回りの整理、亡くなった後のことなど、大きく６つの項目に分けて、問診票を、自分の気持ちを確認しながらチェックしていくものであります。ご案内した、大田区の老いじたく推進事業のような分かりやすい冊子を取り入れることも、より高齢者が人生設計をしやすくなると考えますが、見解をお知らせください。","respondent":"今井福祉部長","answer":"品川区におきましても、類似の取組といたしまして、平成２７年３月より、品川区社会福祉協議会が意思決定支援ライフプランノートを作成・出版し、ご本人の意思決定支援を実施しております。","id":"exchange-016"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"森澤区長の選挙公約で、高齢者・障害者グループホーム２００人分の整備について、区議会自民党でも毎年、増設を要望しておりましたので、賛同いたします。現に、私の地元、小山六丁目のグループホームでは、説明会で反対や見直しの声があり、難航しておりました。その後、障害者支援の実現に向けた障害者施策推進課の粘り強い説明により、計画が前に進んでいるとお聞きしております。","respondent":"今井福祉部長","answer":"私どもも、地域への障害者理解促進に向けて、障害者理解や普及啓発のイベントを広く開催するとともに、町会長や町会の皆様、民生委員をはじめ、住民の皆様に丁寧に説明を重ねて、今後も整備の必要性を説明してまいります。","id":"exchange-017"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"力強いご答弁を頂き、ありがとうあります。計画予定地になっても様々な条件や制約があるかと思いますが、しっかり近隣住民の皆さんの理解を得て、整備目標の実現に向けて引き続き取り組んでいただきたいと要望いたします。最後に、障害者スポーツ支援についてお伺いします。区はデフリンピック大会の啓発活動をどのように行っていくのか、また区民の認知目標値があれば教えていただきたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"それから文化のほうでは、デフの啓発イベントとしまして、オンテナと申しますけれども、振動と光によります、音を体感できるものなどで工夫して音楽会を実施したり、手話をモチーフとしたワークショップを通じた啓発といったものを。","id":"exchange-018"},{"speaker":"湯澤副委員長","kind":"質問","question":"オリンピック・パラリンピックと同様ということで、大変高い目標値を掲げていただきました。スポーツに関心がない方でも、例えば大会が開催される２０２５年までには、例えば職員全員がデフサッカーのユニフォームを着て職務を行うとか、また区長のユニフォーム姿による応援動画やポスターを作成するなど、まずは職員の１００％を目指すべきと考えますが、ご見解をお伺いします。","respondent":"山崎文化スポーツ振興部長","answer":"様々、福祉部をはじめとしまして庁内連携を図るなど、工夫できるものは対応・検討して、力強く啓発をしてまいりたいと思うところです。","id":"exchange-019"},{"speaker":"湯澤副委員長","kind":"提案","question":"様々ご提案させていただきましたが、現在も決勝戦で列島を熱狂させておりますＷＢＣにおきましても、ペッパーミル・パフォーマンスといったものが社会現象となっておりますので、デフリンピックにおいても、区民が熱狂するような啓発とともに、手話の理解促進が２３区トップクラスとなるような取組を期待いたしまして、私からの質問を終わります。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"湯澤一貴副委員長に引き続きまして質問します。私からは、初めに区政運営についてお伺いしてまいります。就任後間もない時点での編成であり、大変なご苦労や、十分満足のいくものではなかったかとも思いますが、いかがでしょうか。森澤区長として、この長期基本計画に対してどのように捉えているのかについてお伺いします。","respondent":"森澤区長","answer":"品川区長期基本計画が示す大きな方向性の上に立ち、社会・経済情勢が大きく変化する激動のただ中にあって、多様化する区民ニーズを的確に捉えながら、４つの重点政策を中心に、区民の幸せ、ウェルビーイングの向上に向けて、積極的に区政を前に進めていきたい。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"長期基本計画を着実に推進するために、令和４年度から令和６年度までの３か年を計画期間とする品川区総合実施計画が策定されています。区長が施政方針の中でも示されました、「誰もが生きがいを感じ、自分らしく暮らしていける品川」を力強く切り開くことの実現のためには、令和５年度中に総合実施計画の検討を行うべきではないかと考えますが、いかがでしょうか。","respondent":"久保田企画部長","answer":"現時点では、総合実施計画の改定作業は、令和５年度の区政に関するアンケート、また行政評価を踏まえまして、各事業の見直し・改善を行うとともに、区民の幸福に直結する区政への変革を目指しまして、令和６年度に行っていきたいと考えているところです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"お答えは分かりました。ただ、やはり先ほど申し上げたように、区長の方針が出てくる中で、計画の前倒し、また改定するのは当然ではないかと私は思います。現総合実施計画にとらわれることなく、また新たな方向性を出していっていただきたいと思いますが、その辺をもう一回お答えいただいてよろしいでしょうか。","respondent":"久保田企画部長","answer":"私どもとしましても、総合実施計画、また長期基本計画を基本としつつも、社会・経済情勢の流れ等も勘案しながら、子育て支援策、また福祉施策、また地域支援等につきましても、様々な角度から総合的に検討いたしまして。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区長の方針に全然反対するのではなくて、積極的に進めてもらいたいという中で質問させていただきましたので、よろしくお願いいたします。改めて別の質問ですが、当初予算案のプレス発表にモデル事業実施が示されていました。今後の品川区としてのモデル事業、また新規事業ということで考えたとき、どのように考えているか、その点についても教えてください。","respondent":"久保田企画部長","answer":"品川区としましては、現在、大きな時代の転換期であると捉えておりまして、子育て、教育、福祉、まちづくり、また行政の仕組みも含めまして、時代に合わせて変えていきたいという考えもありますので、モデル事業の実施も含め、今後も新規事業等も含めまして。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ぜひ品川区として新規事業・モデル事業を実施していただければ、国の事業ということで財源確保という点にもなると思いますので、その辺をまたよろしくお願いしたいと思います。ただ、モデル事業の実施や新たな事業を立ち上げるためには、事業に関わる職員の方の数の面での問題はないでしょうか。そして、一部の職員の方に過度な負担がかからないような体制づくりを希望しますが、いかがでしょうか。","respondent":"堀越総務部長","answer":"定年年齢の引上げに関してですが、これも同じような考え方でございまして、一定職員を採用して、事業を推進する対応を図る上で必要な人材をしっかりと確保していきたいと思ってあります。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"分かりました。都が実施した場合、都からの補助金は、歳出予算４億９,０００万円の２分の１、２億４,５００万円の歳入が見込まれると考えてよろしいのでしょうか。そうであれば、普通に考えれば、２億４,５００万円は一般財源からの支出であり、歳入は一般財源に戻ってしまうのではないかと思いますが、ぜひ子育て関係の別途事業に上乗せしていただきたいと思いますが、いかがでしょうか。","respondent":"柏原子ども未来部長","answer":"私からは、第２子保育料無償化に係る国庫補助の見込みのご質問にお答えしたいと思います。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ活用を検討していただきたいと思います。この６億円を子育てに使っていただきたいと、私は令和元年の決算特別委員会で要望いたしました。その要望に対し、「国からも子育て支援に使うよう通知が来ており、引き続き保育の質の向上に向けて様々な事業展開をしていきたい」とのご答弁を頂きました。その点についてお知らせいただきたいと思います。","respondent":"柏原子ども未来部長","answer":"幼児教育無償化に係る、その後の資金の活用といったところの問合せです。区といたしましては令和元年度以降も、新規開設の保育園、認証保育園から認可保育園への移行も含めてですけれども、保育園の増設ということで、１７園ほど行ってきたところです。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"お話は分かりました。もう一点、子育て支援についてお伺いいたします。我が会派の鈴木博議員から、病児保育の重要性・必要性から、病児保育のさらなる拡充と、親が子どもの病気のケアを実地に学ぶ、病気の子どものケア教室の実現を、本会議や委員会においても要望しております。新年度予算において病児保育は、令和３年度・４年度と同様に、４か所、定員２９名、予算額もほぼ同額です。","respondent":"柏原子ども未来部長、福内健康推進部長","answer":"品川区子ども・子育て支援事業計画といった中で、需要の部分についてもきちんと把握しながら、その拡充に向けて検討を進めていきたいといったところです。今後、この結果も踏まえまして、実施内容やタイミング、対象者等を含め、薬剤師会等の関係機関とも相談しながら、検討を進めてまいります。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ケア教室に関しましては、薬剤師会等、関係団体と調整して、なるべく早く進めて、充実したものにしていただきたいと思います。先ほどの病児保育ですが、第二期品川区子ども・子育て支援事業計画ということですが、これは令和２年度から６年度までです。この計画で改定するということは、実施は令和７年度以降になると考えてしまうのではないかと思うのですが、その辺はいかがでしょうか。","respondent":"柏原子ども未来部長","answer":"そうした中で、病児保育の施設等に関わる部分につきましては、拡充に向けた考え方を持っていきたいですが、ただニーズといったところを深く考えて、実際にその施設を進めていくときには、柔軟な対応を区としては図っていきたいというところで考えているものです。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"分かりました。中間見直しということで、ぜひ検討を早めに進めていただきたいと思いますので、これは要望します。次に、重点政策の２つ目にあります、「高齢者も障がいのある方も誰もが安心を実感できるしながわ」から、八潮南特別養護老人ホームの増改築整備と障害者支援についてお聞きします。八潮南特別養護老人ホームについては、当初の運営設計が見込みのとおりいかず、運営が厳しかったと伺っています。","respondent":"今井福祉部長","answer":"障害者施設整備につきましては、今後の特別支援学校の卒業生の受皿としてのニーズに応えるため、今回の増改築計画に合わせ、同施設内に重症心身障害者通所事業所ピッコロを拡充整備することを含め、検討しております。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"特別養護老人ホームについて、お伺いいたします。中でも、低廉な価格で利用できる多床室は引き続き必要だと思いますが、区のお考えをお知らせください。併せて、個室と多床室の利用料、また多床室に対する入所希望についてもお聞きいたします。","respondent":"今井福祉部長","answer":"直近の申込みにおきまして、多床室のニーズですけれども、全体の約半分、５０％程度の方が多床室のみを希望されている状況です。こうしたニーズも勘案しながら、今回の増改築計画では、多床室を可能な範囲で残す計画と考えております。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺をうまく調整し、全体計画を立てていただきたいと思いますので、よろしくお願いします。どの程度の医療的ケアが必要な方への対応ができるのか、また、そのための地域連携はどうなっているのでしょうか。以前から通所の日数を増やしていただきたいとの要望もお受けしていますが、現在の通所状況とレスパイト事業の実績についてもお知らせください。","respondent":"今井福祉部長","answer":"医療的ケアが必要な方への対応のための地域連携につきましては、令和４年度から、医師の配置回数を月１回から３回に増やしまして問診を行っているほか、保護者や職員からの相談にも対応しています。今後も緊密に連携を深めてまいりたいと考えております。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"うまく連携を取っていただいて、進めていっていただきたいと思います。次に、障害児の支援についてです。現在の区内の設置数は２２だと聞いておりますが、充足数についてお知らせください。障害児の保護者の就労支援や、一時休息の場を提供する日中一時支援は３事業者だと思いますが、就労する方も増えていると聞いています。こちらの状況についてもおっしゃってください。","respondent":"今井福祉部長","answer":"放課後等デイサービスおよび日中一時支援の充足状況についてです。いずれも、発達障害が広く認知されるにつれ、発達に不安や疑いのあるお子さんへの療育ニーズの高まりと、保護者の就労の増加により、まだ区としては整備を進め、開設していきたいという状況と認識しております。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その点から考えると、ピッコロの跡地に放課後等デイサービスをぜひつくっていただきたいということをぜひ要望いたします。平成２８年４月の熊本地震の後、しばらくしてから自民党として被災地へ視察に行きましたが、お話を伺っていた中で、市町村の物資集積拠点に物資が滞留し、避難所になかなか物資が届けられなかった、いわゆるラストワンマイル問題について、非常に大きな課題であると感じました。","respondent":"滝澤災害対策担当部長","answer":"令和４年度の新たな物流体制における実績を踏まえまして、本年２月には、委託物流業者と災害時における協力協定を締結して、災害時にも体制を強化したところであります。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほどの帰宅困難者対策の答弁と少し重複しますが、今回新たに民間倉庫を活用されるということで、令和５年度に実施予定となっておりますが、どういった物資、また機材を入れていくのでしょうか。その活用について、どのように輸送体制の強化につながっていくのかについてもお知らせください。","respondent":"滝澤災害対策担当部長","answer":"区内に２８か所ある備蓄倉庫や、５２か所の区民避難所の倉庫などは、災害発生直後に避難者が必要とする備蓄物資を分散して保管する一方、新年度から借り上げ予定の民間倉庫は、軽量発電機や間仕切りなど、サイズが大きく重量があり。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"倉庫の活用について理解しました。これからも効率的な活用をして、運営していただきたいと、ぜひお願いいたします。これらの支援物資は、どのように災害時の輸送拠点に集約することになるのでしょうか。そして、その運営に対して区の職員の方はどのように関わっていくのかについてもお知らせください。もう一点、協定は輸送以外にも数多くあると思いますが、種類と件数についてもお知らせください。","respondent":"滝澤災害対策担当部長","answer":"そのため、発災２日目以降から、区の地域内輸送拠点を運用することが必要となります。この地域内輸送拠点の運営につきましては、災害時協力協定を締結している物流業者、区の職員、ボランティアなどで対応することを想定しております。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"備蓄物資の確保等に加えまして、輸送体制の強化にもつながることが分かりました。支援物資が避難所に届かなかったという過去の大規模災害の教訓を活かし、引き続き、輸送体制の強化を図っていただきたいと思います。そこで、災害対策担当部長が様々な場面で体験されたご苦労を品川区の防災に活かしていただきたいと思いますが、いかがでしょうか。","respondent":"滝澤災害対策担当部長","answer":"発災直後の被災現場での人命救助から、発災から１週間程度経過した頃からの避難者への生活支援や、瓦礫・災害廃棄物の処理など、最長２か月半にわたる東日本大震災における現地での活動経験などを通じて、時間とともに変化する被災者ニーズへの対応や。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ活かしていただきたいと思います。実は私ども、自民党として以前、時局講演会を開催した際に、自衛隊の経験をされた参議院議員の方からお話を伺いました。何回も要望しておりますが、大井町に来てくれる方を、ＪＲ東日本の開発地内だけで完結させず、中央口方面に流れていただくための、さらなるご努力をお願いいたしますが、この点につきましてもお答えをお願いいたします。","respondent":"有江都市整備推進担当部長","answer":"今後とも、地域と調整を図りながら、大井町駅周辺全体の活性化につながるよう、検討を進めてまいります。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"新庁舎建築に対しましては、款別審査の際に芹澤委員から提言がありましたように、ふるさと納税を活用した寄附金の募集についてはいかがでしょうか。プレートに名前を入れるという方法や、ＪＲ東日本の赤レンガ車庫の存続を求める声もありますが、赤レンガに名前を入れ、新庁舎のどこかにレガシーとして残すような検討はできないでしょうか。これからまた、第二庁舎を含めた広町事業の検討が始まっていきます。","respondent":"榎本新庁舎整備担当部長","answer":"名入れをしたレンガが老朽化した場合に、その対応策等もあらかじめ検討しておく必要があると考えています。一方、他の自治体において、新庁舎整備においてふるさと納税を活用している例は多々あります。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私の議会での質問はこれで最後となりましたが、品川区のさらなる発展、「新時代のしながわ」を推し進めていただくことを希望いたしまして、質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"新妻委員","kind":"質問","question":"森澤区長は、「新時代のしながわ」、「誰もが生きがいを感じ、自分らしく暮らしていける品川」を掲げ、来年度予算案において、特に子育て支援に重点を置いた施策を盛り込み、「子育て・教育で選ばれるしながわ」の実現に向けて、区長１年目をスタートされました。併せて、その中で展開される主要な子育て支援に関する事業を伺います。このような中、区長が子育て支援を第一に取り組む意義をお伺いいたします。","respondent":"久保田企画部長","answer":"国や東京都においても重要課題と認識しておりまして、様々な施策の実施に向け、検討を進めております。区は、国や他の自治体に先駆け、スピード感を持って、先進的な少子化対策・子育て政策を積極的に推進していく考えです。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"学校給食費、高校３年生世代までの医療費の無償化は、区議会公明党の重点要望であり、第２子の保育料の無償化は、都議会公明党が一昨年の都議選で１番目に掲げた公約です。現在の子育て支援策で所得制限があるのはどのようなものでしょうか。お知らせください。そして、今後の品川区の所得制限なしの考え方と、ベーシックサービスについて区の認識をお伺いいたします。","respondent":"久保田企画部長","answer":"初めに、子育て支援施策の中で所得制限がある事業についてですが、国や東京都の制度により、区で実施しております児童手当や認証保育所保育料助成、また、区の制度としましては奨学金貸付事業などがあります。次に、今後の子育て支援に係る所得制限の考え方についてです。","id":"exchange-042"},{"speaker":"新妻委員","kind":"質問・要望","question":"区でできる限りのことのご検討を進めていただきたいと思います。次に、０歳児おむつ宅配定期訪問と、区議会公明党が早期の実施を求めていた出産・子育て応援事業についてです。この事業をご説明いただき、進捗状況を伺います。そこで、出産したばかりのご家庭が、どの支援を利用できるのか混乱のないように、分かりやすい丁寧な周知を求めますが、見解を伺います。","respondent":"福内健康推進部長","answer":"これらの事業の周知につきましては、妊娠届の際にお渡しする母子バッグの中にチラシを同封し、また妊娠期、ネウボラ面談の際に説明するとともに、ホームページに、妊娠期や出産後に、月齢等に応じ、受けられるサービスを掲載するなど、丁寧な周知に努めてまいります。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"厚生労働省が本年２月に２０２２年の出生数を公表しましたが、７９万９,７２８人と、過去最少を更新し、国の将来推計より１１年も早く８０万人を下回りました。その新規事業を注視し、区民が利用できるよう、分かりやすい周知を要望します。さらに、区として不妊治療の支援拡充も視野に入れていただきたいと要望しますが、見解を伺います。","respondent":"福内健康推進部長","answer":"都が今年度１月から開始した精神医療の助成につきましても、十分に周知に努めてまいります。","id":"exchange-044"},{"speaker":"新妻委員","kind":"質問・要望","question":"パートナーシップ宣誓制度について伺います。私は、制度があることで理解が広がっていくとの当事者からのお声を受け、これまで議会質問を通して、パートナーシップ制度の導入を求めてきました。多様な生き方を認め合う品川区の姿勢を示したことを評価するとともに、より一層の性的マイノリティの方々へ寄り添った取組を期待いたします。見解を伺います。事実婚の方々への区のお考えをお伺いいたします。","respondent":"堀越総務部長","answer":"活用の事業に関しましてですが、都のパートナーシップ制度を活用するに当たりまして、庁内でのヒアリングの実施、それから庁内連絡会などを開催してまいりました。それで、新たに提供可能な事業の調査・把握などに努め、連携を図ってまいりました。","id":"exchange-045"},{"speaker":"新妻委員","kind":"質問・要望","question":"誰もが暮らしやすい品川区でありますよう、取組を進めていただきたいと思います。次に、これからの八潮地区についてです。庁舎内に１地区の担当課が設置されることは珍しく、区が八潮地域のこれからに力を注いでいることが分かります。これまで開催された八潮みらい懇談会と部課長級の庁内会議の開催数と、会議の内容、そして令和５年度の開催についてお知らせください。","respondent":"伊崎地域振興部長","answer":"八潮地区は、昭和５８年度、団地の入居開始以降、約４０年が経過しまして、地域に高齢化や人口減少が見られることや、施設の老朽化が進んでいるなど、様々な課題があることから、八潮地区の持続可能で魅力あるまちづくりを進めるために、八潮まちづくり担当を設置したものです。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問・要望","question":"その施設には、私が２０１８年から開設を求めてきたオアシスルームが併設されます。これで、空白地であった八潮地区での開設が実現される方向です。款別審査でも伺いましたが、２０２５年度の開設に向けて、八潮みらい懇談会を活用し、子どもを預ける保護者の声も聞きながら、つくり上げていってほしいと要望します。さらに、開設予定地は、高齢者が多くお住まいの都営住宅の１階です。併せて見解を伺います。","respondent":"柏原子ども未来部長","answer":"園庭の運用ですけれども、具体的にはこれからの検討というところになってまいりますので、近隣のご利用等も含めて検討を進めていければと思ってあります。","id":"exchange-047"},{"speaker":"新妻委員","kind":"意見","question":"前向きなご答弁を頂きました。次に、八潮団地内には、在宅の重症心身障害者の方が家族と共に地域の中で暮らすことができるよう、平成２４年に開設された、品川区重症心身障害者通所事業所ピッコロがあります。開設当時と比較して、現在までの利用状況の推移をお知らせください。先ほどの総括質疑では移転とありましたけれども、どのような検討をされているのか、お知らせください。","respondent":"今井福祉部長","answer":"今後、利用者数の拡充も含めて、実際に運営する事業者または利用の状況を踏まえて、十分検討していきたいと考えています。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問・要望","question":"検討の様子が分かりました。ピッコロの利用者に関してお声を頂きました。利用者の送迎バスの駐車場についてです。区の対応を伺います。併せて伺ってまいります。次に、八潮五丁目地区まちづくりガイドラインの策定についてです。ガイドライン策定後は、八潮まちづくり担当との連携、部課長級の庁内会議でも共有していただき、地域の声がいち早く具現化されるよう要望いたしますが、見解を伺います。","respondent":"今井福祉部長、中村都市環境部長","answer":"今後も利用者や障害者団体の皆様の声を聞きながら、よりよい運営を支援してまいります。八潮地区のまちづくりガイドライン策定に向けた現在の進捗状況ですけれども、これまでに住民アンケートを、八潮五丁目地区全戸配布により実施してきまして、また、自治会、それから分譲住宅管理組合、また子育て世帯の方々を対象に。","id":"exchange-049"},{"speaker":"新妻委員","kind":"確認","question":"ピッコロのバスの件は、２０２２年度からピッコロの前にとめられるようになるということで、確認させていただきました。大変にありがとうあります。立会川・勝島地区まちづくりビジョンは、地域の方々の声を反映しながら２０１９年１月に策定され、目指すべき将来像が示されました。どのような飲食店が入居するのか、伺います。これらに関して、区の認識と対応をお伺いいたします。","respondent":"中村都市環境部長","answer":"東京都港湾局との調整も行ってきております。それから、来年度も勝島人道橋につきまして、引き続き設計および関係機関との調整を進めて、令和６年度の着工に向けて検討を行っていくという考えです。","id":"exchange-050"},{"speaker":"新妻委員","kind":"質問・要望","question":"勝島地域のにぎわいが発展しているということで、特に飲食店は、皆様の期待の声が大きかったところであります。本日、品川区より具体的なことをご答弁いただきまして、ありがとうございました。今後も勝島地域の発展に向けてご尽力いただきたいと思います。以上で総括質疑を終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"こんの委員","kind":"質問・要望","question":"区議会公明党を代表して、新妻委員に引き続き、総括質疑を行います。初めに、幼児教育についてお尋ねします。品川区が掲げる、「一人ひとりをささえ、伸ばす子育て・教育で選ばれるしながわ」にふさわしい幼児教育の体制を求め、質問いたします。そこでまず、品川区における幼児教育の重要性および必要性について、ご見解をお聞きします。品川区における区内私立幼稚園の役割についてお答えください。","respondent":"柏原子ども未来部長","answer":"区としての重要性・必要性についての考えですけれども、就学前の幼児教育は、幼児の発達段階に応じた集団生活に、遊びや具体的な体験・感覚を伴う活動を通じて、生涯にわたる人格形成および学習の基礎を培うといったところで大変重要なものであるという認識で。","id":"exchange-052"},{"speaker":"こんの委員","kind":"提案","question":"品川区の私立幼稚園の大きな役割が確認できました。現在、私立幼稚園では、特別支援保育に対する区の補助支援を受けてはいますが、専門性が求められる教諭を増員するには難しい状況です。そこで、こうした預かり保育や特別支援保育の人材確保の運営実態について、区はどのように捉えていますでしょうか。伺います。ご見解をお聞かせください。","respondent":"柏原子ども未来部長","answer":"今後の教諭増員のための支援といったところの部分ですけれども、先ほど申しましたように、区としても幼児教育の重要性というのは認識していますので、各園における、どういった支援が必要なのかというのをよくお聞きして、保護者のニーズといったところも確認しながら。","id":"exchange-053"},{"speaker":"こんの委員","kind":"質問・要望","question":"さて、区は、臨床・学校心理士による巡回相談も実施しています。一方で、現在、早期療育が必要な園児について、相談後に保護者や園児を適切なサポートにつなぐ体制がないため、園をサポートする体制が課題となっていますが、区の認識を伺います。今後はアウトリーチの観点から、私立幼稚園に対しても、区立と同様の訪問支援の実施を要望します。ご見解をお聞かせください。","respondent":"今井福祉部長","answer":"保育所等訪問支援は、保護者のご依頼によりまして実施するもので、子どもへの直接支援と職員への間接支援を行うほか、保護者に対して訪問先でのお子さんの姿や職員の関わりの様子を専門スタッフが丁寧に伝えるなど、保護者の不安を取り除く支援を行っているものです。","id":"exchange-054"},{"speaker":"こんの委員","kind":"質問","question":"次に参ります。次は、防災対策についてお尋ねします。初期消火体制の強化について伺います。消防庁における、令和４年１月から９月の火災状況によると、全国の総出火件数は２万７,４３２件。これはおよそ、１日当たり１００件、１４分ごとに１件の火災が発生したことになります。そこでまず、品川区における火災の状況について、年間の総件数、１日の平均件数、総焼失面積など、現状をお知らせください。","respondent":"滝澤災害対策担当部長","answer":"死傷者は３６名、うち亡くなられた方は６名です。なお、出火の７割を占める主な原因は、電気関係、たばこ、ガスコンロによるものですが、電気関係によるものが４割、たばこによるものが２割、ガスコンロによるものが１割です。","id":"exchange-055"},{"speaker":"こんの委員","kind":"質問・要望","question":"火災発生時に重要なのは、初期消火です。街かど消火栓は、区議会公明党が、２０１３年の第１回定例会より、幾度となく初期消火体制の強化を求めてきた中で、モデル配備されたものです。ここで、委員長に許可を頂きましたので、資料を提示いたします。操作は至って簡単で、誰でも１人でも迅速に行うことができるものです。そこで、確認します。今後の初期消火体制についての方向性をお聞かせください。","respondent":"滝澤災害対策担当部長","answer":"加えて、消火活動に係る区民への啓発や、区民消火隊などへの訓練実施の支援に力を入れてまいります。","id":"exchange-056"},{"speaker":"こんの委員","kind":"提案","question":"そこで１つは、区民消火隊が使用するＣ級ポンプですが、取り扱う方々が高齢になってきていて、なかなか力が入らず、筒先の操作が困難となってきています。初期消火の体制強化のため、Ｃ級ポンプについては筒先にガンタイプノズルの導入検討を、また街かど消火栓については、例えば木密地域や防災広場への配備の検討を提案します。それぞれ、ご見解をお聞かせください。","respondent":"滝澤災害対策担当部長","answer":"Ｃ級ポンプの筒先に取り付けるガンタイプノズルについてですが、ご提案いただいたノズルについては引き続き細部の情報収集を実施いたしますが、現在、東京都２３区の他の消防団においてもガンタイプノズルの導入実績がないことから、区民消火隊への先行導入については。","id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"初期消火体制、さらなる備えを要望したいと思います。次に、マンションの防災対策について伺います。マンションの防災対策は、可能な限り在宅避難できるよう備えておく自助とともに、住民同士、協力し、助け合う共助も重要です。そこでまず、優良マンションの認定事業について、区独自基準の具体的な内容と基準を設ける狙いについてお伺いします。ご見解をお聞かせください。","respondent":"中村都市環境部長、滝澤災害対策担当部長","answer":"それからもう一つですけれども、居住者の人命保護の観点から、災害への備えも重要であると考えまして、これは最低限の備えですが、災害時の行動をどのようにしたらいいかといった防災マニュアルの作成。区内マンションにお住まいの方の共助を支援する施策として、今回新たに導入されたマンション管理適正化推進計画における防災マニュアルや訓練実施の要件化を含め。","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"マンションの防災対策については、区の今の取組、また研究をするということですが、いつ起きてもいいように備えていくといった姿勢で、どうぞ研究を進めながら、進めていただきたいと思います。最後に、若者支援についてお尋ねします。一方、本当に若者の貧困問題はあるのだろうか。若いのだから頑張れば何とかなるはず。若者の生活困窮について、また住環境をめぐる現状について、区のご所見を伺います。","respondent":"久保田企画部長、今井福祉部長","answer":"特に、比較的脆弱な生活基盤で暮らしてきた方々への影響は大きく、国の統計等を見ましても、若者の完全失業率や非正規雇用率は高く、相談件数も増えていることなどから、生活や、住環境の確保に困窮しているものと。私からは、住居確保給付金の利用状況と、困窮する若者への福祉的な支援についてお答えいたします。初めに、住居確保給付金の利用状況ですが、コロナの影響を受けました令和２年度から、今年の１月までの通算で１,１４４世帯。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"住宅ローン減税など、持家の入手を前提とした政策だけではなく、賃貸住宅への支援も視野に入れるべきではないかとの見解を述べています。そこで今後、若者への支援を考える上で、若者の生活困窮の実態調査を検討してはいかがでしょうか、ご所見を伺います。今後、低所得の若者が安定した生活の基盤を築けるよう、セーフティネット住宅家賃低廉化補助による積極的な家賃助成を要望します。","respondent":"久保田企画部長、中村都市環境部長","answer":"委員ご質問の、若者の生活困窮実態調査につきましては、各窓口での把握状況や今後の社会経済情勢等を踏まえ、必要性を含め検討してまいります。所得の低い方ですけれども、年齢に関係なく住宅家賃低廉化をする制度といたしまして、住まいの確保、そして確保した上で生活を安定する。自立を促進するための区の政策としても、この制度を適宜適切に実施してまいります。","id":"exchange-060"},{"speaker":"石田委員","kind":"質問・要望","question":"私からは、羽田新ルート撤回と、２３区で最低の整備率の障害者グループホームと特別養護老人ホームの増設を求めて質問します。この間の一般質問で羽田新ルートについて、区長の反対表明が羽田新ルートを止める決定打になる、反対表明すべきと求めてきましたが、反対とは絶対に言わない。なぜなのか、伺います。森澤区長は、羽田新ルートは賛成なのか、反対なのか、伺いたいと思います。","respondent":"中村都市環境部長","answer":"新ルートの固定化を回避しまして、技術革新を見据えた検討を行うといったことを求め、現在、国により検討が行われております。したがいまして、賛否といったことではなく、区が求めていることに対してしっかりと国として対応していただくといった考えです。","id":"exchange-061"},{"speaker":"石田委員","kind":"質問・要望","question":"何度も問いましたけれども、反対とは言わないわけです。なぜ言わないのか伺ったのと、あと、森澤区長は羽田新ルートに賛成なのか、反対なのか。これを伺いましたので、明確にお答えいただきたいと思います。","respondent":"中村都市環境部長","answer":"ただいまの賛否についてのご質問ですが、繰り返しになりますけれども、区といたしましては、現在、区の求めにより固定化回避検討会も実施されているという現状を踏まえるということと、それから、これからまた区民の皆さんにご意見をお聞きするアンケートも行うです。","id":"exchange-062"},{"speaker":"石田委員","kind":"質問・要望","question":"区民の皆さんが３年にわたって被害を受けて、そして撤回を求める声を上げていますけれども、結局、どちらなのでしょうか。結局、解決策は国が考えるということでしょうか。伺います。区として、反対、撤回を求めることが、一番の解決につながると思いますが、いかがでしょうか。そして、アンケートでどんな深刻な声が寄せられても、反対や撤回を求めることはないということでしょうか。伺います。","respondent":"中村都市環境部長","answer":"現在、アンケートの内容については検討中ですけれども、賛否という議論ではなく、アンケートを通じまして、区民の皆さんの個別の事情をお聞きするということ、そして、分析結果を踏まえ、国に対応を求めてまいります。","id":"exchange-063"},{"speaker":"石田委員","kind":"質問・要望","question":"要するに、解決策は国が考える。区としては、反対も撤回も求めないということでしょうか。伺いたいと思います。それで、そうしたら地方自治体は何のためにあるのでしょうか。だから、区民は繰り返し撤回を求めています。区内で事故が起こらないように、一番の安全策の海上ルートに戻すことも繰り返し求めています。改めて国へ、羽田新ルートへの反対表明をすることを求めますが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"国からは、平成３０年にまとめました落下物総合対策パッケージというものがありますが、これに基づき、現在、世界まれに見る厳しい基準で安全対策が行われているといった国の説明があります。","id":"exchange-064"},{"speaker":"石田委員","kind":"質問・要望","question":"事故はあってはならない。全区民アンケートは行うけれども、解決策は国任せで撤回も求めない。区民の命と暮らしを守るために、反対表明、そして撤回こそ、私たちは引き続き求めていきたいと思います。今回は、障害者グループホームと特別養護老人ホームに絞って伺いたいと思います。森澤区長が掲げる障害者グループホーム１００人分は、いつ頃どのように進めようとしているのか、伺います。伺います。","respondent":"今井福祉部長","answer":"初めに整備ですけれども、認知症高齢者グループホームと障害者グループホーム、合わせて２００名分の整備を目標に、障害者グループホームにつきましては、総合実施計画にありますとおり、令和６年度末までに４８名の定員増に向け着実に取り組んでいるところです。","id":"exchange-065"},{"speaker":"石田委員","kind":"質問・要望","question":"３３０人の方が、いまだに区外を利用しているという数字が分かりました。さらに、今既にある公有地を使って増設できると思うのですけれども、その検討はされているのか伺います。それぞれいかがでしょうか。重度の方の受入れは、さらに専門性が求められます。区が責任を持って、区立で増設することが必要だと思いますが、いかがでしょうか。重度の方も入れるグループホームの今後の計画はあるのか、伺います。","respondent":"今井福祉部長","answer":"重度の方も入れるグループホームにつきましては、今申し上げました、令和６年４月に開設を予定しております出石つばさの家につきましては、ハードの面でも障害者の高齢化・重度化に対応した、お住まいの場としての整備を進めておりますので、入居者につきましては。","id":"exchange-066"},{"speaker":"石田委員","kind":"質問・要望","question":"抜本改善が必要です。重度の方の受入れも含めて、早急に進めていただきたいと求めます。助成額や中身について、さらに拡充していただきたいと思いますし、私たちもこれから求めていきたいと思いますけれども、なので、区長としての新たな施策は、施政方針では認知症高齢者の絵本の読み聞かせだけなのです。特別養護老人ホームについては、民生費でも伺いましたが、「９０歳になっても半分が入れない。","respondent":"今井福祉部長","answer":"私ども、今、特別養護老人ホームは原則として要介護３以上が入居の要件ということで示されておりますので、特別養護老人ホームのみならず、小山台でも整備を進めるところですが、小規模多機能型居宅介護、グループホームなど、それぞれ皆様に適した施設を。","id":"exchange-067"},{"speaker":"石田委員","kind":"質問・要望","question":"取下げの詳細の理由は把握していないということでしたけれども、もう分かっている、確定している数字で、取り下げている方の人数を伺いたいと思うのです。それをお聞きしたので、お答えいただきたいと思います。そして、待機者ゼロになるのか、足りないと思いますけれども、いかがかというところもお答えください。","respondent":"今井福祉部長","answer":"今後また特別養護老人ホームに限らず、先ほど申しました多様な、グループホームなども含めた入居の仕組み、または施設などの仕組みを整えまして、なるべく品川区の中で、身近なところで暮らしていただけるように進めてまいりたいと考えています。","id":"exchange-068"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひスピーディーにつくっていただきたい。結局、取り下げる人というのは、そうすると、ほんの一部ということでしょうか。家族が特別養護老人ホームに入れずに相談に来た５０代男性から話を伺いました。こうした苦しみが森澤区長には見えているでしょうか。そして、第９期の介護保険事業計画に、八潮南特別養護老人ホーム、東大井都営元芝アパート跡地、小山台住宅等跡地以外の増設計画はあるのか、伺います。","respondent":"今井福祉部長","answer":"特別養護老人ホームを含めた施設の整備につきましては、今後も取り組んでまいりたいと考えております。第９期の介護保険事業計画を立てるに当たりましては、介護保険の策定委員会の皆さんと共に、現在のニーズなどを踏まえた上で適切な計画を立ててまいりたいと考えております。","id":"exchange-069"},{"speaker":"石田委員","kind":"質問・要望","question":"コロナの影響や物価高騰で暮らしが大変なときに、自治体がすべきことは福祉や社会保障を充実させて暮らしを支えることです。福祉・暮らし最優先の区政に転換こそと求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"中塚副委員長","kind":"質問","question":"私からは、森澤区長の基本方針、区立３幼稚園閉園撤回および区立認可保育園の存続、住民を追い出す再開発について伺います。そこで伺いますが、ならば、今までの古い時代とは何を指すのか。新しい時代とは、今までとどう違うのか、伺います。なぜ重点施策に人口増を掲げるのか伺います。長期基本計画では総人口のピークを２０４４年としているが、このピークも先にずれるという想定に変えたのか伺います。","respondent":"久保田企画部長","answer":"守りにつきましては、経常的に必要な事業や公共施設の老朽対応、これまで確実に実施してきました事業を滞ることなく進めていくこと、さらには、将来世代に大きな負担を回すことがないよう、基金の積立てなども行い。","id":"exchange-071"},{"speaker":"中塚副委員長","kind":"質問","question":"「新しい時代」とは従来の何をどう転換するのか、改めて伺います。「子育て・教育で選ばれるしながわ」ですが、保育、給食、医療、３つの無償化で、再開発によるタワーマンションへの転入を進め、開発マンションの販売を伸ばしたいのが狙いなのではないでしょうか。「選ばれるしながわ」とは、開発マンションを購入させて人口増を進めたい、品川区のまちづくり戦略なのか、伺います。","respondent":"久保田企画部長","answer":"新しくすることにつきましては、３つの無償化をはじめ、様々な新規事業を実施し、「誰もが生きがいを感じ、自分らしく暮らしていける品川」の実現に向け、取り組んでいくことと考えております。","id":"exchange-072"},{"speaker":"中塚副委員長","kind":"質問","question":"結局、福祉最低、開発最高への反省の弁は一言もありませんでした。森澤区長はここをどう理解しているのか、しっかりご説明ください。なぜならば、森澤区長の施政方針からは、住民福祉の言葉が一言もないからです。基本がないのは重大な問題です。区長が考える「新時代のしながわ」とは、住民福祉の増進をどのように位置づけているのか伺います。","respondent":"久保田企画部長","answer":"これらを目指すことは、住民福祉の増進を進めるということでありまして、４つの重点施策をはじめ、施政方針に掲げる各施策を推進しまして、福祉の増進に努めてまいります。","id":"exchange-073"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"抜本的な転換を強く求めたいと思います。続いて、区立３幼稚園閉園撤回および区立認可保育園の存続を伺います。閉園理由を、行政財産の有効活用と説明しますが、３つの当該幼稚園の運営が、税金の無駄遣い、非効率だと言いたいのでしょうか。区長は区立３幼稚園の閉園をなぜ撤回しないのか、理由を伺います。こうした前区長の対応は適切だったと思うのか、私は反省すべきだと思いますが、いかがでしょうか。","respondent":"柏原子ども未来部長","answer":"幼稚園のニーズの変化に対応して、行政経営資源を有効活用することで、幼児教育・保育の充実、機能強化を図るといった考え方に基づいておりまして、単独で設置の３園の閉園の中止ということは考えてはございませんけれども、一方で、幼保一体施設の幼稚園につきましては。","id":"exchange-074"},{"speaker":"中塚副委員長","kind":"質問","question":"その方向性を出したのは、前区長です。私が伺ったのは、区立３幼稚園閉園をなぜ森澤区長は撤回しないのかと伺いました。お答えください。保護者の声を受けて柔軟な対応と言いましたが、やはり適切ではなかったと思っているのか、反省はあるのか、改めて伺います。","respondent":"柏原子ども未来部長","answer":"そうしたことから、その方向性について変更する考えはないというご答弁をさせていただいたところです。進め方等につきましても、今回の件で、いろいろな件でお話を頂いたところもあります。","id":"exchange-075"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"教育にまで、幼稚園にまで、効率化を求め、閉園する。これが森澤区長の考える子育て支援なのでしょうか。教育にまで、成果を出すまでの過程に効率化を求めるとはゆがんでいます。伺います。つまり、「新時代のしながわ」では何を変更するのか、伺います。数字を伺いますが、認可保育園の４月入園について、第１次および第２次の不承諾通知数は何人か。","respondent":"柏原子ども未来部長","answer":"その検討の内容です。区立保育園に求められる役割というものを改めて整理する中で、将来の施設の維持・更新の見通しも含めて、区内のどの地域にも同じ子育て支援が提供できるような計画の策定に向けて、そのありようを検討しているといったものです。","id":"exchange-076"},{"speaker":"中塚副委員長","kind":"質問","question":"今、答弁の中に、区立認可保育園について、役割について整理していきたいとご説明がありました。私が伺ったのは、今までとこれからと、その役割に何か違いがあるのかしっかりご説明ください。先ほど、具体的な区立園名を挙げて検討しているのか、数を挙げて検討しているのかと伺いました。お答えください。","respondent":"柏原子ども未来部長","answer":"先ほど申し上げました、現在の役割というのは、基本路線としては変わらないものでありますけれども、新しいニーズ、状況の変化にどう対応するのが区立保育園のあり方かというところを検討しているといったところです。","id":"exchange-077"},{"speaker":"中塚副委員長","kind":"質問","question":"むしろ、さらに大事になってきているのではないでしょうか。区は、これでも実質ゼロと言うのでしょうか。伺います。４月入園でこの状態ですから、年度途中はさらに困難。４月入園で空きが生まれることは、年度途中の引っ越しなどにも柔軟に対応できます。仕事と家庭の両立を本気で考えるならば、４月入園と併せて、年度途中でも保育園に入れる環境づくりが、品川区の役割だと思いますが、いかがでしょうか。","respondent":"柏原子ども未来部長","answer":"我々が検討しています、これは幼稚園の部分でも先ほどご答弁申し上げましたけれども、世の中の情勢が変わってきているといったところに対して、その環境にいかにいち早く、行政として、区として対応できるかというところ。","id":"exchange-078"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"こうした区政は転換し、安心して子育てできる品川区を強く求めたいと思います。最後に、駅前タワーマンションなどの再開発事業について伺います。自分の家なのに、不法占拠です。つまり、地権者の意思にかかわらず、住まいや店舗が奪われるのです。これを追い出しと呼ばずに何と呼ぶのか、伺います。なぜ、自分の家なのに、最終的には不法占拠になるのか。根拠条例や裁判の経過なども含めて、説明を求めます。","respondent":"有江都市整備推進担当部長","answer":"区としましては、法令に基づく手続を適正に進めるとともに、一人でも多くの地権者の方々にご理解いただけるよう、事業主体であります再開発組合に対して働きかけていく考えです。","id":"exchange-079"},{"speaker":"中塚副委員長","kind":"質問","question":"再開発に反対していても組合に強制加入。自分の家なのに不法占拠。これの一体どこに同意があるのか。追い出しそのものだと思いますが、なぜこれを追い出しとは認めないのか、改めて伺います。そして、不法占拠や裁判について、つまり誰が誰を不法占拠として裁判で訴え、誰がその家から出ることになるのかご説明ください。","respondent":"有江都市整備推進担当部長","answer":"そういったものですので、区としましては、防災性の向上、にぎわいの創出など、まちの課題を解決するために、地域主体で検討されているまちづくりにつきましては支援していく考えです。","id":"exchange-080"},{"speaker":"中塚副委員長","kind":"質問","question":"品川区は、地権者が追い出される実態をリアルに直視すべきです。こうした追い出しの実態をなぜ認めないのか、改めて伺います。駅前などでご商売された方、地域のためにと懸命に働いた方、こうした方々を追い出すのはやめるべきで、とてもまちづくりとは言えません。土地を奪って、高度利用して、ゼネコンとデベロッパーの独り勝ちではないでしょうか。伺います。いかがでしょうか。","respondent":"有江都市整備推進担当部長","answer":"区としましては、防災性の向上やにぎわいの創出など、まちの課題を解決するため、地域主体で検討されておりますまちづくりが早期に実現するよう、今後も引き続き再開発組合などを支援していく考えでございまして、再開発事業を中止する考えはございません。","id":"exchange-081"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"住民を追い出している再開発に全く反省がない。新たに品川区長になった森澤区長は、自ら進める開発の足元で住民が追い出されている、積み重ねた努力も人付き合いも奪われている実態に目を向けるべきです。「区民とともに進める新時代のしながわ」と言いますが、一体どこが「区民とともに」でしょうか。再開発事業の中止を求めて、質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"松永委員","kind":"質問","question":"初めに、認知症高齢者支援事業について伺います。そこで、認知症検診の推進についてですが、早期発見によって進行を遅らせることは可能であるとお聞きしますが、来年度予算、約７３１万円についての、もの忘れ検診は、どのように推移されているのでしょうか。そして、もの忘れ検診を受けたがらない方もおられるとお聞きしますが、本区としてどのような対策を取られているのでしょうか。お知らせください。","respondent":"今井福祉部長","answer":"検診の受診の有無にかかわらず、認知症の疑いがある方については、各種相談先の支援につながるような取組や、認知症初期集中支援チームが対応して、早期発見と医療介護サービスにつながるように支援を進めていきたいと考えております。","id":"exchange-083"},{"speaker":"松永委員","kind":"質問","question":"森澤区長もおっしゃっておりましたが、２０２５年には、高齢者の５人に１人が認知症と診断されると言われております。そこで現在、本区内の認知症患者数はどれくらいおられるのでしょうか。先ほど伺いましたが、もの忘れ検診で早期発見することができた方、いわゆる認知症と診断された方について、どのくらいおられるのでしょうか。伺います。","respondent":"今井福祉部長","answer":"今後も認知症高齢者の増加が高齢者人口の増加とともに見込まれております。もの忘れ検診において、先ほど２４６人の方が受診されたと申しましたが、認知症の疑いあり、何らかの疑いありとの診断を受けた方は、５４人という結果でございました。","id":"exchange-084"},{"speaker":"松永委員","kind":"質問","question":"先ほどの、もの忘れ検診を受診された方で、認知症と診断された方について伺います。そこで伺います。ご家族は、どうすればいいのかと頭を悩ませているそうです。そこで、認知症理解促進事業の内容について、もの忘れ検診以外にどのようなことを推進されているのでしょうか。お知らせください。続けて、認知症カフェについて伺います。今後についても伺います。","respondent":"今井福祉部長","answer":"令和５年度におきましては、これらのカフェの交流会などを通しまして、認知症の方やその家族に加え、地域の方が認知症を学び、どなたでも楽しく過ごせる場としての拡充と、それから質の充実について、区としても支援してまいりたいと考えております。","id":"exchange-085"},{"speaker":"松永委員","kind":"質問","question":"認知症の症状を理解し、また採用の仕方など、家族、地域での理解は必須だと思いますので、今後もこうした事業を展開していただければと思います。現在、認知症サポーター養成講座を修了された方はどのくらいおられるのでしょうか。そして、修了された方について、運転免許のように更新やレベルアップを図る取組があるのでしょうか。ありましたら、その内容についてお知らせください。","respondent":"今井福祉部長","answer":"免許の更新やレベルアップの取組についてですけれども、認知症に関する理解をさらに深めることを目的としまして、ステップアップ講座を実施しているとともに、今年度から新規事業として、認知症サポーター企画会議におきまして。","id":"exchange-086"},{"speaker":"松永委員","kind":"提案","question":"こうした講座によってスキルアップされ、今後は長寿改革のモデル都市となることを期待し、品川区版の認知症理解推進条例を提案いたします。ぜひ品川区独自の条例制定のご検討をどうぞよろしくお願いいたします。コミュニティバスについて伺います。そこで伺います。しなバスの試行運行が開始されてから約１年が経過したのですが、現在の利用状況と収支率はどのくらいでしょうか。併せて伺います。","respondent":"中村都市環境部長","answer":"１万５,０００人の乗車利用がありました。それから、そのうちの約半数、８,０００人ほどが、シルバーパスの利用者ということになっております。そこで、収支率といたしましては５８.６％。そして、シルバーパスを見込みますと２８.６％といった状況になっております。","id":"exchange-087"},{"speaker":"松永委員","kind":"質問・要望","question":"なぜ、このことを質問したかといいますと、この試行運行におかれましては、収支率が５０％を超えなければ、廃止も含めた見直しと伺っていたからです。そこで、大井ルート以外の２ルートにつきまして、試行運行の開始時期など、本区はどのように考えているのでしょうか。しなバスを検討していく過程で、区民アンケートやワークショップなど、ルートに関する様々な要望があったとお聞きしております。","respondent":"中村都市環境部長","answer":"残りの２路線につきましても、今、大井ルートをしっかりと検証いたしまして、実施できるかどうかというところはまだ不明ですけれども、検討を引き続きしていきたいと考えております。","id":"exchange-088"},{"speaker":"松永委員","kind":"質問","question":"公園・児童遊園整備のキャッチボール場について伺います。そこで、公園内でキャッチボールができる場所について伺います。こうした場所は、本区内にどのくらいあるのでしょうか。今後こうしたボールを使った遊び場を増やしていくことは考えているのでしょうか。併せて伺います。","respondent":"稲田防災まちづくり部長","answer":"面積やほかの施設の配置等によりキャッチボール場の設置が難しい場合もありますけれども、今後も公園を整備する際には、公園利用者、公園周辺の住民の方々のご意見や要望を十分お聞きしながら、公園施設の整備について検討してまいります。","id":"exchange-089"},{"speaker":"松永委員","kind":"質問","question":"本区内に２２か所あるとのことですが、先ほども述べさせていただきました、キャッチボールの音や声などについて、近隣住民からはどのような声が上がっているのでしょうか。私のところに、こうした声が届いております。そこで伺います。現在、ボールが外に出ないように、上部にネットがあるキャッチボール場はどのくらいあるのか、お知らせください。","respondent":"稲田防災まちづくり部長","answer":"ボールが外に出ないという、キャッチボール場の設えですけれども、天井部分、上部にネットを張っているキャッチボール場の数についてですが、２２か所のキャッチボール場のうち１０か所で、天井部分にネットを設置している状況です。","id":"exchange-090"},{"speaker":"松永委員","kind":"質問・要望","question":"様々な声が上がっているのですね。理解いたしました。キャッチボール場の上部にネットがあり、対策が取られているところは、１０か所と伺いました。ぜひ、事故等が起こる前に、キャッチボールが可能な場所について、上部にネットをつけていただき、対策を検討していただきたいのですが、今後の区のご見解をお知らせください。","respondent":"稲田防災まちづくり部長","answer":"今後の対策の検討についてですが、まず１つは、バットによる打撃など、キャッチボール場では禁止している行為による場外への飛び出しもあります。状況をよく注視しながら、利用マナーの啓発にも引き続き努めてまいりたいと思います。","id":"exchange-091"},{"speaker":"松永委員","kind":"質問","question":"上部ネットにつきましては、ぜひ進めていただければと思います。事故が起こる前の対策を、どうぞよろしくお願いいたします。次に、ドッグランについて伺います。そうした中で、特に犬を飼われる方について伺いたいと思います。そこで、本区内にはドッグランはどのくらい設置されているのでしょうか。ペット用トイレについて、設置されているところがありましたら教えてください。","respondent":"稲田防災まちづくり部長","answer":"ペット用トイレの公園の設置状況についてですけれども、区が管理する公園におきましては、ペット用トイレの設置はないという状況です。","id":"exchange-092"},{"speaker":"松永委員","kind":"質問・要望","question":"こうした声を十分に理解していただき、ぜひドッグランの設置に向け、一緒に遊べる環境をつくっていただきたいと思います。そこでドッグランについてですが、広さや柵の高さなどの基準について決まりはあるのでしょうか。ドッグランをつくるに当たり、近隣住民への対策はどのようにされていかれるのでしょうか。ここでは、ドッグランの基準、近隣の住民への配慮についてお知らせください。","respondent":"稲田防災まちづくり部長","answer":"ドッグランを設置していくとなれば、周辺住民の方々、また一般の公園利用者の方々など、十分な理解を得られるために丁寧な説明を行っていく必要があると考えているところです。","id":"exchange-093"},{"speaker":"松永委員","kind":"質問","question":"そこで、ペットには様々な種類がいるかと思いますが、区民避難所では、ペットはどういった動物を指されているのでしょうか。そこで伺います。以前、私が質問させていただいた際、ペット同行避難ができる避難所は数か所だったかと思いますが、現在どのくらいあるのでしょうか。区内には５２か所の区民避難所があるとお聞きしますが、その中に、ペット同行避難ができる避難所は何か所あるのでしょうか。","respondent":"滝澤災害対策担当部長","answer":"ペット同行避難訓練の実績ですが、コロナ禍以前に実施した訓練のほかに、令和３年度から開始している自主避難施設開設訓練において、ペットや同行避難者用のスペースを設置する訓練を行っております。","id":"exchange-094"},{"speaker":"松永委員","kind":"質問","question":"ペット同行避難ができることについてですが、５２か所の区民避難所のうち３４か所で避難が可能ということでした。ここで質問ですが、今後本区は、ペット同行避難ができる避難所の方向性について、どのようにお考えでしょうか。","respondent":"滝澤災害対策担当部長","answer":"既にマニュアル改定が進められている区民避難所においても、今後、ペット同行避難に係る訓練を実施し、その訓練成果を踏まえて、より実態に即したマニュアルになるよう、引き続き、検証と改定を行ってまいります。","id":"exchange-095"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、ペットの同行避難ができる避難所の整備、またマニュアル改定も含めて、進めていただければと思います。そこで、備蓄について伺います。そこで本区は、このペット用備蓄物資について、どのように考えているのでしょうか。ペットの同行避難についてですが、獣医師会やペットショップ、消防署等との連携はどのようにされているのでしょうか。お知らせください。","respondent":"滝澤災害対策担当部長","answer":"今後は、全ての区民避難所でペットの同行避難の受入れを行うに当たって、地域の皆様の声を聞きながら、公助として確保すべき物資の必要性について検討してまいります。","id":"exchange-096"},{"speaker":"松永委員","kind":"質問・要望","question":"備蓄につきましては理解いたしました。次に、私道整備事業について伺います。近年、私道のトラブルがニュースでも流れており、大きな問題になっております。公道であれば、品川区が費用を負担すると伺っております。私のところに、こうした私道の問題の要望が届いております。そこで伺います。本区には現在どのくらいの私道があるのでしょうか。公道と私道の割合についてお知らせください。","respondent":"中村都市環境部長","answer":"私道ですけれども、区内の私道の長さは、約１４５キロメートル。そして、公道と私道の割合ということですけれども、公道の長さが約３８０キロですので、割合としましては、およそ私道が３割、公道が７割ということになります。","id":"exchange-097"},{"speaker":"松永委員","kind":"質問","question":"本区内に私道がこんなに多くあったとは驚きです。そこで、私道を公道にしたい場合は、どのようにすればよろしいのでしょうか。本区では、こうした陥没や水道管、ガス管などの工事について、助成を行っているとお聞きしております。そこで、令和５年度予算の私道整備事業、約６,１００万円の予算がついているのですが、この内容についてお知らせください。この助成を行うための条件について併せて伺います。","respondent":"稲田防災まちづくり部長、中村都市環境部長","answer":"周辺の交通状況など、現場状況等に鑑みながら、私道を区道に寄附する場合の検討が進められていくものです。私道整備の予算の内容ですけれども、まず、こちらは私道を整備するための設計の費用、それから工事をするための監理の費用ということで、まず設計の費用が２０件分、それから私道の工事監理が４件分。","id":"exchange-098"},{"speaker":"松永委員","kind":"質問・要望","question":"私道を公道にするためには、こうした条件が必要だと分かりました。もう一つ、助成についてですが、実際にこうした状況にならないと分からない方もおられるかと思います。ぜひ、こうした助成制度を区民の皆様に周知していただきたいと考えていますが、現在どういった取組をされているのでしょうか。そして、不動産、建設業の皆さんとの連携は取られているのでしょうか。この２点についてお知らせください。","respondent":"中村都市環境部長","answer":"窓口に置いてあるチラシなどを基に地域へＰＲしていただくこともあります。ただ、そういった協力もしていただいているところではありますが、改めまして、引き続き様々な機会を捉え、業者の方への協力をさらに求めてまいりたいと考えております。","id":"exchange-099"},{"speaker":"松永委員","kind":"意見","question":"ぜひ、周知の徹底をお願いいたします。そして、助成を受けられない私道が多く存在するのも事実です。こうしたトラブルを少しでも解消できるよう、しっかりと場所を把握し、不安のない住宅環境づくりに取り組んでいただければと思います。以上で、イノベーションしながわの総括質疑を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"いながき委員","kind":"提案","question":"項目は、以下の４点です。続いて、予算の編成過程について伺います。他の自治体から大分遅れを取りましたが、区民の要望と品川・生活者ネットワークの提案が実現したことを歓迎します。２０２３年度の予算は、１２月に区長が決まり、そこから区長が公約などの新規事業に予算をつけるには大きな組み替えが必要だったと思いますが、予算を組み替えたときの考え方、方向性について伺います。以上、３つ伺います。","respondent":"久保田企画部長、黒田財政課長","answer":"ホームページへの情報掲載につきましては、区民とともに進める新しい品川区政を実現するスタート元年ということでありまして、可能な限り早期に、区民に対する情報提供を実施したものです。それに基づきまして、各所管からの要求に対して、最少の経費で最大の効果を創出することを目的に、前年度の実績や社会情勢、他区の状況などを調査しまして、単価や数量はもとより、事業の実施内容や規模について検討した上で。","id":"exchange-101"},{"speaker":"いながき委員","kind":"質問・要望","question":"情報公開に関しては、予算だけでなくほかのものに関しても、ぜひとも早めの情報公開をしていただきたいと思います。それに関してもお伺いします。問題の多い小山三丁目第２地区には６億円、大崎駅西口Ｆ南地区には１８億円、戸越五丁目１９番地区には２２億円です。開発事業者に手厚く、福祉に厳しいと取られかねないと思われますが、以上３点、見解を伺います。","respondent":"久保田企画部長、黒田財政課長","answer":"１点目の情報公開、多分、情報提供のお話だと思いますけれども、私どもはこれまで情報提供については、ホームページを使ったり、様々な広報媒体を使いまして、情報提供に努めてまいりました。福祉の予算を減額したというご質問ですが、先ほどご答弁申し上げたとおり、要求いただいた、所管からの要求内容を精査いたしまして、予算額、予算案については編成しておりますが、令和４年度の予算と比べますと増額しておりますので。","id":"exchange-102"},{"speaker":"いながき委員","kind":"質問","question":"障害児者・乳幼児をケアする人への聞き取りはしないと、生活者ネットワークの質問に対し答弁されましたが、直接、自分で声を上げられない人の声を、ケアをしている人から聞くということをしないということは、昨年１２月２０日の第４回定例会での質疑で、区民一人一人を対象にしたアンケートとおっしゃった森澤区長の思いにも反するものではないかと思いますが、見解を伺います。","respondent":"久保田企画部長","answer":"区政に対する評価や期待することなど、区民の方の率直な意見をお聞きしたいと考えておりまして、そのため、保育者や介護者への聞き取り調査の実施は予定しないというものです。","id":"exchange-103"},{"speaker":"いながき委員","kind":"質問","question":"そのことはどうなっているのでしょうか。今回、世帯ごとの郵送に変わったということですが、これは個人をどう捉えていらっしゃるのでしょうか。家単位で物事を考えるということは、区民一人一人を独立した存在として考え、その権利を守るものになっているのでしょうか。返信方法はどうなっているのでしょうか。その３点をお伺いします。","respondent":"久保田企画部長","answer":"回答につきましても、回収の封筒につきましては世帯宛てで考えてありますが、ネット回答等もありますので、そちらを活用していただくことで個人からの回答もできますし、もしご希望があれば、返信用の封筒等についてもご希望の方にはお送りするなど。","id":"exchange-104"},{"speaker":"いながき委員","kind":"質問・要望","question":"アンケート自体、学校でやる場合、ほかの子の目や同調圧力などによって、子どもの本当の心や正確な内容は把握できないのではないかと思います。返信だけでも個人別のものとしていただきたいというのと、アンケートはあくまでも区長部局で責任を持って実施していただきたいと思います。以上、見解を伺います。","respondent":"久保田企画部長","answer":"区長部局がですけれども、アンケートの実施は区長部局で実施するものでありまして、これらにつきまして教育委員会のご協力を頂きながら進めていきたいと考えているところです。","id":"exchange-105"},{"speaker":"いながき委員","kind":"質問・要望","question":"区民の関心の高い羽田新ルート関連のアンケートは、丁寧かつ早急に実施していただき、集計・報告をしていただきたいと思います。これも、区の見解を伺います。続けて、羽田新ルートに関連して伺います。２０１９年８月に設立された羽田空港周辺振興協議会とはどういった団体でしょうか。助成金を出している協議会について、区民も知ることができるよう開示を求めます。見解を伺います。","respondent":"久保田企画部長、中村都市環境部長","answer":"アンケートの集計についてですが、私ども、区民一人一人の意見を大切にしまして、きちんと公平に、かつ、きちんと集計いたしまして実施いたしますので、ご心配の点には至らないと考えています。この協議会の設立目的ですけれども、羽田空港周辺の地方公共団体が実施します周辺地域のさらなる発展・活性化に資することを目的に設立ということになっております。","id":"exchange-106"},{"speaker":"いながき委員","kind":"質問","question":"この協議会は、ホームページなども見つかりませんし、正直、どういった背景の団体か、確かに分かりませんでした。そもそも地方公共団体である品川区が、バックボーンも不明な任意団体から助成金をもらうというのは、行政として差し障りがないのかと心配になりますが、その点はどのようにお考えでしょうか。見解を伺います。その旨、協議会へ伝え、交渉はされたのでしょうか。これも伺います。","respondent":"中村都市環境部長","answer":"防音工事のほうに話を戻しますと、防音工事につきましては、今、国でしっかりと実施してきていただいたというところで、対象につきましては全て完了していただいたといった認識です。","id":"exchange-107"},{"speaker":"いながき委員","kind":"質問","question":"今後ほかにも任意団体の方から助成金のお話があった場合、区民や議会に先に示してほしい気がするのですけれども、それはいかがでしょうか。それも見解を、２つ伺います。","respondent":"中村都市環境部長","answer":"助成金の中身につきましては、これは今、建設委員会等でも、たしか以前にもお答えをしたかと思いますけれども、勝島人道橋、それから浜川公園、あるいは花海道といったところの活用方法について、この協議会の助成を使う旨の報告をしていると認識しております。","id":"exchange-108"},{"speaker":"いながき委員","kind":"質問・要望","question":"総務費に引き続き、第二庁舎に関してお尋ねします。昨年１２月、品川区新庁舎整備基本構想・基本計画策定委員会から区長に対し、答申が手渡されました。今年１月の行財政改革特別委員会で、理事者である品川区から、第二庁舎を残さない方向性が示されました。以上を踏まえ、質問します。検討した会議の議事録の開示を求めます。その見解も伺います。この２つを取りあえずお願いします。","respondent":"榎本新庁舎整備担当部長","answer":"それで、そもそも第二庁舎を残すかどうかというのは、この新庁舎整備基本計画に定められた、もともとの本来の趣旨ではなくて、新庁舎建設候補予定地にどういう新庁舎を建てるかというのが大本ですので、跡地活用については、また別途検討するということで。","id":"exchange-109"},{"speaker":"いながき委員","kind":"質問","question":"第二庁舎の扱いの変更は、私は議決案件なのではないかと思ったのですけれども、これは法的・手続的に問題はないのでしょうか。それで、議事録がないとおっしゃったのですけれども、これは答申からかなり大きな変更なので、通常こういったものは議事録をきちんと取るのが行政なのではないかと私は思っていたのですが、そうではないのでしょうか。見解を伺います。見解を伺います。","respondent":"榎本新庁舎整備担当部長","answer":"変更という形で言っていますけれども、第二庁舎はまだ、どういうふうに活用するかというのは、新庁舎が建った後の話ですので、時期的にも大分後になるということで、その間、情勢がかなり変わりますので、それを見据えて、庁舎跡地周辺の一体的なまちづくりにおいて。","id":"exchange-110"},{"speaker":"いながき委員","kind":"質問","question":"計画変更になったという、その計画がどこに示されているのかというのをお尋ねしました。お伺いします。","respondent":"榎本新庁舎整備担当部長","answer":"計画変更になったというのがいまいち分からないのですけれども、建設予定地に新庁舎を整備するという答申内容そのものは変更しておりません。それで、跡地活用の考え方は、改めて付加的に項目を整理して示したというものです。","id":"exchange-111"},{"speaker":"いながき委員","kind":"質問","question":"第二庁舎の取扱いが、当初残すというところから変更になった、そこの部分がどこに書いてあるのかという質問でした。分かりづらくて申し訳ありません。それを伺います。","respondent":"榎本新庁舎整備担当部長","answer":"それは、素案のときには書いていなくて、意見募集をしたときに、その後どうするのだという意見が大分来ましたので、答申の中では付加的に、第二庁舎を残すという形にしたのですけれども、逆に言うと、今、区長選の後、考え方を示すに当たって、本庁舎、議会棟、第二庁舎。","id":"exchange-112"},{"speaker":"いながき委員","kind":"質問","question":"私の頭では理解できなかったので、もう一回、質問します。第二庁舎の取扱いが変更になった際の決定の経緯を教えてください。それと、第二庁舎は活用が変更になったということで、まずは区民に伝えるべきだと考えます。今後、説明会などが開かれる予定はありますか。どうやって合意形成を図られるのでしょうか。お尋ねします。","respondent":"榎本新庁舎整備担当部長","answer":"それについては、説明会というより、もう公表しておりますので、ホームページ等で公表しておりますし、策定委員の方にも、その旨、周知したところです。","id":"exchange-113"},{"speaker":"いながき委員","kind":"質問","question":"であれば、庁内の会議を招集されたのはどなたの発案でしょうか。会議の回数、１０回前後はやっていると思うとのご答弁でした。情報公開された資料から、１２月２８日と１月５日に開かれたことは分かりました。これは、１月５日までに計画変更が決定されたというふうに読み取れたのですけれども、であるならば、１０回前後の会議を、このタイトなスケジュールの中で本当に実施できたのでしょうか。伺います。","respondent":"榎本新庁舎整備担当部長","answer":"それについては、関係部局が調整して集まった形です。その会議は、逆に言うと、資料を出した１２月２８日以前に行った形になりますので、その会議を複数回経た中で、最終的に資料をつくったという形です。","id":"exchange-114"},{"speaker":"いながき委員","kind":"質問","question":"ごめんなさい。どなたの発案で、「第二庁舎に関してもう一回、話合いをしよう」。それが、１か月もしないうちに変わってしまった、その理由が知りたいのです。それを教えてください。策定委員会委員長の早川先生に、そのお話を直接会って、お目にかかってお話をされたということでした。であるならば、早川先生からはどういったお言葉があったのか、できれば全て一言一句、教えていただければと思います。","respondent":"榎本新庁舎整備担当部長","answer":"ただし、策定委員会の議論においても説明はどんどんしていかないといけないだろうということで、今後いろいろな区民説明、意見聴取の機会を適切に確保して、新庁舎整備計画の途中経過を打ち出しながら進めていくのがいいだろうというご意見を頂きました。","id":"exchange-115"},{"speaker":"いながき委員","kind":"質問","question":"すみません。１つ、多分これは答弁漏れだと思うのです。庁舎跡地の活用に関する委員会が今後設置されるというお話も聞いています。そうしましたら、委員長を務めてくださった早川先生が、納得されたというふうに品川区が感じられたのは、どこをもってして納得されたと思われたのでしょうか。","respondent":"榎本新庁舎整備担当部長","answer":"それに対して委員長は、いや、そうではないと。要は、新庁舎の予定地にどういうものを建てて何を入れるかというのを決めるのが諮問事項であり、それに対して幅広い見地から答えるという形になっておりますので、その形での答申をまとめたものです。","id":"exchange-116"},{"speaker":"いながき委員","kind":"質問","question":"すみません。やはり、自分たちが出した答申が変更される可能性があるのかどうなのかをお伝えするのかどうかというのをお尋ねしたのですけれども、その答えがなかったように思いますが、それをお尋ねします。その方たちはどのようにして納得されたと品川区はお考えでしょうか。この２つをお尋ねします。","respondent":"榎本新庁舎整備担当部長","answer":"それで、１０月１７日に、ある委員から尋ねられたのは、今自分たちがやっていることが全部無駄になるのだったら、やってもしようがないのではないかという意見がありましたので、そういうことはないということでやり取りしましたので、各委員もそのやり取りを聞いておりますので。","id":"exchange-117"},{"speaker":"いながき委員","kind":"確認","question":"私がほかの市の方から聞いた認識とは、品川区はかなり違うのだなということが、今確認できました。ほかの市の方は、そういうことは本当にあり得ないと言っていたので、私はすごくショックだったのです。「品川区はそういう区なんだね」と言われたのがショックだったので、それをお尋ねしました。次に、防災についてお尋ねします。品川区の防災の取組について。そこでお尋ねいたします。以上、伺います。","respondent":"滝澤災害対策担当部長","answer":"発災直後の３分間は自分の命を守り、３時間は近所の方と救助・消火活動を行い、３日間は公的援助なしで生き延びる備えをすることも必要と言われております。","id":"exchange-118"},{"speaker":"いながき委員","kind":"質問","question":"町会に限らず自主的な訓練を促すような仕組みづくりはされていますかというのもお尋ねしていたのですけれども。資料が作られているのは分かりました。それをどのように発信されているのか。この２点を伺います。","respondent":"滝澤災害対策担当部長","answer":"区では、先ほど申し述べた品川区災害対策基本条例の中で、防災区民組織というものを設定しております。その防災区民組織を通じて、その組織と防災部門が一体となり、情報共有をして、防災訓練などについて助言・発信しています。","id":"exchange-119"},{"speaker":"いながき委員","kind":"質問","question":"そうしましたら、「しながわ防災訓練ガイド」という、とてもいい冊子があるのですけれども、以前、生活者ネットワークとして取り上げたのですが、この冊子を活用して訓練をしたいという方が区に問い合わせたところ、町会でないと駄目と言われたらしいのですけれども、これは個人のグループでも大丈夫でしょうか。こちらについていかがでしょうか。伺います。","respondent":"滝澤災害対策担当部長","answer":"２つのご質問がございました。１つ目は訓練支援についてですけれども、基本的には町会単位で防災区民組織に対して支援を行っているものです。個人単位となりますと、かなりの数になりますので、そこはこちらで今後、可能性について研究させていただきたいと思います。","id":"exchange-120"},{"speaker":"いながき委員","kind":"質問","question":"防災運営のＨＵＧゲームというものを使ってほしいと思います。それと、情報発信もしてほしいと思います。見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"今回、防災地図や「しながわ防災こどもｂｏｏｋ」なども作成しましたので、引き続き、いろいろな手段で防災の自助・共助を普及してまいりたいと考えております。","id":"exchange-121"},{"speaker":"いながき委員","kind":"質問・要望","question":"ぜひとも進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"藤原委員","kind":"質問","question":"西大井駅のまちづくりについてお伺いします。答弁してくださる方は、今の、西大井駅周辺を頭に浮かべながら答弁していただけますか。それで、周辺のまちづくりについて、まずお伺いします。これは予定どおりでしょうか。それと、南側、西側、そして北側のオープンスペースは、建築上、建設上、きちんと確保されているでしょうか。それと、西大井駅周辺の再開発はどういう状況になっているでしょうか。","respondent":"中村都市環境部長、有江都市整備推進担当部長","answer":"ニコンの竣工時期ですけれども、今、予定どおりです。令和４年８月に着工いたしまして、そして令和６年春に竣工。そして、夏から稼働予定です。まちの課題や将来のまちづくりの方向性など、地権者の皆さんでご検討されております。","id":"exchange-123"},{"speaker":"藤原委員","kind":"質問・要望","question":"頭の中に描いてください。ですから、あそこの踏切の改善。ですから、歩行者が車両を通すためにどくというのは、私は、交通安全上考えて、これは絶対におかしいと思っているので、その辺もやっていただきたいと思うのと、あと、あそこは３０キロが上限ですけれども、私は２０キロでもいいと思います。ですから、ゾーン３０も含めて、これから検討していっていただきたいと思いますが、いかがでしょうか。","respondent":"中村都市環境部長、有江都市整備推進担当部長、稲田防災まちづくり部長、山崎文化スポーツ振興部長、伊崎地域振興部長","answer":"今後、令和６年、ニコンの本社も竣工して、駅の利用者の増加も見込まれますので、これも、先ほどの西口改札と同じように。区としましては、西大井地区では、先ほど来、出ておりますけれども、ニコン本社の移転や、地域主体でのまちづくりの動向もあることから。路側帯はカラー化を行いまして、歩行者が通る部分と車が通る部分を、視覚的に分けて対応している。今後も、文化財行政や観光協会とも連携・協力を図りながら、区内の歴史的資源の観光活用を一層推進してまいります。","id":"exchange-124"},{"speaker":"藤原委員","kind":"質問","question":"部長、原踏切が上がったとき、歩行者が飛び出すのではなくて、車が早く渡りたいから、車が飛び出す。それと、マスタープランの改定をしましたが、いつ正式に発表になるのでしょうか。それと、今まで西大井は、ＪＲのただ１つの駅みたいな形でマスタープランに載っていたのですけれども、どういうふうに変わっていくのか、もしくは変わったか、教えてください。","respondent":"中村都市環境部長","answer":"西大井駅の位置づけですけれども、まず他の地域と広域都市軸というもので、太い線で結ばれたというところと、それから地域の生活拠点として、駅そのものは位置づけておりまして、今後もにぎわい創出の取組、それから防災性の向上といった。","id":"exchange-125"},{"speaker":"藤原委員","kind":"質問・要望","question":"よろしくお願いします。次に、超高齢社会に向けてという意味で、まず介護予防から伺います。その辺について、お伺いします。この課１つにこれだけ任せて、組織的には大丈夫でしょうか。それと、介護予防ということで、しながわ出会いの湯は、私はすごくわくわくしておりますので、大事だと思っているのですけれども、維持していっていただきたいと思うのですが、いかがでしょうか。これもすばらしいですね。","respondent":"今井福祉部長、福内健康推進部長、伊崎地域振興部長","answer":"やはり、民間企業も含めまして、定年の延長等ありますので、高齢化、６０歳以上になっても、やはり働くことも含めて選択肢が広がったことも。しながわ出会いの湯ですが、こちらは地域の公衆浴場を利用して、高齢者の方が気軽に参加できるお楽しみプログラムと入浴サービスを実施して。シルバー人材センターの取組としましては、広報活動や入会説明会などの実施により、入会強化の取組を積極的に行うとともに。","id":"exchange-126"},{"speaker":"藤原委員","kind":"質問・要望","question":"介護を受ける方の人数は増加すると考えています。昨日はお休みですよね。そして、なぜ行ってくださるか。でも、介護というのは本当に３６５日なのです。私は、どうか区の財源で、区のお金で、この方たちにお金もしくは商品券を配っていただきたいと考えています。その辺についていかがでしょうか。そして、他自治体は、２３区で年間１０万円、自主財源でしている区もあります。この辺についてどう思いますか。","respondent":"今井福祉部長","answer":"ご紹介いただきました、介護職に対して１０万円を支給している自治体というのは、江戸川区が令和５年度までは継続して実施するというところで、お１人１０万円とも確認しているところですけれども、区としましても。","id":"exchange-127"},{"speaker":"藤原委員","kind":"質問","question":"研究しないで、早くやってください。そして、法人にとおっしゃいましたけれども、介護士と介護従事者の方に直接渡してほしい。国も法人にはしてくれているのです。でも、個人には行かないのです。これが実情です。ただ、法人も一生懸命してくれているのです。これが現状なのです。私が、２０年前ぐらい、厚生委員会で、あそこの卒業式に行ったときは、人数がいっぱいいました。いかがでしょうか。","respondent":"今井福祉部長","answer":"地域密着型サービス、７１事業所のうち、ベースアップ加算の取得率は９１.５％ですので、国などの、せっかくのこういう加算ですので、きちんとこういう加算も取りながら、今後どのような支援が必要であるかというのは。","id":"exchange-128"},{"speaker":"藤原委員","kind":"質問","question":"処遇改善。本当に、事務的なことが大変ですから。そのためにはと、やはり考えていくべきだと思います。１０年間、何か静かだったなと思ったのですけれども、急に「事務事業評価やります」となったのですけれども、これは、新区長になったからやるようになったのか、その辺の答弁を頂きたいのと、結局、事務事業評価をしても、内部が内部をするわけですよね。これで、本当の評価というのはできるのでしょうか。","respondent":"久保田企画部長","answer":"令和５年度におきましては、全事業を対象に事務事業評価を実施するとともに、行政だけではなく外部の方、いわゆる区民参加の方を入れまして政策評価を実施いたしまして、新たな政策の推進に必要な財源確保に努めていきたいと考えております。","id":"exchange-129"},{"speaker":"藤原委員","kind":"質問","question":"外部の方を入れるのですね。すばらしい。そうすると、私は外部の方を入れないと思ったので、監査委員がもう少し、数字だけ見るのではなくて、外部評価に絡んだらという質問をしようと思ったのですけれども、ちょっとそこの答弁を、監査委員事務局からも頂きたいのと、あと、外部を入れるというお話ですけれども、将来。その辺については、いかがでしょうか。","respondent":"高山監査委員事務局長","answer":"影響におきましても、監査委員の皆様には、公認会計士をはじめといたします委員、そして議員選出の監査委員の方々に、専門的な、政策的な部分をチェックしていただいておりますので、現行の監査委員監査におきましても、かなり質の高い監査を実施できていると考えていますので。","id":"exchange-130"},{"speaker":"藤原委員","kind":"質問","question":"そうしたら、何年後はいずれ、ＡＩ監査というのが出てくるのではないですか。その辺についてはどうですかというのと、あと、それでもやはり職員の方々が、内部という意味ではしていかないといけないと思っているのですけれども、その大事な職員の方が今、退職が目立つということがあると思うのですけれども、この退職の状況を教えてください。","respondent":"高山監査委員事務局長、堀越総務部長","answer":"しかしながら、ＡＩにつきましては今後、日進月歩ですので、現行におきましては様々な監査事務を執り行う中で、ＡＩあるいはＲＰＡといったニューテクノロジーといいましょうか、新技術、デジタル技術を活用しまして。職員の退職の現状についてです。推移といたしましては、普通退職、いわゆる若手の退職が毎年５０名から８０名ぐらいで推移しています。年代別に見ますと、２０代、３０代の職員が多いという状況です。","id":"exchange-131"},{"speaker":"藤原委員","kind":"質問・要望","question":"企画部長、事務事業評価を頼みます。私が求めると、いつも「財源がありません」と言われてしまうのです。結婚するなら公務員。結婚というか、ご主人も奥さんも公務員という方がいらっしゃいますけれども、そのぐらいすばらしい職なのに、何で転職してしまうのですか。何で、それだったら、人事が面接するときに、その時点で分からなかったのですか。これは、ゆゆしき事態ではないのですか。いかがでしょうか。","respondent":"堀越総務部長","answer":"今ご紹介いただきましたが、面接は採用の段階ではしっかりと対応して、ただ、その後のいろいろな自分の人生の設計の中で、そういう判断をされたと見ております。若手の定着などという部分においては、人事制度においても、今、例えば昇任年次が非常に速くなってきております。","id":"exchange-132"},{"speaker":"藤原委員","kind":"質問","question":"でも、２０代、３０代で、５０人ぐらい退職してしまうのでしょう。それで、やりたい仕事があったと。何回も伺ってしまいますけれども、ここはしっかり、将来の品川区を担ってくれる方のために、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"せらく委員","kind":"質問","question":"先日に引き続き、空き家の利活用について質問いたします。区の取組から、２つの相談窓口について伺います。１つ目に、空き家ホットラインは、主に近隣住民からの相談窓口となり、今年度は何件のご相談がありましたでしょうか。２つ目に、無料の空き家専門相談窓口では、特に所有者の相談窓口として、専門家に無料で相談できるということですが、相談内容の内訳を伺います。","respondent":"中村都市環境部長","answer":"空き家ホットラインへの相談内容ですが、まず数ですけれども、相談の数につきましては、内訳ですけれども、まず所有者からの相談ということで、持ち主からは１件です。それから、近隣からの相談が２８件。","id":"exchange-134"},{"speaker":"せらく委員","kind":"質問","question":"今ある空き家で、ある程度管理されているところに対して、一時的な利用としての登録などをして、少しでも区で管理できることにメリットはありますでしょうか。例えば、入院・介護施設に入る等、長期的にその家の所有者が不在にされる際のご家族へのご案内、区内の引っ越しで住民票異動の際にご案内など、取り組んでいることがあれば教えてください。","respondent":"中村都市環境部長","answer":"空き家の前段階からのアプローチというところでは、介護施設に入る方や、様々事情があって空き家になるということがあると思いますが、これもアプローチを早期にできれば、非常に予防には役立つと、区としては考えております。","id":"exchange-135"},{"speaker":"せらく委員","kind":"提案","question":"簡単に周辺の駐輪場の空き状況が確認でき、駐輪したい皆様にとっては利便性が上がり、路上に自転車があふれるといったことも解消が図れるのではないかと思います。以前、提案させていただいたところでしたので、そういった方向で進んでいき、うれしく思います。適地があれば駐輪場の整備がされるのだろうと思うのですが、９０％台の利用状況では、まだ整備の検討には至らないのでしょうか。お考えを伺います。","respondent":"稲田防災まちづくり部長","answer":"しかしながら、この場所だけではございませんけれども、駅周辺に適地があれば、駐輪場も検討の一つとして考えるところでございまして、ただ、駅周辺というところで、適地の確保はなかなか難しい現状があります。","id":"exchange-136"},{"speaker":"せらく委員","kind":"確認","question":"自転車駐輪場のラック幅についても、利用しやすい施設の整備をぜひお願いしたいと思います。ウェブアプリの仕組みについてですが、タイヤ止めにロックがかかることで判別してカウントするということです。民間の駐輪場も同じようにロックがかかるところが多いと思いますが、そちらも連携して満空確認はできそうでしょうか。教えてください。","respondent":"稲田防災まちづくり部長","answer":"連携というところでは、現在、区のホームページに主な区内の民間駐輪場を掲載していますけれども、今後、新たにシステムのプラットフォームが構築されるなどした場合は、積極的に連携の検討を行うなどして、自転車利用者の利便性の向上に努めていきたいと考えております。","id":"exchange-137"},{"speaker":"せらく委員","kind":"確認","question":"そこで、昨年１２月から始まった品川区電子申請サービスについて、申請できる項目も多く、約１００件ぐらいあることを確認しています。開始後１か月で１,０００件の利用があったと確認しました。電子申請の内容はどの項目が多いですか。そして、まだ電子申請の項目に見受けられなかったところで、保育所の入園申請書類についての電子申請の移行の計画を伺います。","respondent":"久保田企画部長","answer":"保育所の入園申請の電子申請の移行についてですが、こちらにつきましては、令和５年３月７日から、国のぴったりサービスで受付を開始しているところであります。これらにつきましても、品川区電子申請サービスにおいても、近日中にこれとのリンクを登録する予定であります。","id":"exchange-138"},{"speaker":"せらく委員","kind":"質問・要望","question":"国の動向も見て対応していってくださればと思います。次に、ファミリーサポートセンターの利用までの手続についても伺っていきます。子育てには地域社会全体での支援が求められており、ファミリーサポートはそういった支援だと思っています。提供会員が増えることにも寄与できるかもしれないという視点から、面談や顔合わせのオンライン化について伺っていきます。ご見解を伺います。","respondent":"柏原子ども未来部長","answer":"今後におきまして、例えば面談といいますと、事前の会員登録の際の手続を省力化して、オンラインで動画を見ていただいた上で郵送手続をするなどといったところも、改定予定で今考えてありますので、引き続き、オンライン化を含めて、ご提案いただいた内容も含めて。","id":"exchange-139"},{"speaker":"せらく委員","kind":"質問・要望","question":"お子さんの特性や様子を確認するということを理解いたしました。子育て中の方は、オンライン化のように、利便性を求めている方が多いと思います。提供会員へのマッチングの流れについて伺います。利用者が利用希望日をセンターに電話してから、提供会員にはどのような方法で募集をかけますか。提供会員はあらかじめスケジュール登録などをしているのでしょうか。伺います。","respondent":"柏原子ども未来部長","answer":"スケジュールの登録ですけれども、例年１月に提供会員向けのアンケートを実施しています。その中で、次年度の希望や稼働可能な曜日・時間を聞いておりまして、おおよそのスケジュールは事務局でも把握している、登録しているといったところです。","id":"exchange-140"},{"speaker":"せらく委員","kind":"質問","question":"学校の部分を伺います。先日の款別審査で、学校のホームページ改修について質問させていただきました。これまで学校と保護者間の連絡方法について度々質問をさせていただきましたが、この改修で保護者専用ページができましたら、そういったところにお手紙のデータなどを格納して見てもらうようにするといった形で、連絡のオンライン化はできますでしょうか。伺います。","respondent":"米田教育次長","answer":"一定程度、紙面による配布を希望される声もありますが、オンライン化を積極的に活用している学校の事例などを全体で共有し、情報伝達の確実性や安全性も図りながら、オンラインの活用をさらに進め、保護者や教職員の負担軽減に努めたいと考えております。","id":"exchange-141"},{"speaker":"せらく委員","kind":"質問・要望","question":"教職員の方は皆さん、授業の準備、お便りの作成や、報告などの書類作成、事務作業、本当に業務量が多い中、その一部にチャットＧＰＴなどのＡＩツールを活用することにより、一定程度、単純な事務作業において、業務量の軽減・効率化になると思いますが、お考えを伺います。そういった点、生徒と先生の間で認識の確認などはしていらっしゃいますか。","respondent":"米田教育次長","answer":"区ではＤＸ推進基本方針に基づき、ＲＰＡやチャットボットの活用等、事務の効率化を図っておりまして、教育委員会も考え方は同じです。","id":"exchange-142"},{"speaker":"せらく委員","kind":"質問","question":"教職員の方々は皆さん、教育に対してプライドを持って取り組んでおられます。今後の情報化の推進などを通じて、教職員の方々の負担軽減を図り、教育に専念できる体制へ、工夫をしながらお願いしたいと思います。次に、区職員の働き方について質問いたします。コロナ禍でテレワークを取り入れているということですが、来年度の体制について、テレワークのできる環境づくりの現状と今後の展望を伺います。","respondent":"堀越総務部長","answer":"ハード的な部分について、今、様々準備や対応を行っているところでありますが、それと並行いたしまして、人事制度的な部分につきましても、申請や業務報告など、一定のルール整備について今検討を進めているところです。","id":"exchange-143"},{"speaker":"せらく委員","kind":"質問","question":"段階的に窓口もオンラインにして、利用者も職員も自宅で対応できるような環境をつくっていくべきだと考えますが、計画など、区の見解を伺います。続いて、ＲＰＡツールの対象事業の拡充について伺います。現在はどの事業で役立っていますでしょうか。ＲＰＡ人材ということも聞きますが、そういった職員が今いらっしゃるのか、外部雇用をしていく予定でしょうか。伺います。","respondent":"久保田企画部長","answer":"ＲＰＡ人材ですが、こちらは現在、情報推進課が中心となって活用支援を実施しておりまして、プログラミングなどの専門知識を不要とするツールを活用することで、職員を育成しながら、内製化を進めてまいります。","id":"exchange-144"},{"speaker":"せらく委員","kind":"質問・要望","question":"このＤＸについては、行政全体と、議会も意識を高く持っていきたいと、会派として考えます。次に、職員のモチベーションアップのために取り組んでいることを伺います。時には厳しい要望やクレームもあるかと思いますが、そうした状況においても、専門的かつ丁寧な対応をしていただけて非常に心強いです。こういった声の共有はしていらっしゃるのでしょうか。３点お願いします。","respondent":"堀越総務部長","answer":"広報広聴課で受理した区民の声には、区政に対するご意見、それから職員対応への苦言のほかに、職員への感謝のお言葉も頂いてあります。感謝の声も含めまして全て、区長まで内容を見た上で、所管に送付して対応しています。","id":"exchange-145"},{"speaker":"せらく委員","kind":"提案","question":"様々な表彰制度でモチベーションアップができるのではないかと思います。区民からはなかなか見えないところだと思い、今いろいろなところで見える化などと言われていますが、お客様から職員への「ありがとう」の声を見える化して、職員満足度向上、業務改善、お客様との良好な関係を構築していけるのではないかと思います。こういう部分もぜひご検討いただけたらと思います。最後にお考えを伺います。","respondent":"堀越総務部長","answer":"ご提案につきましては、我々職員の仕事は一つ一つが、区民の方の不安や不満の解消、それから区民の幸せの実現のためのものが本分でありますので、まずはそのことを踏まえながら、また職員が前向きに仕事に取り組むよう、今ご紹介いただいた様々なツールの活用可能性も含めて。","id":"exchange-146"},{"speaker":"せらく委員","kind":"質問・要望","question":"区民の相談を受けた議員からの要望に対応していただくといったケースも十分あると思いますので、議員側も積極的に伝えたいと考えています。以上で質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"渡辺委員","kind":"質問・要望","question":"品川区議会自民党は、令和５年度品川区一般会計、同国民健康保険事業会計、同後期高齢者医療特別会計、同介護保険特別会計、同災害復旧特別会計の各予算に賛成します。私たちの委員会質疑、予算化されたこと、さらなる拡充への要望など、熱意あるやり取りがありました。期待を含めて、お伝えとお願いをします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区議会公明党の意見表明を行います。公明党は来年度予算編成の過程において、前区長ならびに新区長にそれぞれ予算要望を行いました。喫緊の課題である少子化への対応に全力を挙げて取り組むとともに、高齢者と子育て世代、町会とマンションなど、共に支え合う地域共生社会の構築も含め、本委員会での会派からの意見・要望を真摯に受け止められ、今後の区政へ活かされるよう要望し、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"のだて委員","kind":"質問・要望","question":"以下、具体的な理由と要望を述べます。地域に１か所もない地域包括支援センターは、地域でチームアプローチができるように増設を求めます。潤沢な予算があるのですから、所得制限は撤廃し、港区並みの１３万７,０００円まで拡充することを求めます。難聴児への支援が終わってしまう１８歳から対象にすることを求めます。本当の意味での出産費用の無償化へ、平均費用の８１万円まで補助することを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"大倉委員","kind":"提案","question":"今後もエネルギー価格の高騰に伴う物価高、ポストコロナ、気候変動、人口減少など、これからの時代の課題にスピード感を持って対応していただくよう求めます。今回の予算特別委員会において、我が会派の所属議員が質問の中で指摘・提案した各項目を真摯に受け止め、予算を執行することを強く要望いたしまして、イノベーションしながわの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-151"},{"speaker":"吉田委員","kind":"提案","question":"しかし一方で、例えば安全ではないにせよ、生活者ネットワークが求め続けてきたヤングケアラーへの支援策が前年よりも具体化されたこと、給食費の無償化など、速やかに執行されるべき予算も多いと考え、一般会計全体としては賛成いたします。オンライン・デジタルの必要性・有用性がうたわれる中で、５Ｇの電磁波の人体への影響についても、予防原則に基づいて注視していくことを求めます。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問・要望","question":"令和５年度予算に対する品川改革連合の意見表明をします。令和５年度の一般会計、国民健康保険事業会計と、後期高齢者医療、介護保険、災害復旧の特別会計の各予算に賛成します。国民は買い控えや節約に動き、消費が減少し、中小企業は資金難で融資返済もできず、廃業や倒産が増えているので、区は支援に一層取り組むとともに、今後もコロナ予防に努めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"松本委員","kind":"提案","question":"区におかれましては、弊会派各委員の質疑の中で指摘・提案した点について検討され、予算の執行や今後の施策に反映していただくよう要望するとともに、区が遂行する政策等については、評価、検証、改善を徹底していただき、区民サービスの向上が図られることを求め、品川区議会日本維新の会の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-154"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491981?Template=document&Id=1176#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":136652,"voices":343}},{"id":"r05-20230327-10","meetingId":"r05-cm03","date":"2023年3月27日","dateIso":"2023-03-27","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年第１回定例会","agenda":"令和５年第１回定例会","exchanges":[{"speaker":"石田委員","kind":"質問","question":"区長に伺いますけれども、こうした品川区の教育改革を根本から変えなくてはいけないという認識はあるでしょうか。そして、今回の人事が、こうした役割を期待しての人事なのか、伺いたいと思います。","respondent":"森澤区長","answer":"先ほど申し上げましたとおり、学校、そして児童・生徒を取り巻く環境というのは、本当に多様化していて、複雑化しています。そういった点で、この伊崎氏には、福祉分野、地域分野での経験を活かして、新たな課題にも積極的に取り組んでいただきたい、そのように考えております。","id":"exchange-001"},{"speaker":"若林副委員長","kind":"質問・要望","question":"ただいま、区長からご説明を頂きました。ぜひ森澤区長には、明日の本会議では、議会はもとより、区民の方、区内の教育行政に携わる方に、今後、品川区の教育行政がこのような大きな方向に、本筋は本筋として、向かっていくのだなということがしっかりと認識、理解できるようなご説明、いわゆる丁寧な説明をしていただきたいという要望を伝えしますので、よろしくお願いいたします。","respondent":"森澤区長","answer":"承知いたしました。","id":"exchange-002"}]},{"id":"topic-02","title":"議事日程(5)および追加議事日程","agenda":"議事日程(5)および追加議事日程","exchanges":[{"speaker":"石田委員","kind":"提案","question":"反対です。理由を述べします。今回の人事の提案についても、抜本的転換が必要なこれまでの教育行政を続けるものです。教育委員会は政治的中立性と教育の自主性を確保するために、行政との独立性を保たれるべきですが、２０１５年に教育長は教育委員会事務局のトップで、教育委員会を主催し代表するという２つの役割を併せ持つ、文字どおりのワントップとして位置づけられました。よって、反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-03","title":"議長会等の報告","agenda":"議長会等の報告","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"くにば議員の欠席の件ですが、現在も治療中ということで確認を取っておりまして、通院しながら体調回復に努めているということでありますので、皆様にご報告をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問・要望","question":"先般、行いました予算特別委員会の総括質疑と意見表明に関し、会派で話合いを行いまして、総括質疑については、今、運営要領上では会派に１０分割り当てられていて、会派の構成委員１人当たり２.５分を付与したものが合計時間として割り当てられているという認識を持っています。その辺りを今後検討していただきたいということです。意見表明のところです。その辺を、是正も含めて検討していただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"今のお話は、ご意見として分かったのですけれども、今後、改選して、新たな方たちと議会改革推進会議などでお話しされるのかなと思うのです。４月２６日の幹事長会は、現職が行かれます。次に当選された方ではなくて、落選した場合でも、そこに参加して、次の議会の方たちのことを話し合う場ですよね。これは、落選した人が次の議会のことを話し合うということにとても違和感があるというか、それは別ですか。","respondent":"渡辺委員長","answer":"申し送りなどの性格のものではないと思ったので、どこで取り上げるかも、改選後の皆様で、取り上げる、取り上げないも含めて検討いただくという考え方で、今日は収められればと思います。","id":"exchange-006"},{"speaker":"安藤副委員長","kind":"意見","question":"これは、副委員長というよりも会派としての意見なのですが、今の小芝委員からの意見表明のところです。議会の発言の時間というのは、特に制限する方向で動くべきではないと考えていますので、私たちとしましては、特に意見表明の時間に制限を設けることは必要ないと思っています。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"意見","question":"先ほどの小芝委員の意見というのは、意見表明という趣旨に沿った発言をしてくださいと言っただけであって、別に時間の制約をしろとは言っていない中で、なぜ、今、安藤副委員長は時間の制約はすべきではないとおっしゃるのか。そこは、先ほど、委員長からすごく配慮のあるご発言もありましたけれども、当然、いろいろなご趣旨、お考えがあるので、各会派の良識にお任せしたいなというのが感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5502#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":14594,"voices":70}},{"id":"r05-20230526-6","meetingId":"r05-cm05","date":"2023年5月26日","dateIso":"2023-05-26","committee":"区民委員会","time":"午後 ２時５０分～午後 ３時４７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"１つ目、児童参加地域事業補助金に関してになりますけれども、まず、防災対策等の観点からも、町会・自治会活動を通じた地域コミュニティの活性化は必要だと考えております。これまでコロナで自粛していた町会・自治会活動を再開、活発にするために、よい方向性であると考えております。質問ですけれども、今回、申請回数を２回から３回に増やしたという背景について教えていただきたいと考えています。","respondent":"宮澤地域活動課長","answer":"やはり町会・自治会からの声についても、いろいろな事業を、子ども向けの事業をやってみたいという声がありますので、そういった意欲のある町会・自治会での活動というものを後押しするために、３回とするものです。","id":"exchange-001"},{"speaker":"えのした委員","kind":"意見","question":"本当にこれ、物価高騰もありますけれども、コロナ禍で町会・自治会はほとんどイベント・行事ができていなかったと思うのです。やはり子どもたちの経験の場が大分失われているので、体験の場ですとか、大変よい事業だなと思うのですけれども。ちなみに、例えば参加を促すような事業というものは、何か具体例はありますか。","respondent":"宮澤地域活動課長","answer":"児童参加地域事業補助金、これまで受けている町会・自治会の取組なのですけれども、例えばさくらまつりであったり、夏であれば盆踊り大会であったり、例えば秋だとハロウィンイベントという形、またはボッチャ大会だとか、ボウリング大会だとか。","id":"exchange-002"},{"speaker":"えのした委員","kind":"意見","question":"ボッチャやボウリングなどというものも、子どもたちは大変楽しめる、もちろん町会・自治会の方がいらっしゃるので、高齢者が一緒に楽しめるのではないかなと思いますが、（２）に新たに立ち上げた事業とあるのですけれども、その中で本当に新しいなというものはありますか。","respondent":"宮澤地域活動課長","answer":"行っている事業の傾向として、町会・自治会との親睦を深めるというところで、レクリエーションのバスツアー等をやっているところがあります。その中で工夫している事例としては、防災をテーマに防災施設へ行くというような取組をしている町会・自治会もあります。","id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"町会のほうから伺ってまいります。広報のところ、すみません、少し私が聞き漏らしてしまったのですけれども、広報しながわと説明のチラシとホームページのお知らせと、ほかに、もう一度確認できたらと思うのですが、その辺りは区政協力委員会などでも、告知などもしていくのかなと思うのですけれども、どのように伝えていくのかというようなところ。","respondent":"宮澤地域活動課長","answer":"日頃から、町会・自治会に最も近いのが、やはり地域センターになってあります。その中で、やはり町会長・自治会長をはじめとする地域の方々と、常日頃接点があります。その中で全ての町会・自治会に、１つずつ丁寧に説明していきたいと考えております。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"例えばマンションの住民の方が多いなどというところを少し簡単に、まず教えていただきたいということと、あとこちらの冊子のほうは、多分ホームページのほうには載っていないかと思うのですが、動画など、そういったものも紹介があるのかなと思うのですけれども、その辺り、今どのように活用されているのかというところも教えていただきたいと思いました。そちらまでお願いします。","respondent":"宮澤地域活動課長","answer":"そのために、先ほど申しましたとおり、全ての町会・自治会に丁寧に説明していくというところが大事だと思っています。町会・自治会のお話を聞くと、町会・自治会の高齢化や担い手不足というところにつきましては、課題として認識しております。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問","question":"省エネルギー対策設備更新助成金のほうなのですけれども、こちらの説明チラシの配布方法について教えていただけたらと思いました。個人事業主の方にも、ぜひ伝わるような形でお願いしたいなというような思いがあっての質問なのですけれども、お願いします。","respondent":"小林商業・ものづくり課長","answer":"今回の助成金のスタートに当たりまして、その概要といいますか、申請方法をまとめました説明チラシを作りまして、１つは、やはり区内の産業団体を通じて配布をするということもありますし、または区の施設です。","id":"exchange-006"},{"speaker":"横山委員","kind":"確認","question":"は確認になるのですけれども、こちらの２００件というものは、想定というお話があったのですが、上限８０万円に至らないケースの場合は、こちらは別に件数を制限するものではないという理解でよろしかったでしょうか。１０万円以上の設備というところなのですけれども、多分こちらはもともとの都のほうのものなのだと思うのですが、根拠だけ確認をさせていただけたらと考えています。","respondent":"小林商業・ものづくり課長","answer":"申請の内容によりまして、もし金額がそれより少ない助成の申請ということでありましたら、予算の範囲内ではそれを超えるような対応というものもある程度考えております。１０万円のところです。","id":"exchange-007"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。その観点からなのですけれども、このエネルギー価格高騰の影響緩和ということなのですが、例えば電気代であったり、ガソリン代であったり、そうしたものを抑えることができるような１０万円以上の設備というような形で、基本的に考えればよろしいのでしょうか。ちょっとその辺り、確認をお願いします。","respondent":"小林商業・ものづくり課長","answer":"ご指摘のとおり、今回この説明資料の中で例示しているものがありますけれども、実際に今後チラシなり、あるいはホームページをつくるときに、特に限定しているということではございませんが、より例示の数というのですか、そのようなものも増やしながら。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この４の実施期間のところでも、始めているところもあるということだったのですが、この４月からもう申請されている件数がどれくらいあるのか伺いたいということと、あと緊急的支援というように括弧で書いてあるので、これはこの令和６年３月３１日までで、それ以降はもうやらないものと考えていいのか、伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"それと事業の実施期間は令和６年３月３１日までとしておりまして、今回の拡充部分については時限的措置として、今年度についてという状況です。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですから、今回５類になったことで、こうした地域、町会・自治会での賑わい創出やコミュニティの活性化というところ、町会・自治会の皆さんからも、ようやくできるようになったよという、そのような声もいただいているので、否定するものではないのですけれども、やはり新たな感染拡大が懸念されていますし、それが起きたときには感染拡大防止の対応を迅速に取るということを。","respondent":"宮澤地域活動課長","answer":"事業実施に関しましては、模擬店などが出て飲食を伴うものもあれば、いわゆるレクリエーションをするようなタイプというものも様々あります。基本的に地域の事業につきましては、町会・自治会が主体となって企画して進めていくと。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それと、省エネルギー対策設備更新助成金のほうですけれども、１事業者が何個か、資料にも事例がある、例えば冷暖房機器を２個などでも、上限８０万円で５分の４での助成というように、１品のみではなくて、限度はあると思うのですが、何品買っても上限８０万円で５分の４の助成だということでいいのかという確認と、あと区内の中小企業、そして個人事業主。","respondent":"小林商業・ものづくり課長","answer":"もう一つ、事業所数ですけれども、こちらについては国の経済センサスといったような調査も５年に１回行っているのですけれども、個人事業主も含めて、全体がというところに関しては、ちょっと国のほうもそこまでは統計が取れていないので、幅広く事業活動というのですか。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私たち共産党としては、こうした中小業者への物価高騰や電気代、ガス代の高騰に対応する区独自の支援策を進めるべきだということを一般質問等でも求め続けてきているところですけれども、そのときは融資あっ旋等もやっていますという、これまであった事業を説明していただいていたし、あと国や都の動向を見守るという、そのような答弁だったのですけれども、やはり融資あっ旋ではなく。","respondent":"小林商業・ものづくり課長","answer":"１つ目のご質問です。２００件がどのようなところからですけれども、我々のほうで令和４年度に実施しました、新型コロナウイルス等対応助成というところで補正予算を組んだものがあります。","id":"exchange-012"},{"speaker":"藤原委員","kind":"確認","question":"これ、目的が、町会等が事業を再開をしていくにあたり、今度事業に対する補助金を多く下さいという話が背景にあって、コロナ禍が落ち着いて再開するようになって、町会・自治会の予算が足りないからどうにかしてくれないかという声もあって、そのようなことが背景で、補正予算まで組んでやっていこうとしたと思っているのですけれども、まず１つ確認として、それでいいのでしょうか。","respondent":"宮澤地域活動課長","answer":"委員のご指摘のありましたとおり、ポストコロナに移行しまして、活動再開というこのタイミングで支援をするです。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうですよね。なぜそのように言うかというと、今回コロナということはあるのだけれども、長年の、やはり決算でも予算でも、特別委員会の中で町会・自治会への助成金を増やしてほしいというようなお話は言っていますよね。やはりその辺を少し考えていただきたいのです。今回この補正予算に反対しているという意味ではなくて、その辺についてはいかがでしょうか。","respondent":"宮澤地域活動課長","answer":"町会・自治会が行う活動というものは非常に様々と認識しております。例えば交通安全の活動であったり、高齢者の見守りであったり、または防災訓練をはじめとする、町会・自治会独自の活動というものは様々にあります。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"何かこう大きいイベントなどをするといっても、今、最大限で助成する金額は大体１０万円ぐらいではないですか。だったらこのように特筆して書くというよりも、そのお金を２０万円とか、３０万円とかという形に増やして、そして町会・自治会を信頼し、信託し、あまり枠組みを決めないで、全体のお金をもっと大きくして助成したほうが私はいいと思うのです。その辺についてもう１回答弁していただけますか。","respondent":"宮澤地域活動課長","answer":"そういった助成金を活用して、様々な町会・自治会活動に、現状つなげていただいているです。それと併せまして、それぞれの目的に応じた各種補助金の支援メニューというものも用意して、両面で引き続き支援していきたいと思っているところです。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"省エネルギー対策設備更新助成金だからしようがないのだと思うのですけれども、あえて伺います。この区民委員会とは別だけれども、でも、介護のことをしている施設などは、ガソリン代が高くなってしまって大変だというお声が来ているから、介護事業者に対しての助成というものも新たにという話も出ているぐらいではないですか。だから、設備だからやはりしようがないのですよね。","respondent":"小林商業・ものづくり課長","answer":"ただいまご指摘の点ですが、今、直接苦しいのは、本当に現在かかっている、そのようなエネルギー価格といいますか、その費用の部分が苦しいというところで、我々のほうもどのような支援がいいのかということで、ご指摘のようなところも含めて検討いたしました。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどなぜ２００件にしたのかというところで、前回もそのようなことをやって２００件に少し足りなかったぐらいがあったのでというお話、個人事業主も入っているということで、非常に幅が広いなとも思うのですけれども、その辺り、どうしてこのような形になったのかというところをもう少し詳しく教えてください。","respondent":"宮澤地域活動課長、小林商業・ものづくり課長","answer":"町会・自治会の主体的な取組、それを立ち上げて定着できるように、町会・自治会の、いわゆる伝統行事のような形になっていただきたいというところは考えておりまして。我々がこのような助成金をつくるというところで調べた範囲でいきますと、県レベルで幾つか、例えば岡山県など、そのようなところで、金額は県レベルですので、ちょっと大きいところで１００万円などとありますけれども。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。先ほど藤原委員からもありましたけれども、直接ガソリン代とかそういうところに支給、幾らあっても正直足りないと思うので、そのようなところをこういう、ちょっと間接的な支援というか、設備更新というところで知恵を出されたのだなというところで、なるほどなというところ、しかも個人事業主まで、業種含めて広いというところでいいアイデアだなと思ったので質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"せらく委員","kind":"質問","question":"私も、町会・自治会の拠点となる会館がまだまだ整備されていないという現状を伺ったところでしたので、その拠点に対するお考えを、もしございましたらお聞かせいただければと思います。","respondent":"宮澤地域活動課長","answer":"町会・自治会の会館という部分に関しましては、新たに新設する部分、もしくは建て替える部分というところで、補助金のメニューというものを用意していますので、物件探しからなかなか難しいところではあろうかと思いますが、そういったものも相談を受けながら。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"この児童参加地域事業補助金のところについては、要望として先ほどちょっと申しそびれてしまったので、賛成の中でお伝えしたいのですけれども、今後、２０１ある町会や自治会、今まで使っていない町会・自治会にも使用いただけるようなきっかけとか、仕組みづくりをご検討いただきたいというところでございました。すみません。賛成の表明の中でのコメントで恐縮ですが、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それと省エネルギー対策設備更新助成金のほうは、これも賛成ですけれども、コロナで疲弊した上に、さらに物価高騰、そして電気代、ガス代の値上がり、本当に大きな打撃を受けている中小業者に対しては、今ほかの委員からも様々ありましたけれども、私たちも常々求めてきた直接支援、やはり電気代、ガス代だけでなく、家賃、そして機材のリース代、そしてメンテナンス費など。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238887?Template=document&Id=2956#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":18460,"voices":68}},{"id":"r05-20230526-7","meetingId":"r05-cm05","date":"2023年5月26日","dateIso":"2023-05-26","committee":"厚生委員会","time":"午後 ２時５５分～午後 ４時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"ご説明ありがとうございました。そこのこの通知との、今回の品川区が出されたということの関係を教えていただきたいのと、そういうことからすると、６月議会ではなくて、今回の臨時会にこういう形で提案されるということは、今まであまりなかったような思いがするのですけれども、この臨時会に提出をされた、提案をされた、その理由も併せてお伺いをさせていただきたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"なぜこの臨時会かですが、３月２２日、２９日、そして４月１２日と、３本にわたって事務連絡等々が出ている中、一刻も早く区民の皆様に給付をしたいという思いから、一番早い段階でのご議決をいただくことを想定しまして。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"私は、この文章を読んだところでは、計画を出して、その計画に基づいて調査を５月頃に実施、予定して、それで限度額の通知が６月下旬と書かれていたので、その後になってくるのかと思ったのですけれども、限度額、品川区に幾ら来るのかというのは、計画を出す前に品川区に通知がされるということで、そこら辺のところは、品川区から働きかけることで。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"計画については、あくまで任意とはなっておりますが、一応、５月２９日という日付がありますので、それは我々でも認識して、現在、準備を進めているです。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"確認","question":"分かりました。これを見ると、令和５年度も３回にわたって臨時交付金を出す方向ということで書かれているのですけれども、ということは、今回が終わりではなくて、この後１０月と、あと冬という形で出す方向が書かれているのですが、そういう方向で検討されているということでいいのか、その点も確認させてください。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）、若生健康課長","answer":"計画を３回に分けて提出するということは書かれているのですけれども、給付金が３回とは我々は認識しておりません。なので、ひとまず今回のこの給付金を速やかにお出しするということで、現在、動いているものです。今回、様々、エネルギー・食料品価格等の物価高騰の影響を受けた多くの区民ですとか事業者の皆様に対して、限りある財源の中でどのような形で支援策を講じていくかというところは、区としても総合的に検討した結果。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今後に向けてということに今回はなってしまうと思うのですけれども、医療にしても、それから公衆浴場などについても、推奨事業メニューの中にも書かれていることですので、ぜひ支援のほうはご検討いただきたいということで、要望させていただきたいと思います。それをお願いします。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"国からの通知で、低所得者世帯に向けたという枕言葉がございましたので、まずは国の示す基準といいますか、通知にも書かれていましたとおり、非課税世帯を対象にするというところで動き始めたところ、長いコロナ禍の中、苦しんでいる人がいるであろうというところから。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その点も確認させていただきたいのですけれども、そういうことで言えば、例えば、暮らし・しごと応援センターに相談に来る方、それからハローワークだったり、サポしながわだったり、シルバー人材センターだったり、そういうところに相談に来られる方というのは、失業してこれから生活が成り立たなくてどうしようという相談の方というのは、こういうところにたくさん行かれると思うのですけれども。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"周知の方法ですが、暮らし・しごと応援センターも含めて、今後の周知方法につきましては、まだこれから今いろいろ最終的なところを詰めている段階ですので、ありとあらゆるところで網を張って、知らなかったということが起きないように。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、今まではそういうところに徹底して、こういう給付金という制度があるので対象者にはぜひ知らせてほしいというところは、暮らし・しごと応援センターだったり、ハローワークだったり、サポしながわとか、そういうところには、今まで２回、家計急変世帯のところを対象にした給付金というのが行われたということなのですけれども。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"ただ、今回も前回も含めて、在宅介護支援センターであったりとか、障害者の地域拠点相談支援センター等々についても、チラシ等々でサポートはしてございましたので、引き続き委員ご指摘のセンターであったりとか、新しいところも含めて周知を図っていくというふうに。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"続けてやってしまっていいですか。では、皆さん質問したいと思いますので、一旦、取りあえず終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"何点か確認をまずさせていただきたいと思います。先ほどほかの委員から、この臨時交付金については、またほかの時期に来るという話もありましたが、それは総務だったり、あるいは企画のほうで割り振りをして考えることだと思うので、その点についてはご説明等は難しいと思いますけれども、いわゆる６月の値上げということも踏まえての算出をされているのか、その辺をまず伺いたいと思います。お願いします。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"それから次に、６月からの値上げを含めてのものなのかということなのですが、今回はあくまでも対前年比のものを算出根拠としておりますので、今後、値上げ分ですとか、どういう影響があるのかについては。私からも同様なご質問についてお答えするところなのですけれども、今、障害者支援課長がお答えしたとおりの形で、高齢の介護サービスのほうも算出根拠を出していますので、同様だということでお話をします。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"３月２８日、私ども会派としても、区長に緊急要望させていただきました。大変に評価いたします。そこで、この均等割ですけれども、文言の一つ、理解を深めたいところなのですが、２番の(2)の下にある米印、ここに書かれている、特別区民税所得割が課税されている者の扶養親族等のみからなる世帯を除く、いわゆる均等割世帯だけ、これはどういう世帯をいうのか、ご説明をお願いしたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"世帯がありまして、お父さんとお子さんで考えると一番分かりやすいのですが、お父様お母様のどちらかが課税されていると。その課税されている方から、税法上の扶養されているこちらのお子さんは対象になりませんと。そういった意味の文言です。","id":"exchange-009"},{"speaker":"こんの委員","kind":"確認","question":"分かりました。そこは確認させていただきました。もう一つ、申請方法なのですけれども、また、申請をされてからの支給までの流れについて確認というか、したいと思いますが、前回、支給をされた方の口座とかのデータがあるということなので、それを印字して通知をしてくださる。コールセンター、前回は何人体制で、何時から何時までそれを受け付けてという体制を取っていたのか、その辺も伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"コールセンターですが、今、最終的な詰めを行っている状態ではありますが、６名から１０名程度のコールセンターで進めていければと考えています。今、最後の詳細を詰めている段階です。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、要望でしておきます。もう少し早く支給ができるようにならないのかという思いから、システム改修という費用が出ていますけれども、このシステム改修、前回のときもシステム改修されて、今回もシステム改修の費用が入っていて、前回のデータを基にというこの通知の仕方も一つある中で、これ、改修にやはり時間がかかったり、必要なのでしょうか。その辺のところを伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"システム改修につきましては、やはり回数を重ねるごとに、まだいろいろどうしても必要になってくるのと、ある程度時間がかかって、改修した後の検証期間も当然必要になってまいりますので、ある程度の日数が必要とご理解をいただければと思います。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"分かりました。最後、妊婦健診のことについてお伺いしたいと思います。こちらは１回を４回まで追加をしてくださるということで、たしか東京都で年度末でしたか、決定して、こういう流れになったと理解をしているのですが、その辺の流れをまず確認をさせていただきたいのと、あと、こちらは多胎児妊娠の場合は、超音波の検査はどのようになるのでしょうかというところです。","respondent":"若生健康課長","answer":"こちらの事業の東京都の補助の情報が、実際は一番最初に区に周知があったのが２月中旬頃でして、そこで東京都の令和５年度の補正予算でということでしたので、区の当初予算として盛り込むことが現実的には難しかったというところが１点ございまして、その後。","id":"exchange-012"},{"speaker":"こんの委員","kind":"確認","question":"多胎児妊娠の方については、直接お声をいただいているわけではないのですが、疑問として、お一人のお子さんの健診と、やはり多胎児というところで、より慎重にというか、そうした検査も必要ではないのですかという疑問のお声も区民の方からいただきましたので確認をさせていただきましたが、今後、もしそういうことになれば、都でも、また、国でも、厚生労働省から出ている指針は４回と出ておりますので。","respondent":"若生健康課長","answer":"ご指摘というか、ご案内がありました、国の妊婦に対する健康診査について望ましい基準という告示が、一応、単胎、多胎というのは区別せずに、妊娠期を通して４回というところはあるものの、現在、国でも。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"ありがとうございました。多胎児のところは、ぜひ動きを注視していただきながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"筒井委員","kind":"確認","question":"基本的な確認なのですけれども、新型コロナウイルス感染症対応地方創生臨時交付金についてなのですが、ただ今回、補正予算の財源が都支出金ということになって、１０分１０ということなのですけれども、このスキームは、この理由は、交付対象者は直接区でもいいと思うのですけれども、何で一旦都を挟んで区に行くという。〔「所管外ではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"款はどこの所管になるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"筒井委員","kind":"確認","question":"総務に確認をします。先ほどからほかの委員からご質問があったと思うのですけれども、６月から電気代が上がるということですが、その一方で、住民税非課税世帯等物価高騰対策支援給付金のところで、家計急変世帯が５００世帯を見込んでいるのですけれども、これ、電気代の値上げによってはもう少し増えてくるのかと考えているのですが、その場合の対応というのはどのようにお考えなのでしょうか。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"家計急変の考え方は、あくまで収入が急変した世帯という考え方ですので、値上がり等々の対応ということでは、この考え方はないということをご理解いただければと思います。","id":"exchange-017"},{"speaker":"筒井委員","kind":"意見","question":"妊婦健康診査、超音波検査についてなのですけれども、これは東京都からの事業だと思うのですが、超音波検査は、その意味というか重要性、そもそも超音波検査をやる意味と、回数を増やすと効果が上がってくるという。どういった理由でこの回数を増やすのかというところをお教えいただければと思います。","respondent":"若生健康課長","answer":"超音波検査をやる意義ですけれども、当然、妊婦健康診査自体が、妊娠期の妊婦の健康状態ですとか、あとは、お子さんの発育状態というところをまず定期的に確認することによって、出産に向けての、そういった様々なリスクというか、そういった状況というところを。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、望ましい基準として、一つ、国の基準を参考として、４回という数字が出てきたということでよろしいのでしょうか。","respondent":"若生健康課長","answer":"こちら、４回というところの根拠としては、国の基準に基づいて設定されていると認識しております。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"確認","question":"先ほど介護サービス事業のところと、あと、障害福祉サービスのところの支援金について、その算出方法を前年度の定員１人当たりの物価上昇率から算出しているというお話だったと思うのですけれども、ここのところの算出の金額というのは、物価高騰に対するカバー率というのはどのくらいなのかと思うのと、あとは、どのぐらいの期間の補助ができているのかというのを確認したいのがまず１点。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"電気代もさらに上がるということもありますので、先ほど障害者支援課長からもお話があったと思うのですけれども。今、高齢分野の考え方というのは、障害分野でも同じということですので、期間についても１年間ですし、算出根拠につきましても。私からも、使途についてのコメントがなかったので、お話ししますが、今、障害者支援課長が言ったとおり、特に今回使い道については、交付金ですので。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問","question":"とても分かりやすかったです。先ほどカバー率のお話を聞いたときに、施設によって不足しているところが出ているというのがあったのですけれども、逆に足りているというところもあったのか。足りていないところに対する今後の対策とかはどのように考えているのかというのをお聞きしたいです。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"やはり入所の部分につきましては、今後、６月の値上がり分も含みまして、事業者自体も省エネとか、努力をしていただいたり、あるいは、ただし入所者の安全がやはり一番ですので、入所者の健康・安全。ただし、通所施設がそれで黒字になっているかというと、実態としては、コロナ禍によって利用者数のやはり減少があったりとかして、光熱水費がかかるという以前に収入自体が下がっているという実態もありますので。","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問","question":"よろしくお願いします。私自身は一従業員といいますか、経営者ではないので、直接懐に入るわけではないのですけれども、非常に助かっております。令和４年度のことを含めてのご質問なのですが、今回、介護施設、障害者サービス事業所も含めてなのですけれども、どういったスキームといいますか、流れで支給の受付というか、支払いをするのかということをお伺いしたいのですけれども。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"前回の１２月補正のときも、１回目１月３０日、年末年始があったので、１回目の締切りは１月末ということで締め切らせていただいたのですが、その際に、やはりどうしても事業者によっては。前回もメール等で事業者に一斉通知をいたしまして、３回に分けて、やはり障害分野でも交付決定ということで支給をさせていただきました。","id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"質問","question":"非常に素朴な疑問なのですけれども、恐らくほとんどの事業所が、頂いてありがたいということで、ほぼ全ての事業所は以前も申請をしていると思うのです。これ、申請しないで、区のほうから、こういう感じで支払いますということで頂くということはできないのでしょうか。やはり現場の業務は煩雑というか、申請業務とかが大変だと思うので、そういうことは難しそうでしょうか。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"ちなみに、前回の１２月補正のときの支援金につきましては、１３１事業所に対して１１７事業所が申請しているということで、９割弱のところが申請をしていただいておりますので、おおむね普及されていると思います。申請いただけなかった方につきましても、３回に分けてというのは、何度も勧奨させていただいて、ぜひ申請してくださいということを申し上げたのですが、その施設、あるいは法人や事業所によって考え方等々がありますので。","id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういったので、メールが受信されて、「品川区」と書いてあっても、もしかしたらウイルス、迷惑メールなのではないかと思って、忙しいと、ぱっと見ないでいると、だんだん下のほうにそれが行ってしまって、見逃してしまうということがあったりして、本当にそういうので情報が漏れてしまったりすることもあるので、ぜひそういった周知の方法も、メールだけではなくて、郵送とかも併せていたりすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"おぎの委員","kind":"質問","question":"私は、妊婦の超音波の健診の案件に関してなのですが、最後の補正予算額、３の(2)の歳出の部分、超音波を１人当たり３回増やす、その回数ごとに医師会に事務の委託料と国保のほうの支払委託料という認識でいるのですが、超音波の件数３,８３８件と、2)番3)番３,６１８件というのは、この件数の違いというのは何かあるのでしょうか。","respondent":"若生健康課長","answer":"こちらが、いわゆるこの受診券を利用するところ以外で、里帰りですとかで出産された方というのは、この受診券を使わずに、後で償還払いという形を取っているものですから、そういったような対象の方については、委託料というところがそもそも発生せず。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、私は実際は超音波検査というのは、厚生労働省は望ましいというところが４回ということで言っているので、少なくとも４回はやるべきでしょうということでこの間も求めてきましたけれども、でも、実際はほとんど毎回超音波検査はやられていると、実際に出産した人からは聞いているのですが、そこら辺のところの実態をつかまれていたら、教えていただきたいと思います。","respondent":"若生健康課長","answer":"超音波検査のこちらの４回というところへの増というところの話ですけれども、こちら、いわゆる２３区というか、東京都と都内の区市町村と、あと、東京都の医師会も含めた５者の協議会、五者協と言われている仕組みがございまして、こういった妊婦健診の公費負担の水準。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ支援していただきたいと思うのですけれども、もしコロナの臨時交付金で足りなければ、一般財源を充ててでもぜひやっていただきたい問題ではないかと思うのですが、その点について伺いたいと思います。","respondent":"豊嶋生活福祉課長（生活支援臨時給付金担当課長兼務）","answer":"委員おっしゃるように、ほかの自治体もやっているというところと、ほかのメニューからうまく拾えるのではなかろうかですが、その辺りを含めて、企画部のほうで今現在調整を進めておりまして。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"エアコンについては、毎年毎年本当にこれは問題になるところでして、特に今年もすごく暑い夏がこれからやってくることになってくると思うので、ぜひエアコンがないために、命に関わるようなことがないための、そういう対応というのはしていただきたいということで、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほどの私の質問の少しだけ補足なのですけれども、こういった事業所への通知をいただく際に、一番恐らく証拠として残りやすいのがメール、次がファクス、最後、電話という順番になると思うのですけれども、通知したというのが証拠として残ります。というか、もしできれば、ペーパーレス化も進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3658#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":30365,"voices":97}},{"id":"r05-20230526-8","meetingId":"r05-cm05","date":"2023年5月26日","dateIso":"2023-05-26","committee":"建設委員会","time":"午後 ２時５１分～午後 ３時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３１号議案、令和５年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"約２,４００万円で補正を組んだということですけれども、今回、補正で予算を組んだという理由を伺いたいと思います。ヘルメットの安全基準の認証を受けているものということなのですが、それは、すぐに区民の方が見て分かるものなのかどうか、どういうものが必要なのかというのを伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"補正でこの助成を行った理由ですけれども、当初は、４月１日からヘルメットの着用努力義務化になりましたので、着用すべく、しっかり自分で交通安全を守っていただいて、ヘルメットを自分で購入していただいて、安全運転に努めていただくということで広報を実施してまいりました。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、こういった仕組みにした理由ですが、一時的に区民の方が負担することになってしまうわけなのですけれども、他区ではお店の窓口で、既に値引きして購入できるようにもしているので、そういったこともできなかったのかなと思うのですが、今回こうした仕組みにした理由を伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"一例を挙げますと、安全基準の関係なのですけれども、ヘルメットの写真を撮って、これが安全基準に合致しているものかどうか、添付してもらおうかということも検討はしたのですが、またそれも区民の方の負担になるというところもありますので、そこは自己申告ということで。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ希望する区民の方が諦めることがないように、利用しやすい仕組みにしていただきたいということは、改めて要望しておきたいと思います。他区でも数年間、事業期間が継続するところもありますので、品川区としても１年だけでなくて、継続してもらいたいと思うのですが、いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"予算を超えた申請が来た場合のお話ですけれども、こちらとしましても、先ほど少しお話させていただいたとおり、より多くの方にヘルメットをかぶって事故防止に努めていただきたいという思いがありますので、もし１万人以上の申請があった場合には、状況を見てですが。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか質問いたします。目標が今の２倍とおっしゃっていたと思いますが、どの数値から２倍なのでしょうかということなのです。それから、区内共通商品券を使うということになると、現金でもいいではないですか。なぜ商品券なのですかということなのです。これに入っていないと対象外になるわけです。そうなってくると、どれだけ入っているのでしょうかと。そういった場合に、対象外になるということですか。","respondent":"工藤交通安全担当課長","answer":"それを基に、ヘルメットの着用率を２倍にしたいということで考えまして、先ほどと重複するのですけれども、区内の自転車防犯登録台数が約３７万台ということで、そちらの３％が約１万１,０００台、それを倍にするということですので、さらに１万台。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"家族が対象という書き方になっていると思うのです。保険に入らないともらえないのかということではなくて、それは入ることに意義があるということで、その周知をしっかりやっていただきたいと要望したいと思います。なので、その辺も難しいと思いますけれども、市場の状況を見てからの啓発活動というのも考えていかないといけないのかなと思いますが、その辺はいかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"区民の方により分かりやすいように、どういったものが対象になるのか、どういったものが必要なのかというところは、しっかり周知していきたいと考えております。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"１万人に対して２,０００円という金額が、果たしてヘルメットを購入するに当たって、どれだけ区民の方にとってプラスになるものなのかどうか、どういう受け止めをされるのかというところの観点で伺いたいのですが、すみません、私も不勉強で恐縮ですが、一般的にヘルメットというのは価格帯がどれぐらいなのか。","respondent":"工藤交通安全担当課長","answer":"２,０００円の補助というところなのですけれども、こちらは、既にヘルメットの購入助成を実施している区が、２３区内で５つの区がやっておりまして、そういったところを参考にさせていただきながら、やはり２,０００円を補助して、大体これで。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"他区の事例を参考にされたということで、特段不満の声はなかったということではありますが、今後参考にしていきたいのですけれども、他区で、２,０００円補助したことでどれぐらい着用率がアップしたのかという、そこまでの評価はされていらっしゃるのでしょうか。","respondent":"工藤交通安全担当課長","answer":"他区の着用率の関係については、他区でそういった調査というのは行っていないというところで把握しておりますので、現状のところは、すみません、分かりません。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"まだ商品券を戻す２,０００円に活用するという視点で、もう一工夫というか、その意味合いにまだ納得というか、すとんと落ちてこないところがあるのですけれども、商品券を活用する意味というか、意義というか、そこをもう少し加味していただけるといいのかなと思うのですが、その辺はいかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"それで、自転車商から区に申請をしていただいて、自転車商にバックするということを想定はしていたのですけれども、なかなかそれが自転車商のほうで難しいかなというお話をいただいたというところがあります。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"目標６％、つまり、逆に言うと９４％は、まだ需要があるということですので、そういう意味でも、自転車商の方との協力も得ていただきながら、自転車商の方も、その先に値引きをということも受け入れてもらえることも含めて、いろいろご協力いただけるような形で、１００％につなげていただけるような制度にぜひしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"歳入のほうで東京都からの補助ということで、そこが額でいうと４００万円、自主財源があるという中で、本来的には努力義務規定も全国的な展開なので、もう少し国や都のリーダーシップがあっていいかなという思いがあったので、ちなみに東京都からの充当事業の中で、交通安全啓発費は全般なのか、それとも一定程度、何か想定的なものだとか、推奨するとか、そういった意味合いがあったのか、あるいはまた別途。","respondent":"工藤交通安全担当課長","answer":"東京都の補助の関係なのですけれども、今のところは４００万円上限ということでお話を伺っているのですが、都内の状況等を鑑みて、果たして４００万円でいいのかどうかというところの検討はされているということを伺っておりますので、まだ都でも要綱等が定まっていないですので。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、初めての展開ということもあって、多分、非常に品川区は早い時期に展開されるので、モデルケースであり、あるいは、品川区民にとってはまだまだパーセンテージの上がり幅が必要だと思いますので、柔軟にこの政策を進めていくという解釈と、自主財源がこれだけあるということで、投入したということは意識が高いと好意的に捉えてはいるのですが、その辺の抱負と。","respondent":"工藤交通安全担当課長","answer":"そういったところで、少しでも事故を減らして、あと、大きな障害を負うような事故ですとか、もしくは命を失うような事故というのはあってはならないと考えていますので、そういったところが絶対ないように。","id":"exchange-011"},{"speaker":"若林委員","kind":"意見","question":"何点か、ダブらないように。物価高騰対策の視点が入っているということで、資料ではたしかそういう表現はなかったのですが、冒頭のご説明、また今の質疑の中でも、区内の還元みたいな観点でもありました。物価高騰対策という視点で、まず、この事業をもう少し総合的にお話しいただければと思います。","respondent":"工藤交通安全担当課長","answer":"物価高騰対策の面ということでお話をしますと、電気代とかガス代、その他生活必需品、もろもろ値上がりしているといった中で、少しでも区民の方々がヘルメットを購入できるように、もしくは商品券を使って日常生活品を買えるようにといったところで。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"ただし、申込みが５月１日から６月３０日までの限定的な期間ということで、開始時期はまだ質問がなかったので、大体の開始時期をお聞かせいただきながら、そうすると、６月３０日に区民交通傷害保険が既に締め切られているということで、ここの保険料が安いということもありますので、早め早めに、先ほどから周知は早めにということがありましたけれども、特にこの部分については。","respondent":"工藤交通安全担当課長","answer":"初めに、購入助成の開始時期の件です。現在、鋭意推進中ですけれども、７月の中旬頃を目途に頑張って作業を進めたいと考えています。失礼しました。そこのところは今、検討中ではあるのですけれども、簡易書留に封書と商品券とを入れ込むことが可能ということもありますので、そちらは１回でできるような形で検討していきたいと考えております。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにしても、今回、助成制度ということですけれども、大事なのはヘルメットの、各委員もおっしゃっていますが、啓発・普及が最もこの事業の真の目的であって、早めの助成制度の周知とともに、それよりもまずは、今の安全基準も含めたヘルメットの普及を、例えば死亡率が２割、かぶっていない人とかぶる人で違うとか、よくニュースでも出ていますけれども、そういうことも真っ先にというか。","respondent":"工藤交通安全担当課長","answer":"そういったところの検査をやっていると認識をしております。いろいろ、ヘルメットをかぶらなかったときの死亡率の高さとかというのは、これまでも周知を図ってきておりますけれども、引き続き、より分かりやすいように周知に努めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"若林委員","kind":"意見","question":"もう１個だけ。ヘルメットの購入にも、保険に加入という意味で使えますよと。今の意味は分かりましたか。要するに、いつもは６月３０日で締めてしまうのだけれども、７月１日からの保険適用期間で１年間なのですが、７月５日、１０日、７月末に加入しても、あなたは６月３０日までの１年を切ってしまっているけれども、保険証を発給しますよという工夫ができないのかなと。","respondent":"工藤交通安全担当課長","answer":"その辺の部分についても、今後、制度の構築という面で検討させていただければと考えています。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/216259?Template=document&Id=4376#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":17248,"voices":54}},{"id":"r05-20230526-9","meetingId":"r05-cm05","date":"2023年5月26日","dateIso":"2023-05-26","committee":"文教委員会","time":"午後 ２時５０分～午後 ４時０２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"第３２号議案 専決処分の承認を求めること","agenda":"第３２号議案 専決処分の承認を求めること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"給付対象者の数です。ちょっと全体像を把握したいので伺います。今回、人数で言うと合わせて４,９００人ぐらいということです。これは区内のお子さんのうち、およそ何％ぐらいに当たるのか。給付の対象になるのか、伺いたいと思います。世帯数は３,２００世帯ということだと思いますが、これは何％ぐらいになるのか。もし分かればそちらもお願いしたいと思います。もし分かればお伺いしたいと思います。","respondent":"飛田子育て応援課長","answer":"ですので、そこからちょっと割るとパーセンテージが出るのかなと思いますが、ちょっとそこは計算しないとすぐは出てきませんが、大体そのぐらいの数字となります。他区の状況です。専決を予定しているところは、品川区を入れて７区あると聞いております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"３万６,４００世帯のうち今回３,２００世帯ということで、大体１割弱ぐらい、１割に届かないという感じの全体像なのかなと思いました。専決処分については、なるほど、そういう対応ということなのですね。最後です。自分たちの世帯が該当するのかどうかということが、まずはっきり分かることが必要だと思います。ここら辺の工夫をしていただきたいと思いますが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"令和３年、４年とやっておりまして、そこのところで周知のほうは、３階の生活保護担当の部署や、こども家庭支援センターというところにもチラシを置かせていただく。しながわパパママ応援アプリなどでも周知します。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、受けられるのだけれども自分が該当するのか分からないとか、あるいは申請し忘れたという方がないように、チラシがあるということですので、そういったものをちょっと引き延ばすのか、ポスター風にするなどして、今言ったような施設だけではなく、例えば保育園など子どもの施設、児童センター等にも周知を充実していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問","question":"１点質問です。今までも同じようなスキームでやられた令和４年度の特別給付金というのがあったと思いますが、申請不要の方はいいのですが、申請をされる方の受給率というのがどのくらいになっているのか。","respondent":"飛田子育て応援課長","answer":"令和３年４年と同じようなスキームでやっています。対象者で辞退する方が、実際２人、３人程度いらっしゃるのが現実です。例えば海外で収入を得ている方は、日本の税務の外になるので、そこまでしなくて大丈夫ですということでお断りになる方もいらっしゃいます。","id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問","question":"二、三人はお断りされたと言っていますけれど、全ての方が受給されているということでよろしいのですか。そうすると、先ほど安藤委員からも周知をしっかりやってほしいという話もありましたが、では、今まで令和３年、４年とほぼ受給率１００％だったら、別に周知する必要もないのですが、そこに矛盾があります。受給率が本当に１００％、９９.９％だと思うので、それをもう一回教えてください。","respondent":"飛田子育て応援課長","answer":"そこのところは私たちでも分からないところは実際ありますが、そういうことがないように周知はしっかりしていきたいと思います。家計急変の方などは、今までは収入でこういう制度があることを知らなかった方にも行き届くように周知していきたいと考えております。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"最後にします。申請をされるということは、この対象者なわけです。こういった困窮された方には本当に重要な補助金だと思うので、受給率１００％になるよう、間違いなくやっていただきたいという思いがあって、今、受給率等を聞いています。要望にしますけれど、先ほどお話もありましたが、しっかりと周知していただいて受給率１００％、対象者が全員もらえるように対策をしてください。もしあったら。","respondent":"飛田子育て応援課長","answer":"今回の受給は、児童扶養手当をもらっている方は申請なしで、もう１００％は行くようにやっております。ただ、家計急変の方というところで、今までそういうことを知らなかった方がやはりいるかもしれませんので、そういうところに分かるように周知を徹底していきたいと思います。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、１つ。コールセンターを５月８日に設置したということですが、これは、区の職員の方がコールセンターの担当になったのですか。それとも、どこかの業者に委託というか頼んだのか。そこを教えてください。","respondent":"飛田子育て応援課長","answer":"こちらのコールセンターは、委託をお願いしまして設置させていただきました。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうすると、４月２７日に専決しているのですが、その間ゴールデンウイークを挟んで５月８日にもうコールセンターができるということは、いつ委託の方と交渉して、金額を決めたのか。委託をしたときの仕組みを教えていただきたいのと、あと、どれだけの金額で委託しているのかということです。","respondent":"飛田子育て応援課長","answer":"これは毎年やっていたので、国の通知が出た時点ですぐにコールセンターの契約の予算を立てて、執行の準備をさせていただきました。コールセンター委託費は、１,１６１万６,０００円という額となっております。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"なぜ伺ったかというと、コールセンターを設置したのがスピーディーでいいという意味でお尋ねしています。ですから、ほかのいろいろな状況でもそのようにスピーディーにコールセンターを設置して、あと、もろもろの準備をなさって、できるだけ早く支給したいという区の姿勢が出ていると思うので、このコールセンター設置についてはスピーディーでとてもいいと思いました。","respondent":"飛田子育て応援課長","answer":"こちらはもう昨年度もやっている実績がありますので、随契で委託の契約をさせていただきました。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"このようにスピーディーに対象の方に渡るような、こういった施策の進行はとてもいいと思いますので、あとは順次支給のところも、６月以降のところはきっと時間がかかると思いますが、そこをスピーディーにお願いします。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"確認","question":"ちょっと確認です。必要な方に漏れなく周知がされるようにというのは、皆さん、同じ思いだと思います。制度を知るのがすごく遅れてしまう方も中にはいらっしゃるかなと思います。特にここには明記されていないのですが、少し期間がたってしまっても受給できるのか。いつ頃までに申請しなければいけないというのは、どこかであるのでしょうか。その辺をちょっと確認させてください。","respondent":"飛田子育て応援課長","answer":"今回のところは家計急変ということで、今後もいつあるか分からないというところもありますので、それを含めまして、令和６年２月２９日まで受け付けるというふうになっております。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"品川区議会公明党としましても、緊急要望、予算要望してきた内容で、非常に歓迎したい内容であると感じております。先ほどからもお話があったとおりで、受給漏れがないように、より一層の周知を図っていただければと思います。異議はございません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"第３１号議案 令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３１号議案 令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区独自の給付金の支給のところです。これは申請は必要ないということでよろしいのかという確認と、あと財源です。これは一般財源、基金繰入金からなのかという確認をさせていただきたいと思います。併せて、なぜ今回、国の対象にならない世帯にも区独自に支給を行うことにしたのかというのを伺います。昨年１２月にも同じような支援をしたわけですが、単価が、在園児１人当たり１万１,０００円でした。","respondent":"飛田子育て応援課長、石井保育支援課長","answer":"なぜ、今回、国とまた別枠ということですが、国のほうでまた給付金を支給したということで、区独自でどこまでできるかということで区内でも検討を進めておりまして、区内の財源と特定財源がなかなか見込めないということで。そのため、当初予算編成の時期には国の事業のみ予算計上しておったところですが、今回、東京都の情報が分かり次第、速やかに事業を実施できないかということで、この時期に補正予算を提出させていただいたところです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"区独自給付は高校生については要申請というところなので、これについても申請漏れがないような周知をぜひ工夫していただきたいと思います。電気代が下がっているという認識は全然一般にはないですし、今後さらなる支援措置を行うべきだと思いますが、今回はこれで出されていますので別に反対するものではありませんが、今後さらなる支援が、措置が必要だと思いますが、いかがでしょうか。","respondent":"飛田子育て応援課長、石井保育支援課長","answer":"今回、物価高騰の影響というのは、やはり本当に生活が困窮しているということで、国の給付とならない世帯にも相当波及しているのではないかということで、非課税世帯だけでなく。ただ、もちろんこの後、こういった物価高騰の流れがどのようになるかは不明ですし、国や都がどのような支援をするか。そういったことも含めて状況を注視してまいりたいと考えています。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"物価については、もう明らかに６月から上がるというのが分かっているわけですから、こういうのを組んでいくのも大変なことだと思いますので、ぜひ先手先手で、やはり実態に合った支給の額に支援を強めていただきたいと思います。その上で幾つかお伺いしたいのですが、これもそうなのですけれど、財源を確認します。一般財源、ここで基金繰入金ということでよろしかったでしょうかという確認です。伺います。","respondent":"柏木学務課長","answer":"これに基づきますと、基本的には、運営等に関わるもの、経費については、学校設置者が実施するものであるという考えです。そういうこともございまして、私立・国立等への無償化については、現時点では検討は行っておりません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"義務教育無償化というのはもう憲法で定められているわけですから、国が本当はやらなくてはいけないことだと思いますが、今回、国を動かそうという意味でも、品川区がやったというのはすばらしいことだと考えています。検討していないということですが、ぜひ検討していただきたいと思います。実施するに当たって何か課題みたいものというのは、区としては今現状どう考えているのか。最後に伺いたいと思います。","respondent":"柏木学務課長","answer":"ただし、現在は東京都は給食費の無償化はしていないというのと、説明の際にも申し上げましたが、都立特別支援学校に就学している児童は、区立の学校に就学するのが困難ということで進学している経緯がありますので、今回、都立特別支援学校については。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問","question":"２点お伺いします。１点目が、低所得の子育て世帯に対する給付金の中で、補正予算でシステム作業支援委託が計上されていますが、これの具体的な内容を教えてください。空き定員の預かり事業ですが、対象児童は、保育園等を利用していない原則０から２歳児ということで、対象者数を教えてください。これは９施設で予定されているようですが、受入れの人数がどのくらいになるのかを教えてください。","respondent":"飛田子育て応援課長、石井保育支援課長","answer":"今回、システムの内容ですが、まず、今持っているデータシステムの構築のほうからデータの抽出、また抽出のデータの作成、また、両申請データの抽出、また、その台帳。受入れ人数ですが、事業を実施する保育所の定員の空きの状況に左右されるものですので、そういった状況により変動するものと認識しています。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"システム作業ですが、以前からもずっとお伝えしていますが、例えばこれは４００名に対して８００万円かかっているということですよね。あくまで４年前の話ですけれど、今でもこうやって出てくるということは多分そうなのでしょう。特に多分一番そういったシステムを使われている課なのかなと思いますので、ぜひその辺はよく検討していただきたいなと思います。これは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"せお委員","kind":"質問・要望","question":"すみません。何点かお聞きします。そこなのですが、対象児が４,６００名ほどいらっしゃるということで、どのようにこの対象児を集めていくのかなという、方法などを教えていただければと思います。ベビーシッターとかもありますし。そういったところの何か相談する場所とか、こういうときにここを使ったらいいみたいなことを教えていただけるところがあれば、聞かせていただきたいと思います。","respondent":"石井保育支援課長、柏木学務課長","answer":"いかんせん、まだ９施設ということで、４,６００名に対して全てを把捉できるものではございませんので、そういった検討会などで検討しながら、周知方法ですとか使いたい方に届けるように事業を進めてまいりたいと考えています。私からは、特別支援学校のアレルギー等のためお弁当で、給食を食べていない方の対応についてです。","id":"exchange-019"},{"speaker":"せお委員","kind":"質問","question":"ごめんなさい、給食費については理解しました。空き定員を利用した事業も、本当にもう様々あって大変ありがたいですけれども、皆さんも結構分からなくなっているところがあるので、丁寧に教えていただけたらなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。今のせお委員の質疑で空き定員のところですが、もう一回だけ確認させてください。対象児童が４,６００名います。これからピックアップしていきます。ちょっと実施期間的には結構タイトになっているのかなと思いますが、その辺のところをこれからどういうふうに組まれていくのかということをお知らせいただきたいと思います。","respondent":"石井保育支援課長","answer":"したがって、補正予算の議決をいただきましたならば、補助要綱の策定をまず速やかに行い、それで各園に周知を行った上で、事業が速やかに実施できるように体制を整えてまいりたいと考えています。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"そのときの対応。なかなか現場の保育園や幼稚園だけでは厳しいですが、どういうところと連携を取ってやっていくかというのが１つ。もう一つは、お子さんが支援が必要。そのお子さんを預けたいという場合、受け入れる側の対応は、どのようなところと連携をして受け入れていくのでしょうかということです。ご家庭で支援が必要な場合と、お子さんが発達で特別な支援が必要な場合ですけれど、その２つの場合です。","respondent":"石井保育支援課長","answer":"今回、私立保育園で実施するということですので、そういった通常保育園で行える支援についても、このモデル事業において受けられるものであると承知しております。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"していただくと、この事業もよりよくなると思います。逆に預けていらっしゃらないご家庭の方の状況が、これに預けることによって把握できたり、また、指導と言ったら失礼ですけれど療育・教育できると思うので、今お話があったように、ぜひほかの機関との協力をお願いしたいと。そちらの私立認可保育園の先ほどあった巡回保育を行って協力するのももちろんお願いしたいのですが、そちらのほうはどうでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"これを機会に拡大をという。すみません。質問の言い方が悪かったです。","respondent":"石井保育支援課長","answer":"現在、臨床心理士の先生や学校心理士の先生にご協力いただきながらこの事業を実施しておりますので、そういったところで課題を共有しながら、事業をよりよくしていきたいと考えています。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"支援が必要なお子さんは、支援計画をつくらなければいけなくなると思うのです。そうすると、保育士さんなり、あるいは巡回していく心理士の先生方と協力をして支援計画をつくるというのは、実は非常に大変な労力がかかります。でも、つくっていただかなければいけないので、そこの支援計画については、しっかりとやっていただきたいと思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"何点か質問させていただきたいと思います。１つ目が、都立特別支援学校給食費補助事業についてです。複数回にて行われるのか、お聞きしたいと思います。保護者への周知の方法として個別案内とありますが、具体的にはどういった形を取られるのか。問合せがあれば答える形なのかどうか、お聞きしたいと思います。今後、年齢幅の拡充の検討があるのであれば、お聞きしたいと思います。","respondent":"柏木学務課長、飛田子育て応援課長、石井保育支援課長","answer":"私からは、特別支援学校の給食費の件についてお答えいたします。質問を２ついただきました。１つ目が支給回数です。支給は７月中ということでこちらに記載しておりますが、この後、対象者や申込みの確認をいたしますので、７月３１日までには支給すると考えております。恐らくこういった支援の必要な方々はかなりの数に上るのではないかと考えてございまして。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"意見","question":"未来としても賛成なのですが、少しだけ意見を言わせてください。区が一生懸命いろいろな支援の制度をつくったことによって、どれをどう選んで、どれをどう申請したらいいのかが分かりにくくなっているということが、やはり子育て、児童福祉についても言えるのかなと思います。以上の意見をもちまして、でも内容としては必要な補正だと思いますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"必要な内容ですし、今回の補正には、給付金や学校給食の無償化など、国や都がやらなくても、またやらない部分について単費を入れて区独自に支援するという項目も入っているということは、すごく重要だなと思っています。さらに拡充していただきたいと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区長と教育長が、記者会見で補正予算とともに発表した区立学校でのいじめの重大事態について、大変重要な問題なので文教委員会で報告してほしいと思います。いつ報告されるのか、伺いたいと思います。","respondent":"米田教育次長","answer":"学校におけるいじめの重大事態の認定が遅れましたことにつきましては、この場でも重ねておわびを申し上げたいと思います。その上で、次回の文教委員会の場できちんと改めて報告をさせていただければと考えているところです。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246913?Template=document&Id=5096#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":21772,"voices":100}},{"id":"r05-20230529-5","meetingId":"r05-cm05","date":"2023年5月29日","dateIso":"2023-05-29","committee":"総務委員会","time":"午前１０時００分～午前１０時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和５年度品川区一般会計補正予算","agenda":"第３１号議案、令和５年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ご説明ありがとうございました。金曜日に、既に所管で議論がされて、先ほど、全会一致で採決されたという報告が委員長からありましたけれども、改めて確認させていただきたい点がありますので、幾つか伺いたいと思います。一つ伺いたいのは、いわゆる６月議会ではなくて、臨時会にかけた理由、そこをご説明いただきたいと思っています。なぜ、６月ではなくて、この臨時会のタイミングでかけたのか。","respondent":"遠藤財政課長","answer":"今回の補正予算ですけれども、いわゆる区民の生活などや事業者の支援というところで、新型コロナウイルス感染症対応地方創生臨時交付金、こちらをどう使うかというのが中心になってくるメニューです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"一刻も早くというのは、それはそのとおりだと私も思います。そこで伺いたいのは、コロナ対策で、総務部がコロナの本部としてこの３年間動いてきたと思うのですけれども、今もその本部はあるのか、もう解散してしまったのか。今後のことを見通すことは、科学的に、もちろん私だって限界はありますけれども、そういう十分な警戒をする姿勢というのは持ち続けるべきだと思うのですけれども、いかがでしょうか。","respondent":"遠藤財政課長、勝亦総務課長","answer":"当然、国等の改めてのモニタリングとかいろいろな部分が出てくるかと思いますけれども、当然その事情によってというか状況によって、こちらも対応することはあるかと思うのですが。コロナの本部会議ですけれども、今般の５類への移行に伴いまして、国・都の本部会議が終了したことに伴いまして、区のほうでも終了しています。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここまで来ると、いよいよ区立についても都立についても、学校給食費の財源について、しっかり東京都と国に対して求めていくということが品川区として必要ではないかと思うのですが、その姿勢を伺いたいのと、特に都立特別支援学校は、やはり、東京都自身が、小池都知事自身が決断をして、この都立特別支援学校も東京都の責任で給食費を無償化にすると、その決断を品川区としても求めていく。","respondent":"遠藤財政課長","answer":"ですので、いわゆる拡大分につきましては、どちらも一般財源を入れて実施するという形になっているところです。それと、省エネルギー対策設備更新助成金ですけれども、こちらのほうは今、５分の４ということでかなり率の高いものにさせていただいているところです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"省エネルギー対策設備更新助成ですけれど、確かに１００万円のものを買って８０万円の助成が来るというのは思い切った仕組みだと、私は評価しております。学校給食についても、国や東京都について注視するということですけれども、品川区でここまで、言わば押してきたわけですから、しっかり財源についても、都立についても、国や東京都に対して意見を上げていただきたいと要望して終わりたいです。","respondent":"佐藤（憲）企画課長","answer":"すみません、学校給食費の無償化に係る財源措置ですが、特別区長会を通じて国や都に予算の要望をする機会がありますので、学校給食費の無償化の財源に関しましては、品川区から国へ要望を出すというのを今、事務作業を進めているところです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"本当に、非課税世帯の方もいらっしゃるのですが、そのほかに、やはり年金生活者、それから非正規雇用、それから、まだまだ給料が安い若年者層の皆さんは、これだけエネルギー価格が高騰しているなら、相当生活が厳しいのではないかと思うのですが、非課税世帯も大切だと思うのですけれど、やはりそういう人たちにも支援の枠というのを考えていくべきだと私は思うのですが、その辺、都の見解。","respondent":"遠藤財政課長","answer":"児童参加地域事業補助、新規事業定着化補助は、事業に対して配付するということですけれども、私どものほうでも、いわゆる一律に町会に配るという話も当然、検討の中で上がったところです。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどの町会に戻りますけれど、ここ約３年余りほとんど活動ができていない中で、町会費というのは、やはり収入として得ているのです。それから、あと、やはり物価急騰して、それぞれ大変な状況にある、そういう低所得者層というのは非課税世帯だけではないので、ここはやはり、国、都にしっかり意見を言っていただきたいと私は思います。区も、加えて、できるだけの支援を私は要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"少し具体的な話でお伺いしたいのが、ヘルメットのところなのですけれども、これ、東京都は２,０００円の半分ですか、半額を補助するというような話で言っていたかと思うのですが、この予算のほうを見ると、実際には、都支出金が４００万円で、では実際の一般財源でどのくらい出ているかといったら、２,０００万円ですか。","respondent":"遠藤財政課長","answer":"自転車用ヘルメット購入費助成の区の財源ですけれども、こちら東京都の上限が４００万円という形になっているので、残りは一般財源という形で計上させていただいたものです。","id":"exchange-007"},{"speaker":"松本委員","kind":"確認","question":"ではこれは、個数としては都の上限では全然足りなかったということかと思います。というのを確認と、区としてはどのくらいの個数を念頭に置いているのかお願いいたします。","respondent":"遠藤財政課長","answer":"要は、東京都の補助金は２分の１で４００万円ですので、ただ、区のほうとしてはもう少し、具体的には先ほどありました１万人分、１万個を考えております。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"なので、ここの部分を品川区としてしっかりと出していただいているのは、これはやはり、我々も自転車の事故というのは周りでよく起こっていますので、ここの部分は、東京都は残念ながら、４００万円というところが上限であったにもかかわらず、１万人分、それを対応していただいたのはとてもありがたいなというところで、ここはおおむねご評価させていただいて、私のほうの質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えばこれ、町会・自治会があるけれども、では高齢者クラブどうなのと。高齢者クラブ、ではシルバー大学どうなのと。そうすると第２回定例会、第３回定例会。基金の部分は。こういうのが出てくるなら、本当介護だ何だと全部、高齢者クラブだって、二転三転で出てきていいのですか、みたいな話になるような気がしてならないのです。そう思っているのですけれど、その辺の考え方をまず教えてほしいです。","respondent":"遠藤財政課長","answer":"コロナ以降、特に補正予算は多くのものをやっていたと。以前はほかの仕事ができないので、例えば、ワクチンのほうに多く回しますとかということができていたわけです。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"別にこれはこれでいいのだけれど、金額が変な話、５４０万円ぐらいで、これ５４０万円だったら、別に流用だって何だって遡ったって何だってやれるわけではないですか、これぐらいなら。皆さんも大変なのかもしれないけれど、多分、私は職員の方々をもっともっとやる気にするべきことがたくさんあるような気がしてならないので、それだけはお願いしておきます。それでやめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"塚本副委員長","kind":"質問","question":"ではどこに対して、今回、いろいろな幾つかの拡大があるわけですけれど、これを決めていく中での区の基本的な考え方とか議論も、どんな議論があって、今回、区独自としては、こういうところに力を、補正予算として組みましょうとなっていったのかというところをお伺いしたいと思います。","respondent":"遠藤財政課長","answer":"委員がお話しされたとおり、今回は地方創生臨時交付金が国のほうから、東京都のほうからいただけるというところがありますので、やはり一番の、例えば、前回１２月の補正でもやらせていただいた。","id":"exchange-012"},{"speaker":"塚本副委員長","kind":"質問","question":"要するに対象を絞らず全ての区民に、というのを物価高対策としてです。もしそれを、やろうとはしたのだけれどもできない、やはり財源的な問題があるのだということであれば、その点も含めてお伺いしたいと思います。","respondent":"久保田企画部長","answer":"そうした中で、今回は、均等割のみ課税の世帯ということで拡大をさせていただいたのですが、今、副委員長のほうからもお話がありましたように、全体的にも必要かどうかというような検討もしたところですが、しながわ活力応援給付金、令和２年度に出させていただきましたけれども。","id":"exchange-013"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"幅広く、議論を、検討をしていただいたというような経緯は分かったので、ここは承知いたしました。今後とも、また、物価高、どこまで続くかというところが見えないところですので、適宜、適切に、我々としてもいろいろ議論をさせていただきたいと思います。今後ともそういった対応については、しっかりと対応していただけるようにお願いさせていただいて、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の補正は、一歩でも二歩でも支援する中身として賛成いたしますが、さらなる支援を、追加を求めたいと思います。給付金についても、引き続き、繰り返し実施し、対象についても拡大していただきたい。品川区の積極的な財政出動を改めて求めたいと思います。国に対して必要な財源や対策を求めていく。東京都に対しても必要な財源や対策を求めていく。そうした姿勢もあわせて要望して、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回の議案に関しては賛成しますが、やはり区がこういう補正予算を出してきたということに対して、やはり区民としては納得できない方もたくさんいらっしゃると私は思います。ぜひ、やはり区のメンツもありますから、都や国にしっかり、やはりおかしいことはおかしいとはっきり明言して、私は様々な要望をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166654?Template=document&Id=2264#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":19075,"voices":48}},{"id":"r05-20230529-10","meetingId":"r05-cm05","date":"2023年5月29日","dateIso":"2023-05-29","committee":"議会運営委員会","time":"午後 ０時５０分～午後 ０時５３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5504#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1266,"voices":10}}]);
